/* ===== JS originale 4/107: preview-network-guard-v45 ===== */

(() => {
  'use strict';

  const ua = String(navigator.userAgent || '');
  const platform = String(navigator.platform || '');
  const touchPoints = Number(navigator.maxTouchPoints || 0);
  const protocol = String(location.protocol || '').toLowerCase();

  const isIPad = /iPad/i.test(ua) || (platform === 'MacIntel' && touchPoints > 1);
  const isIOS = isIPad || /iPhone|iPod/i.test(ua);
  const isEdgeIOS = /EdgiOS/i.test(ua);
  const isWindows = /Windows/i.test(ua) || /^Win/i.test(platform);
  const localDocument = protocol === 'file:' || protocol === 'blob:' || protocol === 'content:' || protocol === 'edge:' || protocol === 'ms-appx-web:';

  window.__DASHBOARD_IPAD__ = isIPad;
  window.__DASHBOARD_IOS__ = isIOS;
  window.__DASHBOARD_EDGE_IOS__ = isEdgeIOS;
  const isAndroid = /Android/i.test(ua);
  window.__DASHBOARD_WINDOWS__ = isWindows;
  window.__DASHBOARD_ANDROID__ = isAndroid;
  window.__DASHBOARD_LOCAL_FILE__ = localDocument;
  window.__DASHBOARD_LOCAL_LIKE__ = localDocument;

  // FIX ANTEPRIMA:
  // non applicare CSP locale e non bloccare fetch/XHR/WebSocket.
  window.__DASHBOARD_PREVIEW_SAFE_MODE__ = false;
  // V315: Progressive initialization everywhere. Avoid dozens of hidden
  // chart canvases/indicators competing for Safari, Android and desktop GPU RAM.
  // Every selected market still creates its full chart + every indicator.
  window.__DASHBOARD_IPAD_SINGLE_MARKET__ = true;
  window.__DASHBOARD_LAZY_MARKET_RENDER_V315__ = true;
  document.documentElement.dataset.chartEngineMode = 'progressive-v316';
  window.__DASHBOARD_SMOOTH_V316__ = true;
})();


