/* ===== JS originale 8/107: ipad-safari-compat-v43 ===== */

(() => {
  'use strict';
  const ua = String(navigator.userAgent || '');
  const platform = String(navigator.platform || '');
  const isIPad = /iPad/i.test(ua) || (platform === 'MacIntel' && Number(navigator.maxTouchPoints || 0) > 1);
  if (!isIPad) return;

  document.documentElement.classList.add('ipad-device');
  window.__DASHBOARD_IPAD_OPTIMIZED__ = true;

  // iPad 6 FIX: non installare subito il fallback Canvas su file://.
  // Prima il boot principale prova Lightweight Charts dai CDN; il Canvas incorporato
  // resta come fallback solo se i CDN non sono raggiungibili.
  const installLocalChartEngine = () => {
    const local = location.protocol === 'file:' || location.protocol === 'blob:';
    if (!local || window.LightweightCharts || typeof window.__installLightweightChartsFallback !== 'function') return;
    if (!window.__DASHBOARD_ALLOW_IPAD_CANVAS_FALLBACK__) return;
    try {
      if (window.__installLightweightChartsFallback()) {
        document.documentElement.classList.add('ipad-local-chart-engine');
      }
    } catch (_) {}
  };
  // Profilo hardware iPad. iPad Pro 12,9" (viewport 1024x1366 CSS) non va
  // trattato come il vecchio iPad 6/A10: mantiene DPR e timeout completi.
  const screenShortSide = Math.min(Number(screen?.width || 0), Number(screen?.height || 0));
  const screenLongSide = Math.max(Number(screen?.width || 0), Number(screen?.height || 0));
  const isLargeIpadPro = screenShortSide >= 1000 && screenLongSide >= 1300;
  window.__DASHBOARD_IPAD_PRO_12_9__ = isLargeIpadPro;
  // Il browser non espone il chip: nessuna classificazione M2 dalla sola risoluzione.
  window.__DASHBOARD_IPAD6_LITE__ = false;
  window.__DASHBOARD_ALL_MARKET_FEEDS__ = true;
  // Anche sul Pro teniamo un solo mercato/grafico pienamente attivo: su iPadOS tutti
  // i browser usano WebKit e questo riduce sospensioni, memoria e socket inutili.
  window.__DASHBOARD_IPAD_SINGLE_MARKET__ = true;
  window.__DASHBOARD_IPAD6_EDGE__ = /EdgiOS/i.test(ua);
  window.__DASHBOARD_REDUCE_BACKGROUND_STREAMS__ = false;
  document.documentElement.dataset.ipad6Fix = isLargeIpadPro ? 'ipad-pro-12-9-edge-live-v5' : 'edge-live-v3';
  document.documentElement.dataset.ipadBrowser = window.__DASHBOARD_IPAD6_EDGE__ ? 'edge-ios' : 'webkit-ios';
  document.documentElement.dataset.ipadProfile = isLargeIpadPro ? 'pro-12-9' : 'lite';

  const bindTouchFallbacks = () => {
    // Safari normalmente genera click dal touch; questo fallback rende affidabili
    // i due pulsanti tema anche dentro WebView iPad che sopprimono il click sintetico.
    ['themeLight', 'themeNight'].forEach(id => {
      const el = document.getElementById(id);
      if (!el || el.dataset.ipadTouchBound === '1') return;
      el.dataset.ipadTouchBound = '1';
      el.addEventListener('touchend', event => {
        event.preventDefault();
        el.click();
      }, { passive:false });
    });
  };

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', bindTouchFallbacks, { once:true });
  } else {
    bindTouchFallbacks();
  }

  // Quando Safari ripristina la scheda dalla back-forward cache, forza un resize
  // dei Canvas e un evento online per riattivare i poller sospesi da iPadOS.
  window.addEventListener('pageshow', () => {
    installLocalChartEngine();
    window.setTimeout(() => {
      try { window.dispatchEvent(new Event('resize')); } catch (_) {}
      if (navigator.onLine) {
        try { window.dispatchEvent(new Event('online')); } catch (_) {}
      }
    }, 120);
  }, { passive:true });
})();


