/* ===== JS originale 11/107: platform-universal-v94 ===== */

(() => {
  try {
    const ua = String(navigator.userAgent || '');
    const p = String(navigator.platform || '');
    const touch = Number(navigator.maxTouchPoints || 0);
    const apple = /iPhone|iPad|iPod|Macintosh|MacIntel/i.test(ua + ' ' + p) || (p === 'MacIntel' && touch > 1);
    const android = /Android/i.test(ua);
    const windows = /Windows/i.test(ua) || /^Win/i.test(p);
    document.documentElement.classList.toggle('platform-apple-v94', apple);
    document.documentElement.classList.toggle('platform-android-v94', android);
    document.documentElement.classList.toggle('platform-windows-v94', windows);
    document.documentElement.dataset.universalBuild = 'v94';
  } catch (_) {}
})();


