/* ===== JS originale 12/107: v174-luna-burn-order ===== */

(()=>{function fix(){
 if(!matchMedia('(max-width:767px)').matches)return;
 const els=[...document.querySelectorAll('div,section,article')];
 const score=(e,re)=>re.test((e.textContent||'').trim())&&e.children.length<15;
 const d=els.find(e=>score(e,/BURN LUNA OGGI[\s\S]*PHOENIX-1/i));
 const t=els.find(e=>score(e,/TOTALE LUNA AL BURN ADDRESS[\s\S]*PHOENIX-1/i));
 if(!d||!t||d===t)return;
 let p=d.parentElement;
 if(!p||!p.contains(t)){p=t.parentElement;if(!p||!p.contains(d))return;}
 p.classList.add('v174-luna-burn-stack');d.classList.add('v174-luna-burn-card');t.classList.add('v174-luna-burn-card');
 if(d.nextElementSibling!==t)p.insertBefore(d,t);
}
document.addEventListener('DOMContentLoaded',fix,{once:true});addEventListener('pageshow',fix);addEventListener('resize',fix,{passive:true});setTimeout(fix,400);
})();


