/* ===== JS originale 13/107: v278-total-defi-same-size-as-total-script ===== */

(() => {
  'use strict';
  if (window.__TOTAL_DEFI_SAME_SIZE_V278__) return;
  window.__TOTAL_DEFI_SAME_SIZE_V278__ = true;

  function syncTotalDefiSize(){
    const total = document.getElementById('globalTotalPill');
    const defi = document.getElementById('globalTotalDefiPill');
    if(!total || !defi) return;

    const width = Math.round(total.getBoundingClientRect().width);
    const height = Math.round(total.getBoundingClientRect().height);
    if(width > 0){
      defi.style.width = width + 'px';
      defi.style.minWidth = width + 'px';
      defi.style.maxWidth = width + 'px';
      defi.style.flex = '0 0 ' + width + 'px';
    }
    if(height > 0){
      defi.style.minHeight = height + 'px';
      defi.style.height = height + 'px';
    }
  }

  let ro = null;
  function init(){
    syncTotalDefiSize();
    const total = document.getElementById('globalTotalPill');
    if(window.ResizeObserver && total && !ro){
      ro = new ResizeObserver(() => syncTotalDefiSize());
      ro.observe(total);
    }
    setTimeout(syncTotalDefiSize, 60);
    setTimeout(syncTotalDefiSize, 240);
  }

  if(document.readyState === 'loading'){
    document.addEventListener('DOMContentLoaded', init, {once:true});
  } else {
    init();
  }
  window.addEventListener('resize', syncTotalDefiSize, {passive:true});
  window.addEventListener('orientationchange', syncTotalDefiSize, {passive:true});
  window.addEventListener('pageshow', syncTotalDefiSize, {passive:true});
  window.addEventListener('load', syncTotalDefiSize, {passive:true});
})();


