/* ===== JS originale 14/107: v279-total-defi-readable-trend-script ===== */

(() => {
  'use strict';
  if (window.__TOTAL_DEFI_READABLE_TREND_V279__) return;
  window.__TOTAL_DEFI_READABLE_TREND_V279__ = true;

  function ensureReadable(){
    const pill = document.getElementById('globalTotalDefiPill');
    const trend = document.getElementById('globalTotalDefiTrend');
    const label = pill && pill.querySelector('.global-marketcap-pill-label');
    const value = document.getElementById('globalTotalDefiValue');
    if(!pill || !trend || !label || !value) return;

    trend.style.flex = '0 0 auto';
    trend.style.overflow = 'visible';
    trend.style.textOverflow = 'clip';
    trend.style.whiteSpace = 'nowrap';

    // Se lo spazio è molto stretto, compatta solo label e valore; il trend resta sempre completo.
    const available = pill.clientWidth;
    if(available > 0 && pill.scrollWidth > available){
      label.style.fontSize = '6.6px';
      value.style.fontSize = '8px';
      pill.style.gap = '1px';
      pill.style.paddingLeft = '5px';
      pill.style.paddingRight = '5px';
    } else {
      label.style.removeProperty('font-size');
      value.style.removeProperty('font-size');
    }
  }

  function run(){
    ensureReadable();
    requestAnimationFrame(ensureReadable);
    setTimeout(ensureReadable, 80);
    setTimeout(ensureReadable, 260);
  }

  if(document.readyState === 'loading') document.addEventListener('DOMContentLoaded', run, {once:true});
  else run();
  window.addEventListener('resize', run, {passive:true});
  window.addEventListener('orientationchange', run, {passive:true});
  window.addEventListener('pageshow', run, {passive:true});
  window.addEventListener('load', run, {passive:true});
  window.addEventListener('dashboard-pill-update', run, {passive:true});
})();


