/* ===== JS originale 16/107: v304-long-short-both-right-left-script ===== */

(() => {
  'use strict';
  if (window.__LONG_SHORT_V304__) return;
  window.__LONG_SHORT_V304__ = true;

  const STEP_MS = 520;
  let step = 0;
  let timer = 0;

  function dotsRTL(row, groupSelector){
    return Array.from(row.querySelectorAll(groupSelector + ' .ls-dot-v260')).reverse();
  }

  function clearV304(row){
    row.querySelectorAll('.ls-dot-v260').forEach(dot => {
      dot.classList.remove('v304-dot-active');
    });
  }

  function renderV304(){
    document.querySelectorAll('.long-short-compact-v257').forEach(row => {
      clearV304(row);
      const green = dotsRTL(row, '.ls-dots-long-v260');
      const red = dotsRTL(row, '.ls-dots-short-v260');
      if (green.length) green[step % green.length].classList.add('v304-dot-active');
      if (red.length) red[step % red.length].classList.add('v304-dot-active');
    });
    step = (step + 1) % 5;
  }

  function startV304(){
    if (timer) window.clearInterval(timer);
    renderV304();
    timer = window.setInterval(renderV304, STEP_MS);
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', startV304, {once:true});
  } else {
    startV304();
  }

  window.addEventListener('pageshow', () => setTimeout(startV304, 60), {passive:true});
  window.addEventListener('focus', () => setTimeout(startV304, 60), {passive:true});
  document.addEventListener('visibilitychange', () => {
    if (!document.hidden) setTimeout(startV304, 60);
  }, {passive:true});
})();


