          waitingTick: 'Esperando el primer tick…', waiting: '● EN ESPERA', fullInfo: 'Información completa', burnTitle: 'Burn', burnTotal: 'Total quemado', burnLatestEpoch: 'Burn de la última época', burnToday: 'Burn de hoy', burn7d: 'Burn de 7 días', burn30d: 'Burn de 30 días', burnUpdating: 'Actualizando burn…', burnLive: 'Datos burn actualizados', burnPartial: 'Total on-chain · recopilando historial', burnSource: 'Fuente', cursorPrice: 'Precio en el cursor', open: 'Apertura', close: 'Cierre',
          connecting: 'Conectando…', switchingPolling: 'Cambiando a sondeo…', livePolling: 'En vivo · sondeo', dataUnavailable: 'Datos no disponibles', offline: 'Sin conexión', libraryMissing: 'Biblioteca del gráfico no disponible',
