      let lastPriceHapticAt = 0;
      let priceHapticMessageTimer = 0;

      function showPriceHapticStatus(message) {
        const state = $('priceVisibilityState');
        if (!state) return;
        window.clearTimeout(priceHapticMessageTimer);
        state.textContent = message;
        priceHapticMessageTimer = window.setTimeout(() => {
          state.textContent = t(pricesVisible ? 'visible' : 'hidden');
        }, 1800);
      }

      function vibratePriceToggle() {
        const now = Date.now();
        if (now - lastPriceHapticAt < 350) return true;
        lastPriceHapticAt = now;

        try {
          if (typeof navigator === 'undefined' || typeof navigator.vibrate !== 'function') {
            showPriceHapticStatus('Vibrazione non supportata dal browser');
            return false;
          }

          if (document.visibilityState !== 'visible') {
            showPriceHapticStatus('Apri la pagina in primo piano');
            return false;
          }

          // Impulso medio eseguito direttamente durante la pressione dell'utente.
          // Vibrazione media eseguita durante il gesto diretto dell'utente.
          navigator.vibrate(0);
          const accepted = navigator.vibrate(140);
          if (accepted === false) {
            showPriceHapticStatus('Vibrazione bloccata dal browser');
            return false;
          }
          return true;
        } catch (_) {
          showPriceHapticStatus('Vibrazione bloccata dal browser');
          return false;
        }
      }

      function applyPriceVisibility() {
        document.body.classList.toggle('prices-hidden', !pricesVisible);
        $('priceVisibilityToggle').checked = !pricesVisible;
        $('priceVisibilityLabel').textContent = t(pricesVisible ? 'showPrices' : 'hidePrices');
        $('priceVisibilityState').textContent = t(pricesVisible ? 'visible' : 'hidden');
        document.querySelectorAll('.price, .asset-tab-quote > strong, .quote .change, .direction-alert, .threshold-price-value, .ema-item strong, .chart-tooltip strong').forEach(element => {
          element.setAttribute('aria-hidden', String(!pricesVisible));
        });
        if (!pricesVisible) {
          document.querySelectorAll('.chart-tooltip').forEach(tooltip => {
            tooltip.classList.remove('visible');
            tooltip.setAttribute('aria-hidden', 'true');
          });

          // Rimuove subito ogni indicazione live di salita/discesa.
          document.querySelectorAll('.asset-tab.live-up, .asset-tab.live-down').forEach(tab => {
            tab.classList.remove('live-up', 'live-down');
            tab.title = 'Prezzo nascosto';
          });

          document.querySelectorAll('.direction-alert').forEach(alert => {
            alert.className = 'direction-alert neutral';
            alert.textContent = '● ••••';
            alert.setAttribute('aria-hidden', 'true');
          });

          document.querySelectorAll('.asset-tab.live-upper').forEach(tab => { tab.title = 'Upper 20/2 raggiunto'; });
        } else {
          document.querySelectorAll('.direction-alert').forEach(alert => {
            alert.setAttribute('aria-hidden', 'false');
          });
        }
        Object.entries(charts).forEach(([symbol, { chart, candles, emaSeries }]) => {
          chart.applyOptions({ leftPriceScale: { visible: false }, rightPriceScale: { visible: true, borderVisible: true, minimumWidth: 92, entireTextOnly: true } });
          candles.applyOptions({ lastValueVisible: false, priceLineVisible: false, priceLineStyle: 2, priceLineWidth: 1 });
          if (pricesVisible && Number.isFinite(Number(lastPrices[symbol]))) scheduleLivePriceLineV73(symbol, Number(lastPrices[symbol]));
          else {
            if (charts[symbol]?.livePriceLineV73) charts[symbol].livePriceLineV73.style.display = 'none';
            if (charts[symbol]?.livePriceLabelV75) charts[symbol].livePriceLabelV75.style.display = 'none';
          }
          Object.entries(emaSeries).forEach(([, series]) => {
            // V132 — tutte le EMA usano solo il badge custom (o quello unico del fallback).
            series.applyOptions({
              lastValueVisible: false,
              priceLineVisible: false
            });
          });
        });
      }

      function applyDashboardBrightness() {
        const rawBrightness = Number(dashboardBrightness);
        const normalized = Number.isFinite(rawBrightness) ? Math.min(100, Math.max(0, Math.round(rawBrightness))) : 100;
        dashboardBrightness = normalized;
        // Anche a 0% mantiene circa il 30% di luminosità reale: il sito resta scuro,
        // ma tutti gli elementi rimangono chiaramente visibili.
        const minimumVisibleBrightness = 0.30;
        const visibleBrightness = minimumVisibleBrightness + (normalized / 100) * (1 - minimumVisibleBrightness);
        document.documentElement.style.setProperty('--dashboard-dim-opacity', (1 - visibleBrightness).toFixed(3));
        const input = $('brightnessRange');
        const output = $('brightnessValue');
        if (input) input.value = String(normalized);
        if (output) {
          output.value = `${normalized}%`;
          output.textContent = `${normalized}%`;
        }
      }

      function calculateAdaptiveBrightness(date = new Date()) {
        const hour = date.getHours() + date.getMinutes() / 60;
        let target;
        if (hour >= 7 && hour < 18) target = 100;
        else if (hour >= 18 && hour < 21) target = 92;
        else if (hour >= 21 && hour < 23) target = 89;
        else if (hour >= 6 && hour < 7) target = 90;
        else target = 86;

        // Il tema chiaro richiede un piccolo margine in più per mantenere leggibilità.
        if (isLight()) target += 5;
        return Math.min(100, Math.max(0, Math.round(target)));
      }

      function syncAdaptiveBrightnessControl() {
        const toggle = $('adaptiveBrightnessToggle');
        const input = $('brightnessRange');
        const state = $('adaptiveBrightnessState');
        if (toggle) {
          toggle.checked = adaptiveBrightnessEnabled;
          toggle.setAttribute('aria-checked', String(adaptiveBrightnessEnabled));
        }
        if (input) input.disabled = adaptiveBrightnessEnabled;
        if (state) state.textContent = t(adaptiveBrightnessEnabled ? 'adaptiveOn' : 'adaptiveOff');
      }

      function refreshAdaptiveBrightness() {
        dashboardBrightness = adaptiveBrightnessEnabled
          ? calculateAdaptiveBrightness()
          : manualDashboardBrightness;
        applyDashboardBrightness();
        syncAdaptiveBrightnessControl();
      }

      function scheduleAdaptiveBrightness() {
        if (adaptiveBrightnessTimer) window.clearInterval(adaptiveBrightnessTimer);
        adaptiveBrightnessTimer = null;
        if (!adaptiveBrightnessEnabled) return;
        adaptiveBrightnessTimer = window.setInterval(refreshAdaptiveBrightness, 60 * 1000);
      }

      function setAdaptiveBrightness(enabled) {
        adaptiveBrightnessEnabled = Boolean(enabled);
        writeLocalPreference('crypto-dashboard-adaptive-brightness', String(adaptiveBrightnessEnabled));
        refreshAdaptiveBrightness();
        scheduleAdaptiveBrightness();
      }

      function chartColors() {
        const auroraMode = document.body.classList.contains('aurora');
        const soleMode = document.body.classList.contains('sole');
        const violaMode = document.body.classList.contains('viola');
        if (auroraMode) {
          return isLight()
            ? { bg: '#f8fffd', text: '#547377', grid: '#d5ebe7', border: '#9bcfc7' }
            : { bg: '#061a20', text: '#9cc8cb', grid: '#143941', border: '#24675f' };
        }
        if (soleMode) {
          return isLight()
            ? { bg: '#fffdf4', text: '#765d2c', grid: '#f0dfb3', border: '#d9b95c' }
            : { bg: '#1a1207', text: '#d6bb7d', grid: '#3b2a10', border: '#7a5b1d' };
        }
        if (violaMode) {
          return isLight()
            ? { bg: '#fcf8ff', text: '#6b4e8f', grid: '#e5d9f3', border: '#bea3e6' }
            : { bg: '#170b22', text: '#c9b1ee', grid: '#332046', border: '#6d44a9' };
        }
        return isLight()
          ? { bg: '#ffffff', text: '#687385', grid: '#e8ebf0', border: '#dfe4eb' }
          : { bg: '#101319', text: '#8f99a8', grid: '#1d222b', border: '#242a34' };
      }

      function getTimeframeConfig() {
        return TIMEFRAME_CONFIG[interval] || TIMEFRAME_CONFIG.MAX;
      }

      function keepsAllLoadedCandles(selection = getTimeframeConfig()) {
        return Boolean(selection.fullHistory || selection.progressiveHistory);
      }

      function timeframeBucketStart(timestamp, bucket) {
        if (bucket.unit === 'week') {
          // Settimane allineate a lunedì 00:00 UTC. Per 2W vengono unite due settimane consecutive.
          const secondsPerWeek = 7 * 86400;
          const mondayEpoch = 4 * 86400; // 1970-01-05 00:00 UTC
          const weekIndex = Math.floor((timestamp - mondayEpoch) / secondsPerWeek);
          const bucketWeek = Math.floor(weekIndex / bucket.size) * bucket.size;
          return mondayEpoch + bucketWeek * secondsPerWeek;
        }
        if (bucket.unit === 'month') {
          const date = new Date(timestamp * 1000);
          const monthIndex = date.getUTCFullYear() * 12 + date.getUTCMonth();
          const bucketMonth = Math.floor(monthIndex / bucket.size) * bucket.size;
          const year = Math.floor(bucketMonth / 12);
          const month = bucketMonth % 12;
          return Math.floor(Date.UTC(year, month, 1) / 1000);
        }
        return Math.floor(timestamp / bucket.size) * bucket.size;
      }

      function aggregateCandles(rows, bucket, maxItems = 300) {
        const ordered = rows
          .filter(row => [row.time, row.open, row.high, row.low, row.close].every(Number.isFinite))
          .slice()
          .sort((a, b) => a.time - b.time);
        const result = [];

        ordered.forEach(row => {
          const time = timeframeBucketStart(row.time, bucket);
          const volume = Number.isFinite(row.volume) ? row.volume : 0;
          const current = result[result.length - 1];
          if (current && current.time === time) {
            current.high = Math.max(current.high, row.high);
            current.low = Math.min(current.low, row.low);
            current.close = row.close;
            current.volume += volume;
          } else {
            result.push({
              time,
              open: row.open,
              high: row.high,
              low: row.low,
              close: row.close,
              volume
            });
          }
        });

        return Number.isFinite(maxItems) ? result.slice(-maxItems) : result;
      }

      function buildTopBottomMarkers(candles) {
        const markers = [];
        if (!Array.isArray(candles) || candles.length < 8) return markers;

        // Un pivot viene mostrato soltanto dopo almeno 3 candele chiuse di conferma.
        // Se il movimento continua, l'etichetta viene aggiornata a 4 o 5 conferme.
        for (let i = 2; i < candles.length - 3; i += 1) {
          const pivot = candles[i];
          const leftTop = pivot.high > candles[i - 1].high && pivot.high >= candles[i - 2].high;
          const leftBottom = pivot.low < candles[i - 1].low && pivot.low <= candles[i - 2].low;

          let topConfirmations = 0;
          let bottomConfirmations = 0;
          const maxConfirmation = Math.min(5, candles.length - i - 1);

          for (let n = 1; n <= maxConfirmation; n += 1) {
            const next = candles[i + n];
            if (next.high < pivot.high) topConfirmations = n;
            else break;
          }

          for (let n = 1; n <= maxConfirmation; n += 1) {
            const next = candles[i + n];
            if (next.low > pivot.low) bottomConfirmations = n;
            else break;
          }

          if (leftTop && topConfirmations >= 3) {
            markers.push({
              time: pivot.time,
              position: 'aboveBar',
              color: '#ff5f6d',
              shape: 'arrowDown',
              text: 'TOP ' + Math.min(topConfirmations, 5)
            });
          }

          if (leftBottom && bottomConfirmations >= 3) {
            markers.push({
              time: pivot.time,
              position: 'belowBar',
              color: '#18c683',
              shape: 'arrowUp',
              text: 'BOTTOM ' + Math.min(bottomConfirmations, 5)
            });
          }
        }

        return markers.sort((a, b) => a.time - b.time);
      }

      const EMA_CROSS_PAIRS = [
        [15, 20], [15, 50], [15, 200],
        [20, 50], [20, 200], [50, 200]
      ];

      function buildEmaCrossEvents(candles) {
        if (!Array.isArray(candles) || candles.length < 2) return [];

        const emaMaps = {};
        EMA_CONFIG.forEach(({ period }) => {
          const map = new Map();
          calculateEMA(candles, period).forEach(point => {
            if (point && Number.isFinite(Number(point.time)) && Number.isFinite(Number(point.value))) {
              map.set(Number(point.time), Number(point.value));
            }
          });
          emaMaps[period] = map;
        });

        const events = [];
        EMA_CROSS_PAIRS.forEach(([fastPeriod, slowPeriod]) => {
          const fast = emaMaps[fastPeriod];
          const slow = emaMaps[slowPeriod];
          if (!fast || !slow) return;

          let previous = null;
          candles.forEach(candle => {
            const time = Number(candle?.time);
            if (!Number.isFinite(time) || !fast.has(time) || !slow.has(time)) return;
            const fastValue = Number(fast.get(time));
            const slowValue = Number(slow.get(time));
            if (!Number.isFinite(fastValue) || !Number.isFinite(slowValue)) return;
            const diff = fastValue - slowValue;

            if (previous) {
              const crossedUp = previous.diff <= 0 && diff > 0;
              const crossedDown = previous.diff >= 0 && diff < 0;
              if (crossedUp || crossedDown) {
                events.push({
                  time,
                  fastPeriod,
                  slowPeriod,
                  direction: crossedUp ? 'up' : 'down',
                  value: (fastValue + slowValue) / 2
                });
              }
            }
            previous = { time, diff };
          });
        });

        events.sort((a, b) => a.time - b.time || a.fastPeriod - b.fastPeriod || a.slowPeriod - b.slowPeriod);
        return events;
      }

      function buildEmaCrossMarkers() {
        // V144 — niente marker storici: l'avviso compare solo sul punto dell'incrocio LIVE.
        return [];
      }

      function positionLiveEmaCrossAlert(symbol) {
        const bundle = charts[symbol];
        const alert = bundle?.emaCrossLiveAlert;
        const event = bundle?.emaCrossPointEvent;
        if (!bundle || !alert || !event) return;

        const ts = bundle.chart?.timeScale?.();
        const x = ts && typeof ts.timeToCoordinate === 'function'
          ? Number(ts.timeToCoordinate(event.time))
          : NaN;
        const referenceSeries = bundle.emaSeries?.[event.fastPeriod];
        const y = referenceSeries && typeof referenceSeries.priceToCoordinate === 'function'
          ? Number(referenceSeries.priceToCoordinate(event.value))
          : NaN;

        const width = Number(bundle.chartContainer?.clientWidth) || 0;
        const height = Number(bundle.chartContainer?.clientHeight) || 0;
        if (!Number.isFinite(x) || !Number.isFinite(y) || x < 0 || y < 0 || (width && x > width) || (height && y > height)) {
          alert.classList.remove('visible');
          return;
        }

        const safeX = width ? Math.max(58, Math.min(width - 58, x)) : x;
        const safeY = Math.max(26, y);
        alert.style.left = `${safeX}px`;
        alert.style.top = `${safeY}px`;
      }

      function showLiveEmaCrossAlert(symbol, candles) {
        const bundle = charts[symbol];
        if (!bundle || !Array.isArray(candles) || !candles.length) return;

        const latestTime = Number(candles[candles.length - 1]?.time);
        if (!Number.isFinite(latestTime)) return;
        const latestEvents = buildEmaCrossEvents(candles).filter(event => event.time === latestTime);
        if (!latestEvents.length) return;

        const signature = latestEvents
          .map(event => `${event.fastPeriod}-${event.slowPeriod}-${event.direction}`)
          .sort()
          .join('|') + '@' + latestTime;
        if (lastEmaCrossNotifications[symbol] === signature) return;
        lastEmaCrossNotifications[symbol] = signature;

        // V146 — AVVISO SOLO NELLE LINEE: niente badge/popup/marker aggiuntivi.
        // Lampeggiano per 1 secondo esclusivamente le EMA 15/20/50/200 coinvolte nell'incrocio.
        blinkEmaCrossLines(symbol, latestEvents);

        if (bundle.emaCrossLiveAlert) bundle.emaCrossLiveAlert.classList.remove('visible');
        bundle.emaCrossPointEvent = null;
      }

      function updateTopBottomMarkers(symbol) {
        const bundle = charts[symbol];
        const candles = candleHistory[symbol] || [];
        if (!bundle?.candles || typeof bundle.candles.setMarkers !== 'function') return;
        // Mantiene solo i marker TOP/BOTTOM; gli incroci EMA sono segnalati esclusivamente dal lampeggio delle linee.
        const markers = buildTopBottomMarkers(candles)
          .sort((a, b) => Number(a.time) - Number(b.time));
        bundle.candles.setMarkers(markers);
        // V147 — Il lampeggio EMA non viene più deciso dai marker/candele storiche.
        // Viene rilevato tick-per-tick direttamente in updateEmas().
      }

      function renderUnifiedVolumeAxisLabel(symbol) {
        const bundle = charts[symbol];
        const badge = bundle?.volumeAxisBadge;
        const value = Number(bundle?.volumeAxisBadgeValue);
        if (!badge || !Number.isFinite(value)) {
          if (badge) badge.hidden = true;
          return;
        }

        // V132 — Windows: deve esistere UNA SOLA etichetta VOL + dato.
        // Il motore Canvas incorporato disegna già il proprio badge volume;
        // in quel caso nascondiamo il badge HTML per evitare il doppione.
        const ua = String(navigator.userAgent || '');
        const platform = String(navigator.platform || '');
        const windowsPlatform = Boolean(
          window.__DASHBOARD_WINDOWS__ ||
          /Windows/i.test(ua) ||
          /^Win/i.test(platform)
        );
        const embeddedFallback = Boolean(bundle?.chart?.__isEmbeddedFallback);
        if (windowsPlatform && embeddedFallback) {
          badge.hidden = true;
          return;
        }

        const safeValue = Math.max(0, value);
        const labelColor = String(bundle?.volumeAxisBadgeColor || '#8b5cf6');
        const compactVolume = new Intl.NumberFormat(currentLocale(), {
          notation: 'compact',
          maximumFractionDigits: 2
        }).format(safeValue);
        badge.textContent = 'VOL  ' + compactVolume;
        badge.style.background = labelColor;
        badge.style.borderColor = labelColor;
        badge.hidden = false;

        const coord = bundle?.volume && typeof bundle.volume.priceToCoordinate === 'function'
          ? Number(bundle.volume.priceToCoordinate(safeValue))
          : NaN;
        const containerHeight = bundle?.chartContainer?.clientHeight || 0;
        const halfLabelHeight = 9;
        let top = Number.isFinite(coord) ? coord : (containerHeight ? Math.max(halfLabelHeight, containerHeight - 24) : 12);
        if (containerHeight > 0) {
          top = Math.max(halfLabelHeight, Math.min(containerHeight - halfLabelHeight, top));
        }
        badge.style.top = top + 'px';
      }

      function updateVolumeAxisLabel(symbol, volumeValue, color) {
        const bundle = charts[symbol];
        const label = bundle?.volumeAxisLabel;
        const value = Number(volumeValue);
        if (!bundle || !Number.isFinite(value)) return;
        const safeValue = Math.max(0, value);
        const rawColor = String(color || '');
        const isUp = /24\s*,\s*198\s*,\s*131|18c683|00e59b/i.test(rawColor);
        const isDown = /255\s*,\s*95\s*,\s*109|ff5f6d|ff3b5f/i.test(rawColor);
        const labelColor = isUp ? '#00e59b' : (isDown ? '#ff3b5f' : '#8b5cf6');

        bundle.volumeAxisBadgeValue = safeValue;
        bundle.volumeAxisBadgeColor = labelColor;

        if (label && typeof label.applyOptions === 'function') {
          try {
            label.applyOptions({
              price: safeValue,
              color: labelColor,
              axisLabelColor: labelColor,
              axisLabelTextColor: '#ffffff',
              title: '',
              lineVisible: false,
              axisLabelVisible: false
            });
          } catch (_) {}
        }

        renderUnifiedVolumeAxisLabel(symbol);
      }

      function lockChartView(symbol) {
        const bundle = charts[symbol];
        if (!bundle) return;
        bundle.viewLocked = true;
        try {
          const range = bundle.chart.timeScale().getVisibleRange();
          if (range && range.from != null && range.to != null) bundle.savedVisibleRange = { from: range.from, to: range.to };
        } catch (_) {}
        try {
          const logical = bundle.chart.timeScale().getVisibleLogicalRange();
          if (logical && Number.isFinite(Number(logical.from)) && Number.isFinite(Number(logical.to))) {
            bundle.savedLogicalRange = { from: Number(logical.from), to: Number(logical.to) };
          }
        } catch (_) {}
      }

      function rememberChartView(symbol) {
        const bundle = charts[symbol];
        if (!bundle || !bundle.viewLocked) return;
        try {
          const range = bundle.chart.timeScale().getVisibleRange();
          if (range && range.from != null && range.to != null) bundle.savedVisibleRange = { from: range.from, to: range.to };
        } catch (_) {}
        try {
          const logical = bundle.chart.timeScale().getVisibleLogicalRange();
          if (logical && Number.isFinite(Number(logical.from)) && Number.isFinite(Number(logical.to))) {
            bundle.savedLogicalRange = { from: Number(logical.from), to: Number(logical.to) };
          }
        } catch (_) {}
      }

      function restoreChartView(symbol) {
        const bundle = charts[symbol];
        if (!bundle || !bundle.viewLocked) return;
        const timeScale = bundle.chart.timeScale();
        let restored = false;

        // V138 — la posizione trascinata dall'utente ha priorità assoluta.
        // Usiamo PRIMA il range logico: conserva anche lo spazio libero oltre
        // l'ultima candela e impedisce agli aggiornamenti LIVE di riportare
        // improvvisamente il grafico tutto a destra.
        if (bundle.savedLogicalRange && Number.isFinite(Number(bundle.savedLogicalRange.from)) && Number.isFinite(Number(bundle.savedLogicalRange.to))) {
          try {
            timeScale.setVisibleLogicalRange({
              from: Number(bundle.savedLogicalRange.from),
              to: Number(bundle.savedLogicalRange.to)
            });
            restored = true;
          } catch (_) {}
        }
        // Fallback temporale solo quando non esiste una posizione logica valida.
        if (!restored && bundle.savedVisibleRange && bundle.savedVisibleRange.from != null && bundle.savedVisibleRange.to != null) {
          try {
            timeScale.setVisibleRange({
              from: bundle.savedVisibleRange.from,
              to: bundle.savedVisibleRange.to
            });
            restored = true;
          } catch (_) {}
        }
        renderUnifiedVolumeAxisLabel(symbol);
      }

      function resetChartViewMemory(symbol) {
        const bundle = charts[symbol];
        if (!bundle) return;
        bundle.viewLocked = false;
        bundle.savedVisibleRange = null;
        bundle.savedLogicalRange = null;
      }

      // V59 — Target e zone bloccati. Le zone non richiedono più permanenza minima: si aggiornano solo al breakout confermato del proprio bordo. Il cambio timeframe resetta lo stato.
      function ensureTradingZoneLayer(symbol) {
        const bundle = charts[symbol];
        if (!bundle || !bundle.chartContainer) return null;
        const wrap = bundle.chartContainer.closest('.chart-wrap');
        if (!wrap) return null;
        if (bundle.tradingZoneLayer && bundle.tradingZoneLayer.isConnected) return bundle.tradingZoneLayer;

        const layer = document.createElement('div');
        layer.className = 'trading-zones-layer-v46';
        layer.setAttribute('aria-hidden', 'true');
        ['accumulo', 'buy', 'sell'].forEach(kind => {
          const zone = document.createElement('div');
          zone.className = `trading-zone-v46 ${kind}`;
          zone.dataset.kind = kind;
          zone.dataset.label = kind === 'accumulo' ? 'ZONA ACCUMULO' : (kind === 'buy' ? 'ZONA BUY' : 'ZONA SELL');
          zone.hidden = true;
          layer.appendChild(zone);
        });
        wrap.appendChild(layer);
        bundle.tradingZoneLayer = layer;
        return layer;
      }

      function positionTradingZones(symbol) {
        const bundle = charts[symbol];
        if (!bundle || !bundle.candles || !Array.isArray(bundle.tradingZoneValues)) return;
        const layer = ensureTradingZoneLayer(symbol);
        if (!layer) return;
        const zonesEnabledV172 = window.__indicatorModelsPrefsV172?.zones !== false;
        layer.hidden = !zonesEnabledV172;
        if (!zonesEnabledV172) return;
        const h = bundle.chartContainer?.clientHeight || 0;
        if (!h || typeof bundle.candles.priceToCoordinate !== 'function') return;

        bundle.tradingZoneValues.forEach(zone => {
          const el = layer.querySelector(`[data-kind="${zone.kind}"]`);
          if (!el) return;
          const yHigh = Number(bundle.candles.priceToCoordinate(Number(zone.high)));
          const yLow = Number(bundle.candles.priceToCoordinate(Number(zone.low)));
          if (!Number.isFinite(yHigh) || !Number.isFinite(yLow)) {
            el.hidden = true;
            return;
          }
          const top = Math.max(0, Math.min(h, Math.min(yHigh, yLow)));
          const bottom = Math.max(0, Math.min(h, Math.max(yHigh, yLow)));
          const height = Math.max(8, bottom - top);
          el.style.top = `${top}px`;
          el.style.height = `${height}px`;
          el.dataset.label = `${zone.label}${zone.inConsolidation ? ' · CONSOLIDAMENTO ORIZZONTALE' : ''}  ${zone.lowText} – ${zone.highText}`;
          el.hidden = false;
        });
      }

      function technicalAtrFromHistory(valid) {
        if (!Array.isArray(valid) || valid.length < 2) return NaN;
        const start = Math.max(1, valid.length - 14);
        let trSum = 0;
        let trCount = 0;
        for (let i = start; i < valid.length; i += 1) {
          const cur = valid[i];
          const prevClose = Number(valid[i - 1]?.close);
          const high = Number(cur.high);
          const low = Number(cur.low);
          if (![prevClose, high, low].every(Number.isFinite)) continue;
          const tr = Math.max(high - low, Math.abs(high - prevClose), Math.abs(low - prevClose));
          if (Number.isFinite(tr) && tr > 0) {
            trSum += tr;
            trCount += 1;
          }
        }
        let atr = trCount ? trSum / trCount : NaN;
        if (!Number.isFinite(atr) || atr <= 0) {
          const sample = valid.slice(-Math.min(14, valid.length));
          const ranges = sample
            .map(c => Number(c.high) - Number(c.low))
            .filter(v => Number.isFinite(v) && v > 0);
          if (ranges.length) atr = ranges.reduce((a, b) => a + b, 0) / ranges.length;
        }
        return atr;
      }

      function makeLockedZoneSet(symbol, close, atr) {
        const cfg = ASSETS[symbol];
        if (!cfg) return [];
        const decimals = Number(cfg.decimals) || 2;
        const minimum = Math.pow(10, -decimals);
        const clampPositive = value => Math.max(minimum, value);
        const fmt = value => Number(value).toLocaleString(currentLocale(), {
          minimumFractionDigits: decimals,
          maximumFractionDigits: decimals
        });
        const values = [
          {
            kind: 'accumulo', label: 'ZONA ACCUMULO',
            low: clampPositive(close - atr * 1.80),
            high: clampPositive(close - atr * 1.00)
          },
          {
            kind: 'buy', label: 'ZONA BUY',
            low: clampPositive(close - atr * 0.85),
            high: clampPositive(close - atr * 0.20)
          },
          {
            kind: 'sell', label: 'ZONA SELL',
            low: close + atr * 0.80,
            high: close + atr * 1.55
          }
        ];
        values.forEach(zone => {
          if (zone.low > zone.high) [zone.low, zone.high] = [zone.high, zone.low];
          zone.lowText = fmt(zone.low);
          zone.highText = fmt(zone.high);
          zone.anchorClose = close;
          zone.anchorAtr = atr;
        });
        return values;
      }

      function makeLockedTargetSet(close, atr) {
        return [
          { price: close + atr,     label: 'TARGET 1 UP',   color: '#22c55e', strong: true,  direction: 'up', multiplier: 1, anchorClose: close },
          { price: close + atr * 2, label: 'TARGET 2 UP',   color: '#16a34a', strong: false, direction: 'up', multiplier: 2, anchorClose: close },
          { price: close + atr * 3, label: 'TARGET 3 UP',   color: '#15803d', strong: false, direction: 'up', multiplier: 3, anchorClose: close },
          { price: Math.max(0, close - atr),     label: 'TARGET 1 DOWN', color: '#ef4444', strong: true,  direction: 'down', multiplier: 1, anchorClose: close },
          { price: Math.max(0, close - atr * 2), label: 'TARGET 2 DOWN', color: '#dc2626', strong: false, direction: 'down', multiplier: 2, anchorClose: close },
          { price: Math.max(0, close - atr * 3), label: 'TARGET 3 DOWN', color: '#b91c1c', strong: false, direction: 'down', multiplier: 3, anchorClose: close }
        ].filter(level => Number.isFinite(level.price) && level.price > 0);
      }

      function refreshOneLockedTarget(target, close, atr) {
        const distance = atr * Number(target.multiplier || 1);
        target.anchorClose = close;
        target.price = target.direction === 'down'
          ? Math.max(0, close - distance)
          : close + distance;
      }

      function refreshOneLockedZone(zone, symbol, close, atr) {
        const fresh = makeLockedZoneSet(symbol, close, atr).find(item => item.kind === zone.kind);
        if (!fresh) return;
        Object.assign(zone, fresh);
      }

      const ZONE_CONSOLIDATION_MIN_CANDLES_V67 = 3;

      function resetZoneConsolidationV67(zone) {
        zone.rangeEntered = false;
        zone.consolidationCandles = [];
        zone.consolidationReady = false;
        zone.consolidationFirstTime = null;
        zone.consolidationLastTime = null;
        zone.consolidationCount = 0;
        zone.inConsolidation = false;
      }

      function advanceZoneConsolidationV67(candle, zone) {
        if (!zone) return false;
        if (!Array.isArray(zone.consolidationCandles)) zone.consolidationCandles = [];
        const time = candle?.time;
        if (time === undefined || time === null) return false;
        const existing = zone.consolidationCandles.find(item => item.time === time);
        if (!existing) zone.consolidationCandles.push({ time: time });
        zone.consolidationCandles = zone.consolidationCandles.slice(-ZONE_CONSOLIDATION_MIN_CANDLES_V67);
        zone.consolidationCount = zone.consolidationCandles.length;
        zone.consolidationFirstTime = zone.consolidationCandles[0]?.time ?? null;
        zone.consolidationLastTime = zone.consolidationCandles[zone.consolidationCandles.length - 1]?.time ?? null;
        zone.rangeEntered = true;
        if (zone.consolidationCount >= ZONE_CONSOLIDATION_MIN_CANDLES_V67) {
          zone.consolidationReady = true;
          zone.inConsolidation = true;
          return true;
        }
        return false;
      }

      function zoneBreaksClearlyV67(candle, zone) {
        const close = Number(candle?.close);
        const zoneLow = Number(zone?.low);
        const zoneHigh = Number(zone?.high);
        if (![close, zoneLow, zoneHigh].every(Number.isFinite)) return false;
        const lo = Math.min(zoneLow, zoneHigh);
        const hi = Math.max(zoneLow, zoneHigh);
        const width = Math.max(0, hi - lo);
        const atr = Number(zone?.anchorAtr);
        const epsilon = Math.max(
          Number.EPSILON * Math.max(1, Math.abs(lo), Math.abs(hi)) * 16,
          width * 0.06,
          Number.isFinite(atr) && atr > 0 ? atr * 0.12 : 0
        );
        if (close > hi + epsilon) return 'up';
        if (close < lo - epsilon) return 'down';
        return false;
      }

      // V68 — riconoscimento robusto di un range laterale reale.
      // Non pretende che ogni wick sia perfettamente dentro la zona originale:
      // basta che la formazione sia compatta e sovrapposta alla zona. Quando il
      // consolidamento è valido, la zona viene agganciata al suo range e resta fissa.
      const ZONE_HORIZONTAL_MIN_CANDLES_V68 = 4;
      const ZONE_HORIZONTAL_LOOKBACK_V68 = 7;

      function candleOverlapsZoneV68(candle, zone) {
        const low = Number(candle?.low), high = Number(candle?.high);
        const zl = Number(zone?.low), zh = Number(zone?.high);
        if (![low, high, zl, zh].every(Number.isFinite)) return false;
        const lo = Math.min(zl, zh), hi = Math.max(zl, zh);
        return high >= lo && low <= hi;
      }

      function detectHorizontalConsolidationV68(valid, zone, atr) {
        if (!Array.isArray(valid) || valid.length < ZONE_HORIZONTAL_MIN_CANDLES_V68) return null;
        const zl = Number(zone?.low), zh = Number(zone?.high);
        if (![zl, zh, atr].every(Number.isFinite) || atr <= 0) return null;
        const zoneLo = Math.min(zl, zh), zoneHi = Math.max(zl, zh);
        const zoneWidth = Math.max(zoneHi - zoneLo, atr * 0.25);
        const maxLook = Math.min(ZONE_HORIZONTAL_LOOKBACK_V68, valid.length);

        for (let count = maxLook; count >= ZONE_HORIZONTAL_MIN_CANDLES_V68; count -= 1) {
          const sample = valid.slice(-count);
          const lows = sample.map(c => Number(c.low));
          const highs = sample.map(c => Number(c.high));
          const closes = sample.map(c => Number(c.close));
          if (![...lows, ...highs, ...closes].every(Number.isFinite)) continue;

          const rangeLow = Math.min(...lows);
          const rangeHigh = Math.max(...highs);
          const rangeHeight = rangeHigh - rangeLow;
          if (!(rangeHeight > 0)) continue;

          // Formazione laterale: range compatto rispetto ad ATR e alla larghezza zona.
          const maxHeight = Math.max(atr * 1.45, zoneWidth * 1.20);
          if (rangeHeight > maxHeight) continue;

          // Almeno il 70% delle candele deve sovrapporsi alla zona.
          const overlapCount = sample.filter(c => candleOverlapsZoneV68(c, zone)).length;
          if (overlapCount < Math.ceil(count * 0.70)) continue;

          // Pendenza dei close contenuta: niente trend marcato mascherato da range.
          const drift = Math.abs(closes[closes.length - 1] - closes[0]);
          if (drift > Math.max(atr * 0.65, rangeHeight * 0.60)) continue;

          // Il prezzo medio del box deve essere vicino/entro la zona originaria.
          const mid = (rangeLow + rangeHigh) / 2;
          const tolerance = Math.max(atr * 0.55, zoneWidth * 0.35);
          if (mid < zoneLo - tolerance || mid > zoneHi + tolerance) continue;

          return {
            low: rangeLow,
            high: rangeHigh,
            firstTime: sample[0]?.time ?? null,
            lastTime: sample[sample.length - 1]?.time ?? null,
            count: count
          };
        }
        return null;
      }

      function lockZoneToConsolidationV68(zone, box, symbol) {
        if (!zone || !box) return false;
        const cfg = ASSETS[symbol];
        const decimals = Number(cfg?.decimals) || 2;
        const fmt = value => Number(value).toLocaleString(currentLocale(), {
          minimumFractionDigits: decimals, maximumFractionDigits: decimals
        });
        const atr = Number(zone.anchorAtr);
        const pad = Number.isFinite(atr) && atr > 0 ? atr * 0.04 : 0;
        zone.low = Math.max(Math.pow(10, -decimals), Number(box.low) - pad);
        zone.high = Number(box.high) + pad;
        zone.lowText = fmt(zone.low);
        zone.highText = fmt(zone.high);
        zone.rangeEntered = true;
        zone.consolidationReady = true;
        zone.inConsolidation = true;
        zone.consolidationCount = Number(box.count) || ZONE_HORIZONTAL_MIN_CANDLES_V68;
        zone.consolidationFirstTime = box.firstTime;
        zone.consolidationLastTime = box.lastTime;
        zone.consolidationLockedAt = Date.now();
        return true;
      }

      // V58 — REGOLA DEFINITIVA ZONE: prima del breakout, il prezzo deve consolidare
      // dentro la FASCIA BUY / SELL / ACCUMULO. Servono 5 candele CONSECUTIVE
      // completamente contenute tra low e high della zona (wick comprese).
      // La candela di breakout deve essere SUCCESSIVA alle 5 e deve CHIUDERE oltre
      // il bordo opposto. Solo allora si aggiorna esclusivamente la zona sfondata.
      const ZONE_MIN_INSIDE_CANDLES_V50 = 5;
      const ZONE_RECT_MAX_HEIGHT_RATIO_V55 = 1.00;
      function candleBodyEntersZoneRange(candle, zone) {
        const open = Number(candle?.open);
        const close = Number(candle?.close);
        const zoneLow = Number(zone?.low);
        const zoneHigh = Number(zone?.high);
        if (![open, close, zoneLow, zoneHigh].every(Number.isFinite)) return false;
        const lo = Math.min(zoneLow, zoneHigh);
        const hi = Math.max(zoneLow, zoneHigh);
        const bodyLow = Math.min(open, close);
        const bodyHigh = Math.max(open, close);
        const width = Math.max(0, hi - lo);
        const epsilon = Math.max(Number.EPSILON * Math.max(1, Math.abs(lo), Math.abs(hi)) * 16, width * 1e-6);
        // Solo contatto con il bordo = nessun ingresso.
        return bodyHigh > lo + epsilon && bodyLow < hi - epsilon;
      }

      function candleClosesInsideZoneRange(candle, zone) {
        const close = Number(candle?.close);
        const zoneLow = Number(zone?.low);
        const zoneHigh = Number(zone?.high);
        if (![close, zoneLow, zoneHigh].every(Number.isFinite)) return false;
        const lo = Math.min(zoneLow, zoneHigh);
        const hi = Math.max(zoneLow, zoneHigh);
        const width = Math.max(0, hi - lo);
        const epsilon = Math.max(Number.EPSILON * Math.max(1, Math.abs(lo), Math.abs(hi)) * 16, width * 1e-6);
        return close > lo + epsilon && close < hi - epsilon;
      }

      // V56 — per contare nella permanenza, l'INTERA candela deve restare nella fascia:
      // minimo >= bordo basso e massimo <= bordo alto. Anche le wick devono rimanere dentro.
      function candleFullyInsideZoneRange(candle, zone) {
        const low = Number(candle?.low);
        const high = Number(candle?.high);
        const zoneLow = Number(zone?.low);
        const zoneHigh = Number(zone?.high);
        if (![low, high, zoneLow, zoneHigh].every(Number.isFinite)) return false;
        const lo = Math.min(zoneLow, zoneHigh);
        const hi = Math.max(zoneLow, zoneHigh);
        const width = Math.max(0, hi - lo);
        const epsilon = Math.max(Number.EPSILON * Math.max(1, Math.abs(lo), Math.abs(hi)) * 16, width * 1e-6);
        return low >= lo - epsilon && high <= hi + epsilon;
      }

      function resetZoneRectangleV55(zone) {
        zone.rectangleSamples = [];
        zone.rectangleReady = false;
        zone.rectangleLow = null;
        zone.rectangleHigh = null;
        zone.rectangleFirstTime = null;
        zone.rectangleLastTime = null;
        zone.rectangleReadyTime = null;
        zone.rectangleReadyAt = null;
        zone.insideCandleCount = 0;
        zone.lastCountedInsideTime = null;
        zone.readyForBreak = false;
        zone.readyAtTime = null;
        zone.readyAt = null;
      }

      function updateZoneRectangleV55(candle, zone) {
        if (!zone?.rangeEntered || zone.rectangleReady || !candleFullyInsideZoneRange(candle, zone)) return false;
        const low = Number(candle?.low), high = Number(candle?.high), time = candle?.time;
        const zoneLow = Number(zone?.low), zoneHigh = Number(zone?.high);
        if (![low,high,zoneLow,zoneHigh].every(Number.isFinite) || time === undefined || time === null) return false;
        const lo=Math.min(zoneLow,zoneHigh), hi=Math.max(zoneLow,zoneHigh);
        const candleLow=Math.max(lo,low), candleHigh=Math.min(hi,high);
        if (!(candleHigh>=candleLow)) return false;
        if (!Array.isArray(zone.rectangleSamples)) zone.rectangleSamples=[];
        const existing=zone.rectangleSamples.find(x=>x.time===time);
        if (existing) { existing.low=candleLow; existing.high=candleHigh; }
        else zone.rectangleSamples.push({time,low:candleLow,high:candleHigh});
        // Devono essere CONSECUTIVE: se una candela non resta interamente nella fascia,
        // il ciclo viene azzerato nel loop principale prima di arrivare qui.
        if (zone.rectangleSamples.length>ZONE_MIN_INSIDE_CANDLES_V50) zone.rectangleSamples=zone.rectangleSamples.slice(-ZONE_MIN_INSIDE_CANDLES_V50);
        zone.insideCandleCount=new Set(zone.rectangleSamples.map(x=>x.time)).size;
        zone.lastCountedInsideTime=time;
        if (zone.rectangleSamples.length<ZONE_MIN_INSIDE_CANDLES_V50) return false;
        const latest=zone.rectangleSamples.slice(-ZONE_MIN_INSIDE_CANDLES_V50);
        const boxLow=Math.min(...latest.map(x=>Number(x.low)).filter(Number.isFinite));
        const boxHigh=Math.max(...latest.map(x=>Number(x.high)).filter(Number.isFinite));
        const zoneWidth=hi-lo, boxHeight=boxHigh-boxLow;
        if (!(zoneWidth>0) || boxHeight>zoneWidth*ZONE_RECT_MAX_HEIGHT_RATIO_V55) return false;
        zone.rectangleReady=true;
        zone.rectangleLow=boxLow;
        zone.rectangleHigh=boxHigh;
        zone.rectangleFirstTime=latest[0].time;
        zone.rectangleLastTime=latest[latest.length-1].time;
        zone.rectangleReadyTime=time;
        zone.rectangleReadyAt=Date.now();
        zone.readyForBreak=true;
        zone.readyAtTime=time;
        zone.readyAt=zone.rectangleReadyAt;
        return true;
      }

      function candleExitsZoneFromEntrySide(candle, zone) {
        const close = Number(candle?.close);
        const zoneLow = Number(zone?.low);
        const zoneHigh = Number(zone?.high);
        if (![close, zoneLow, zoneHigh].every(Number.isFinite)) return false;
        const lo = Math.min(zoneLow, zoneHigh);
        const hi = Math.max(zoneLow, zoneHigh);
        const width = Math.max(0, hi - lo);
        const epsilon = Math.max(Number.EPSILON * Math.max(1, Math.abs(lo), Math.abs(hi)) * 16, width * 1e-6);
        // Accumulo/Buy entrano normalmente dall'alto: uscire sopra hi annulla la permanenza.
        // Sell entra normalmente dal basso: uscire sotto lo annulla.
        if (zone.kind === 'sell') return close < lo - epsilon;
        return close > hi + epsilon;
      }

      function candleBreaksThroughArmedZone(candle, zone) {
        if (!zone?.rangeEntered || !zone?.rectangleReady) return false;
        if (Number(zone.insideCandleCount || 0) < ZONE_MIN_INSIDE_CANDLES_V50) return false;
        const close = Number(candle?.close);
        const zoneLow = Number(zone?.low);
        const zoneHigh = Number(zone?.high);
        if (![close, zoneLow, zoneHigh].every(Number.isFinite)) return false;
        const lo = Math.min(zoneLow, zoneHigh);
        const hi = Math.max(zoneLow, zoneHigh);
        const width = Math.max(0, hi - lo);
        const epsilon = Math.max(Number.EPSILON * Math.max(1, Math.abs(lo), Math.abs(hi)) * 16, width * 1e-6);

        // Accumulo/Buy sono sotto il prezzo di partenza: entrano dall'alto e devono
        // sfondare il bordo BASSO. Sell è sopra: entra dal basso e deve sfondare l'ALTO.
        if (zone.kind === 'sell') return close > hi + epsilon;
        return close < lo - epsilon;
      }


      // All devices use chart-native price lines: their coordinates are updated
      // by the chart during touch pan, pinch, price-scale changes and resize.
      function renderLockedTargets(symbol, close, state) {
        const bundle = charts[symbol];
        const cfg = ASSETS[symbol];
        if (!bundle || !cfg || !state || !Array.isArray(state.targets)) return;
        if (!Array.isArray(bundle.targetLines)) bundle.targetLines = [];
        if (!Array.isArray(bundle.targetLineValues)) bundle.targetLineValues = [];
        const targetsEnabledV172 = window.__indicatorModelsPrefsV172?.targets !== false;

        if (bundle.ipadTargetOverlayV60) {
          bundle.ipadTargetOverlayV60.remove();
          bundle.ipadTargetOverlayV60 = null;
        }

        state.targets.forEach((level, index) => {
          const price = Number(level.price);
          if (!Number.isFinite(price) || price <= 0) return;
          const anchorClose = Number(level.anchorClose);
          const pctBase = Number.isFinite(anchorClose) && anchorClose > 0 ? anchorClose : close;
          const pct = ((price / pctBase) - 1) * 100;
          const decimalsPct = Math.abs(pct) < 10 ? 1 : 0;
          const signedPct = `${pct >= 0 ? '+' : ''}${pct.toFixed(decimalsPct)}%`;
          const title = `${level.label} ${signedPct}`;

          if (!bundle.targetLines[index]) {
            try {
              bundle.targetLines[index] = bundle.candles.createPriceLine({
                price,
                color: level.color,
                lineWidth: level.strong ? 2 : 1,
                lineStyle: 2,
                lineVisible: targetsEnabledV172,
                axisLabelVisible: targetsEnabledV172,
                title
              });
            } catch (_) {
              bundle.targetLines[index] = null;
            }
          } else {
            try {
              bundle.targetLines[index].applyOptions({
                price,
                color: level.color,
                lineWidth: level.strong ? 2 : 1,
                lineStyle: 2,
                lineVisible: targetsEnabledV172,
                axisLabelVisible: targetsEnabledV172,
                title
              });
            } catch (_) {}
          }
          bundle.targetLineValues[index] = price;
        });

        for (let i = state.targets.length; i < bundle.targetLines.length; i += 1) {
          try { bundle.targetLines[i]?.applyOptions({ lineVisible: false, axisLabelVisible: false }); } catch (_) {}
        }

      }


      document.addEventListener('indicator-models-v172-change', () => {
        try {
          Object.keys(charts || {}).forEach(symbol => {
            const bundle = charts[symbol];
            const targetOn = window.__indicatorModelsPrefsV172?.targets !== false;
            if (Array.isArray(bundle?.targetLines)) {
              bundle.targetLines.forEach(line => {
                try { line?.applyOptions({ lineVisible: targetOn, axisLabelVisible: targetOn }); } catch (_) {}
              });
            }
            const layer = bundle?.tradingZoneLayer;
            if (layer) layer.hidden = window.__indicatorModelsPrefsV172?.zones === false;
            if (window.__indicatorModelsPrefsV172?.zones !== false) {
              try { positionTradingZones(symbol); } catch (_) {}
            }
          });
        } catch (_) {}
      });

      function updatePriceTargets(symbol) {
        const bundle = charts[symbol];
        const cfg = ASSETS[symbol];
        const history = candleHistory[symbol];
        if (!bundle || !cfg || !Array.isArray(history) || history.length < 2) return;

        const valid = history.filter(c =>
          c && [c.open, c.high, c.low, c.close].every(v => Number.isFinite(Number(v)))
        );
        if (valid.length < 2) return;

        const last = valid[valid.length - 1];
        const close = Number(last.close);
        const high = Number(last.high);
        const low = Number(last.low);
        const candleTime = last.time;
        if (![close, high, low].every(Number.isFinite) || close <= 0) return;

        const atr = technicalAtrFromHistory(valid);
        if (!Number.isFinite(atr) || atr <= 0) return;

        const timeframeKey = String(typeof interval !== 'undefined' ? interval : '');
        let state = bundle.targetZoneLockV47;
        const needsInit = !state || state.timeframe !== timeframeKey || !Array.isArray(state.targets) || !Array.isArray(state.zones);

        if (needsInit) {
          state = {
            timeframe: timeframeKey,
            targets: makeLockedTargetSet(close, atr),
            zones: makeLockedZoneSet(symbol, close, atr),
            lastCandleTime: candleTime,
            lastHigh: high,
            lastLow: low,
            lastOpen: Number(last.open),
            lastClose: close,
            initializedAt: Date.now(),
            hits: 0
          };
          bundle.targetZoneLockV47 = state;
        } else {
          const sameCandle = state.lastCandleTime === candleTime;
          const prevHigh = Number(state.lastHigh);
          const prevLow = Number(state.lastLow);

          // TARGET: si aggiorna SOLO il livello realmente raggiunto dalla candela.
          state.targets.forEach(target => {
            const price = Number(target.price);
            if (!Number.isFinite(price) || price <= 0) return;
            let touched = false;
            if (target.direction === 'up') {
              touched = high >= price && (!sameCandle || !Number.isFinite(prevHigh) || prevHigh < price);
            } else {
              touched = low <= price && (!sameCandle || !Number.isFinite(prevLow) || prevLow > price);
            }
            if (touched) {
              refreshOneLockedTarget(target, close, atr);
              target.lastHitTime = candleTime;
              target.lastHitAt = Date.now();
              state.hits += 1;
            }
          });

          // V68 — CONSOLIDAMENTO ORIZZONTALE ROBUSTO.
          // 1) rileva una formazione laterale compatta che si sovrappone alla zona;
          // 2) aggancia la fascia BUY/SELL/ACCUMULO al range reale del box;
          // 3) mantiene la zona estesa e immobile;
          // 4) la aggiorna soltanto dopo una chiusura chiaramente fuori dal box.
          const brokenZonesV68 = [];

          state.zones.forEach(zone => {
            const zoneLow = Number(zone.low);
            const zoneHigh = Number(zone.high);
            if (![zoneLow, zoneHigh, close].every(Number.isFinite)) return;

            if (zone.inConsolidation) {
              const breakDir = zoneBreaksClearlyV67(last, zone);
              if (breakDir) {
                brokenZonesV68.push({ kind: zone.kind, direction: breakDir });
              }
              // Durante il consolidamento NON muovere né resettare la fascia.
              return;
            }

            const box = detectHorizontalConsolidationV68(valid, zone, atr);
            if (box) {
              lockZoneToConsolidationV68(zone, box, symbol);
            }
          });

          if (brokenZonesV68.length) {
            const freshZonesV68 = makeLockedZoneSet(symbol, close, atr);
            brokenZonesV68.forEach(hit => {
              const zone = state.zones.find(item => item.kind === hit.kind);
              const fresh = freshZonesV68.find(item => item.kind === hit.kind);
              if (!zone || !fresh) return;
              Object.assign(zone, fresh);
              resetZoneConsolidationV67(zone);
              zone.lastBreakTime = candleTime;
              zone.lastBreakAt = Date.now();
              zone.lastBreakKind = hit.kind;
              zone.lastBreakDirection = hit.direction;
              zone.lastRefreshClose = close;
              zone.lastRefreshAtr = atr;
              state.lastZoneBreakKind = hit.kind;
              state.lastZoneBreakDirection = hit.direction;
              state.lastZoneBreakTime = candleTime;
              state.lastZoneBreakAt = Date.now();
              state.hits += 1;
            });
          }

          state.lastCandleTime = candleTime;
          state.lastHigh = high;
          state.lastLow = low;
          state.lastOpen = Number(last.open);
          state.lastClose = close;
        }

        bundle.tradingZoneValues = state.zones;
        ensureTradingZoneLayer(symbol);
        renderLockedTargets(symbol, close, state);

        if (typeof requestAnimationFrame === 'function') {
          requestAnimationFrame(() => {
            positionTradingZones(symbol);
            // V315: native price lines follow the chart without a legacy iPad overlay.
          });
        } else {
          positionTradingZones(symbol);
          // V315: native price lines need no manual re-positioning.
        }
      }

      function applyAggregatedHistory(symbol, aggregated, preserveVisibleRange = false) {
        if (!charts[symbol] || !aggregated.length) return;
        const bundle = charts[symbol];

        // V139 — preserva SEMPRE prima la posizione logica scelta dall'utente.
        // Fondamentale per Raydium/MAX: ad ogni tick le 230 candele vengono
        // ricostruite; ripristinare solo il range temporale faceva scattare
        // improvvisamente il grafico verso l'ultima candela a destra.
        const lockedLogicalRange = bundle.viewLocked && bundle.savedLogicalRange &&
          Number.isFinite(Number(bundle.savedLogicalRange.from)) &&
          Number.isFinite(Number(bundle.savedLogicalRange.to))
            ? { from: Number(bundle.savedLogicalRange.from), to: Number(bundle.savedLogicalRange.to) }
            : null;

        const visibleRange = bundle.viewLocked && bundle.savedVisibleRange
          ? { from: bundle.savedVisibleRange.from, to: bundle.savedVisibleRange.to }
          : (preserveVisibleRange ? bundle.chart.timeScale().getVisibleRange() : null);
        const candles = aggregated.map(({ time, open, high, low, close }) => ({ time, open, high, low, close }));
        const volume = aggregated.map(candle => ({
          time: candle.time,
          value: Number.isFinite(candle.volume) ? candle.volume : 0,
          color: candle.close >= candle.open
            ? ((symbol === ORE_SYMBOL || symbol === ORAI_SYMBOL) ? 'rgba(24,198,131,.82)' : 'rgba(24,198,131,.42)')
            : ((symbol === ORE_SYMBOL || symbol === ORAI_SYMBOL) ? 'rgba(255,95,109,.82)' : 'rgba(255,95,109,.42)')
        }));

        candleHistory[symbol] = candles;
        v317HistoryNotice(symbol);
        refreshDerivedLowReference(symbol);
        bundle.candles.setData(candles);
        bundle.volume.setData(volume);
        const latestVolumePoint = volume[volume.length - 1];
        if (latestVolumePoint && (symbol === ORAI_SYMBOL || symbol === TAI_SYMBOL)) {
          coinGeckoCurrentVolumes[symbol] = latestVolumePoint.value;
        }
        if (latestVolumePoint) updateVolumeAxisLabel(symbol, latestVolumePoint.value, latestVolumePoint.color);
        updateTopBottomMarkers(symbol);
        updateEmas(symbol);
        updateTechnicalIndicators(symbol);
        updatePriceTargets(symbol);

        if (lockedLogicalRange) {
          // Il grafico principale resta esattamente dove l'utente lo ha lasciato,
          // anche con spazio libero oltre i bordi dei dati.
          try {
            bundle.chart.timeScale().setVisibleLogicalRange({
              from: lockedLogicalRange.from,
              to: lockedLogicalRange.to
            });
          } catch (_) {}

          // Gli indicatori non hanno bisogno dello spazio logico extra: li
          // sincronizziamo alle stesse date senza alterare il pan del grafico principale.
          if (visibleRange) {
            Object.values(bundle.indicators).forEach(indicator => {
              try { indicator.chart.timeScale().setVisibleRange(visibleRange); } catch (_) {}
            });
          }

          // Non ricalcolare il range logico dopo il setData: manterrebbe un range
          // normalizzato dalla libreria e potrebbe reintrodurre lo scatto su RAY.
          bundle.savedLogicalRange = {
            from: lockedLogicalRange.from,
            to: lockedLogicalRange.to
          };
        } else if (visibleRange) {
          try { bundle.chart.timeScale().setVisibleRange(visibleRange); } catch (_) {}
          Object.values(bundle.indicators).forEach(indicator => {
            try { indicator.chart.timeScale().setVisibleRange(visibleRange); } catch (_) {}
          });
          if (bundle.viewLocked) rememberChartView(symbol);
        } else {
          bundle.chart.timeScale().fitContent();
          Object.values(bundle.indicators).forEach(indicator => indicator.chart.timeScale().fitContent());
        }
      }

      function normalizeRestKline(kline) {
        return {
          time: Math.floor(Number(kline[0]) / 1000),
          open: Number(kline[1]),
          high: Number(kline[2]),
          low: Number(kline[3]),
          close: Number(kline[4]),
          volume: Number(kline[5])
        };
      }

      function normalizeStreamKline(kline) {
        return {
          time: Math.floor(Number(kline.t) / 1000),
          open: Number(kline.o),
          high: Number(kline.h),
          low: Number(kline.l),
          close: Number(kline.c),
          volume: Number(kline.v)
        };
      }

