      function refreshAssetDetails(symbol) {
        const key = ASSETS[symbol].key;
        const panel = $(key + '-details');
        if (!panel || panel.hidden) return;
        const grid = panel.querySelector('.details-grid');
        const details = collectAssetDetails(symbol);

        if (grid.children.length !== details.length) {
          grid.replaceChildren();
          details.forEach(() => {
            const item = document.createElement('div');
            item.className = 'detail-item';
            const label = document.createElement('span');
            label.className = 'detail-label';
            const value = document.createElement('strong');
            value.className = 'detail-value';
            item.append(label, value);
            grid.appendChild(item);
          });
        }

        [...grid.children].forEach((item, index) => {
          const detail = details[index];
          item.classList.toggle('price-sensitive', Boolean(detail.sensitive));
          item.querySelector('.detail-label').textContent = detail.label;
          const value = item.querySelector('.detail-value');
          value.textContent = detail.value;
          value.className = 'detail-value' + (detail.tone ? ' ' + detail.tone : '');
        });
      }

