      function burnCompactToMicro(numberText, suffix) {
        const normalized = String(numberText || '').replace(/,/g, '').trim();
        const match = normalized.match(/^([0-9]+(?:\.[0-9]+)?)/);
        if (!match) return null;
        const value = Number(match[1]);
        if (!Number.isFinite(value)) return null;
        const multiplier = ({ K: 1e3, M: 1e6, B: 1e9, T: 1e12 })[String(suffix || '').toUpperCase()] || 1;
        return BigInt(Math.round(value * multiplier * 1e6));
      }

      async function fetchJsonWithTimeout(url, timeout = 6500) {
        const controller = new AbortController();
        const timer = setTimeout(() => controller.abort(), timeout);
        try {
          const response = await fetch(url, { signal: controller.signal, cache: 'no-store', headers: { Accept: 'application/json' } });
          if (!response.ok) throw new Error('HTTP ' + response.status);
          return await response.json();
        } finally { clearTimeout(timer); }
      }

      async function fetchLuncSupplyMicro() {
        const paths = [
          '/cosmos/bank/v1beta1/supply/by_denom?denom=uluna',
          '/cosmos/bank/v1beta1/supply/uluna'
        ];
        const attempts = [];
        for (const base of LUNC_BURN_LCDS) {
          for (const path of paths) attempts.push(fetchJsonWithTimeout(base + path).then(data => ({ data, base })));
        }
        return await new Promise((resolve, reject) => {
          let pending = attempts.length;
          let lastError = new Error('Supply LUNC non disponibile');
          attempts.forEach(promise => promise.then(({ data, base }) => {
            const amount = data?.amount?.amount ?? data?.amount ?? data?.supply?.find?.(coin => coin.denom === 'uluna')?.amount;
            if (amount !== undefined && /^\d+$/.test(String(amount))) resolve({ amountMicro: BigInt(amount), source: new URL(base).hostname });
            else throw new Error('Formato supply non valido');
          }).catch(error => {
            lastError = error;
            pending -= 1;
            if (!pending) reject(lastError);
          }));
        });
      }

      function extractBurnMetricsFromText(rawText) {
        const text = String(rawText || '').replace(/\s+/g, ' ');
        const result = {};
        const exact = text.match(/Total LUNA Classic Burned\s*([\d,]+(?:\.\d+)?)\s*LUNC/i);
        if (exact) result.totalMicro = burnCompactToMicro(exact[1], '');
        const totalCompact = text.match(/Total LUNC Burned\s*([\d,.]+)\s*([KMBT])\b/i);
        if (!result.totalMicro && totalCompact) result.totalMicro = burnCompactToMicro(totalCompact[1], totalCompact[2]);
        const today = text.match(/(?:Today's LUNC Burn|Burned today)\s*([\d,.]+)\s*([KMBT])?\s*(?:LUNC)?/i);
        if (today) result.todayMicro = burnCompactToMicro(today[1], today[2]);
        const seven = text.match(/7-day LUNC Burn\s*([\d,.]+)\s*([KMBT])?/i);
        if (seven) result.sevenMicro = burnCompactToMicro(seven[1], seven[2]);
        const thirty = text.match(/30-day LUNC Burn\s*([\d,.]+)\s*([KMBT])?/i);
        if (thirty) result.thirtyMicro = burnCompactToMicro(thirty[1], thirty[2]);

        const donated = text.match(/Donated to Burn Wallet\s*([\d,.]+)\s*([KMBT])\b/i);
        if (donated) result.walletMicro = burnCompactToMicro(donated[1], donated[2]);

        const onchain = text.match(/Burned On-Chain\s*([\d,.]+)\s*([KMBT])\b/i);
        if (onchain) result.onChainMicro = burnCompactToMicro(onchain[1], onchain[2]);

        return result;
      }

      async function fetchBurnTrackerMetrics() {
        const targets = [
          { url: 'https://www.luncmetrics.com/top-burners/lunc', name: 'LUNCMetrics Top Burners' },
          { url: 'https://www.luncmetrics.com/burn-tracker/lunc', name: 'LUNCMetrics' },
          { url: 'https://luncsupply.live/', name: 'LUNC Supply Live' }
        ];
        let merged = {};
        const sources = [];
        for (const target of targets) {
          const urls = [
            target.url,
            'https://api.allorigins.win/raw?url=' + encodeURIComponent(target.url),
            'https://corsproxy.io/?url=' + encodeURIComponent(target.url)
          ];
          for (const url of urls) {
            const controller = new AbortController();
            const timer = setTimeout(() => controller.abort(), 6500);
            try {
              const response = await fetch(url, { signal: controller.signal, cache: 'no-store' });
              if (!response.ok) throw new Error('HTTP ' + response.status);
              const raw = await response.text();
              const parsed = extractBurnMetricsFromText(raw);
              if (parsed.todayMicro || parsed.sevenMicro || parsed.thirtyMicro || parsed.totalMicro) {
                merged = {
                  totalMicro: merged.totalMicro ?? parsed.totalMicro,
                  todayMicro: merged.todayMicro ?? parsed.todayMicro,
                  sevenMicro: merged.sevenMicro ?? parsed.sevenMicro,
                  thirtyMicro: merged.thirtyMicro ?? parsed.thirtyMicro,
                  walletMicro: merged.walletMicro ?? parsed.walletMicro,
                  onChainMicro: merged.onChainMicro ?? parsed.onChainMicro
                };
                sources.push(target.name);
                break;
              }
            } catch {} finally { clearTimeout(timer); }
          }
        }
        return sources.length ? { ...merged, source: sources.join(' + ') } : null;
      }

