      function burnMetric(symbol) {
        return BURN_METRICS[symbol] || { label: t('burnTotal'), fallback: 'N/D', source: 'Protocollo', status: 'Dato non disponibile', detail: '' };
      }

      function burnSecondaryMarkup(symbol) {
        const cfg = ASSETS[symbol];
        const metric = burnMetric(symbol);
        if (!cfg || !metric.secondaryLabel) return '';
        const highlightClass = (symbol === 'RAYUSDT' || symbol === 'SOLUSDT' || symbol === 'INJUSDT' || symbol === 'OREUSD' || symbol === 'TAIUSD' || symbol === 'TAOUSDT' || symbol === 'VIRTUALUSDT' || symbol === 'WLDUSDT' || symbol === 'ORAIUSD' || symbol === 'LUNCUSDT' || symbol === 'LUNAUSDT') ? ' burn-total-highlight' : '';
        return `<div class="burn-item${highlightClass}"><span class="burn-label" id="${cfg.key}-burn-secondary-label">${metric.secondaryLabel}</span><strong class="burn-value" id="${cfg.key}-burn-secondary">${metric.secondaryFallback || 'N/D'}</strong></div>`;
      }

      function setBurnSecondaryValue(symbol, displayValue, title = '') {
        const cfg = ASSETS[symbol];
        if (!cfg) return;
        const element = $(cfg.key + '-burn-secondary');
        if (!element) return;
        const safeValue = displayValue || 'N/D';
        const previousValue = element.textContent?.trim() || '';
        element.textContent = safeValue;
        element.title = title || safeValue;
        if (previousValue && previousValue !== safeValue) {
          element.classList.remove('burn-value-live-change');
          void element.offsetWidth;
          element.classList.add('burn-value-live-change');
        }
        if (!['N/D', '—', 'Non applicabile'].includes(String(safeValue).trim())) {
          element.dataset.liveBurnCumulative = 'true';
          element.dataset.liveBurnUpdatedAt = String(Date.now());
          // Salva anche il cumulativo: se una singola API salta un ciclo, il dato
          // recente resta visibile senza bloccare le altre crypto.
          try {
            const cache = readBurnCache();
            const current = cache[symbol] && typeof cache[symbol] === 'object' ? cache[symbol] : {};
            cache[symbol] = {
              ...current,
              secondaryDisplay: safeValue,
              secondaryTitle: title || safeValue,
              secondaryUpdatedAt: Date.now()
            };
            localStorage.setItem(BURN_CACHE_KEY, JSON.stringify(cache));
          } catch (_) {}
        } else {
          delete element.dataset.liveBurnCumulative;
          delete element.dataset.liveBurnUpdatedAt;
        }
      }

