      function applyVerifiedRealBurnFallback(symbol) {
        const cfg = ASSETS[symbol];
        const snap = VERIFIED_REAL_BURN_FALLBACKS[symbol];
        if (!cfg || !snap) return false;

        const primaryLabel = $(cfg.key + '-burn-total-label');
        const primary = $(cfg.key + '-burn-total');
        const secondaryLabel = $(cfg.key + '-burn-secondary-label');
        const secondary = $(cfg.key + '-burn-secondary');
        const status = $(cfg.key + '-burn-status');
        const source = $(cfg.key + '-burn-source');
        const updated = $(cfg.key + '-burn-updated');

        if (primaryLabel) primaryLabel.textContent = snap.primaryLabel;
        if (primary) {
          primary.textContent = snap.primary;
          primary.title = snap.detail;
          primary.dataset.verifiedRealBurn = 'true';
        }
        if (secondaryLabel) secondaryLabel.textContent = snap.secondaryLabel;
        if (secondary) {
          secondary.textContent = snap.secondary;
          secondary.title = snap.detail;
          secondary.dataset.verifiedRealBurn = 'true';
        }
        if (status) {
          status.textContent = 'DATO REALE VERIFICATO · LIVE IN AGGIORNAMENTO';
          status.className = 'burn-status warn';
          status.title = snap.detail;
        }
        if (source) source.textContent = 'Fonte: ' + snap.source;
        if (updated) updated.textContent = snap.updated;
        return true;
      }

