          if (toggleLabel) toggleLabel.textContent = (symbol === 'OREUSD' || symbol === 'BTCUSDT') ? 'Mining LIVE' : 'Burn oggi - totale';
          if (label) label.textContent = metric.label;
          if (secondaryLabel && metric.secondaryLabel) secondaryLabel.textContent = metric.secondaryLabel;
