      function syncVisibleOrderbooks() {
        Object.keys(ASSETS).forEach(symbol => {
          const cfg = ASSETS[symbol];
          if(cfg && !$(cfg.key + '-orderbook-panel')) setupOrderbookSection(symbol);
          const panel = cfg ? $(cfg.key + '-orderbook-panel') : null;
          if (!panel) return;
          panel.hidden=false;
          panel.style.removeProperty('display');
          if (orderbookCanRunV212(symbol)) {
            if (!orderbookSockets.get(symbol) && orderbookLiveMarket(symbol)) startOrderbook(symbol);
            else if (!orderbookLiveMarket(symbol)) startOrderbook(symbol);
          } else if (orderbookSockets.get(symbol)) {
            closeOrderbookSocket(symbol);
          }
        });
      }

      function watchdogRealOrderbooks() {
        if (document.hidden) return;
        const now = Date.now();
        Object.keys(ASSETS).forEach(symbol => {
          const cfg = ASSETS[symbol];
          const market = orderbookLiveMarket(symbol);
          if (!cfg || !market || !orderbookCanRunV212(symbol)) return;
          const socket = orderbookSockets.get(symbol);
          const last = Number(orderbookLastMessageAt.get(symbol) || 0);
          const staleLimit = Number(market.staleMs || ORDERBOOK_STALE_MS);
          // ORAI controller owns its retries: do not interrupt its REST rescue.
          const stale = symbol !== ORAI_SYMBOL && last > 0 && now - last > staleLimit;
          const disconnected = !socket || socket.readyState === WebSocket.CLOSING || socket.readyState === WebSocket.CLOSED;
          if (stale || disconnected) {
            setOrderbookStatus(symbol, stale ? `Dati fermi · riconnessione ${market.exchange}…` : `Riconnessione ${market.exchange}…`, 'loading');
            closeOrderbookSocket(symbol);
            startOrderbook(symbol);
          }
        });
      }

      // Initialize independently of details, mining, burn and news startup.
      function restoreOrderbookPanelsV134(){
        Object.keys(ASSETS).forEach(symbol=>{
          try { setupOrderbookSection(symbol); }
          catch(error){ console.warn('Orderbook panel',symbol,error); }
        });
        Object.keys(ASSETS).forEach(symbol=>{try{
          if(orderbookCanRunV212(symbol)){if(!orderbookSockets.get(symbol))startOrderbook(symbol);}
          else if(orderbookSockets.get(symbol))closeOrderbookSocket(symbol);
        }catch(error){console.warn('Orderbook connection',symbol,error);}});
        try{watchdogRealOrderbooks();}catch(error){console.warn('Orderbook watchdog',error);}
      }
      setTimeout(restoreOrderbookPanelsV134,0);
      window.addEventListener('pageshow',restoreOrderbookPanelsV134,{passive:true});
      window.addEventListener('online',restoreOrderbookPanelsV134,{passive:true});
      document.addEventListener('visibilitychange',()=>{if(!document.hidden)restoreOrderbookPanelsV134();});
      setInterval(()=>{if(!document.hidden)restoreOrderbookPanelsV134();},5000);

