      let raydiumBurnLoading = false;
      async function updateRaydiumBurnData() {
        if (raydiumBurnLoading) return;
        raydiumBurnLoading = true;
        try {
          const snapshot = await fetchRayBuybackWalletSnapshot();
          try {
            const daily = await fetchRayBuybackTodayAtomic(snapshot);
            renderExactRaydiumBuyback(snapshot, daily);
          } catch (historyError) {
            // Il cumulativo non deve sparire se l'RPC consente i saldi ma limita lo
            // storico. In questo caso il giornaliero continua dal checkpoint locale.
            setDailyBurnFromCumulativeAtomic(
              'RAYUSDT',
              snapshot.amountAtomic,
              snapshot.decimals,
              'RAY',
              'Raydium Docs · Solana RPC ' + snapshot.source,
              'Cumulativo live verificato on-chain. Storico giornaliero non disponibile (' + (historyError?.message || 'errore RPC') + '), quindi il giornaliero usa il checkpoint locale.'
            );
            const status = $('ray-burn-status');
            const source = $('ray-burn-source');
            if (status) {
              status.textContent = 'Cumulativo RAY live · giornaliero dal checkpoint · LIVE';
              status.className = 'burn-status warn';
            }
            if (source) source.textContent = t('burnSource') + ': Raydium Docs · Solana RPC ' + snapshot.source;
          }
        } catch (error) {
          const reason = 'Buyback RAY non raggiungibile: ' + (error?.message || 'errore sconosciuto');
          const cached = showCachedBurnValue('RAYUSDT', reason);
          if (!cached) {
            setBurnUnavailable('RAYUSDT', reason, false);
          }
          const status = $('ray-burn-status');
          if (status) {
            status.textContent = cached ? 'RAY · REAL-TIME · ULTIMO DATO VALIDO' : 'RAY · REAL-TIME';
            status.className = 'burn-status warn';
            status.title = reason;
          }
          // Forza la riscoperta degli RPC ufficiali al prossimo ciclo.
          rayRpcDiscoveryCache.expiresAt = 0;
        } finally {
          raydiumBurnLoading = false;
        }
      }

      async function fetchErc20TotalSupplyAtomic(contractAddress) {
        let lastError = new Error('RPC Base non disponibile');
        for (const endpoint of BASE_RPC_ENDPOINTS) {
          try {
            const [supplyHex, decimalsHex] = await Promise.all([
              fetchJsonRpcWithTimeout(endpoint, 'eth_call', [{ to: contractAddress, data: '0x18160ddd' }, 'latest'], 9000),
              fetchJsonRpcWithTimeout(endpoint, 'eth_call', [{ to: contractAddress, data: '0x313ce567' }, 'latest'], 9000)
            ]);
            if (!/^0x[0-9a-f]+$/i.test(String(supplyHex))) throw new Error('totalSupply ERC-20 non valida');
            const decimals = Number(BigInt(decimalsHex));
            if (!Number.isInteger(decimals) || decimals < 0 || decimals > 36) throw new Error('Decimali ERC-20 non validi');
            return { amountAtomic: BigInt(supplyHex), decimals, source: new URL(endpoint).hostname };
          } catch (error) { lastError = error; }
        }
        throw lastError;
      }

