      async function fetchTextWithTimeout(url, timeout = 7500) {
        const controller = new AbortController();
        const timer = setTimeout(() => controller.abort(), timeout);
        try {
          const response = await fetch(url, { signal: controller.signal, cache: 'no-store' });
          if (!response.ok) throw new Error('HTTP ' + response.status);
          return await response.text();
        } finally { clearTimeout(timer); }
      }


      function parseRpcHexBigInt(value, label = 'Valore RPC') {
        const text = String(value ?? '');
        if (!/^0x[0-9a-f]+$/i.test(text)) throw new Error(label + ' non valido');
        return BigInt(text);
      }

      async function fetchBnbRpcFromEndpoint(endpoint, method, params, timeout = 9000) {
        return fetchJsonRpcWithTimeout(endpoint, method, params, timeout);
      }

      async function fetchBnbBlock(endpoint, blockTag) {
        const block = await fetchBnbRpcFromEndpoint(endpoint, 'eth_getBlockByNumber', [blockTag, false], 9000);
        if (!block?.number || !block?.timestamp) throw new Error('Blocco BSC non disponibile');
        return {
          number: parseRpcHexBigInt(block.number, 'Numero blocco BSC'),
          timestamp: parseRpcHexBigInt(block.timestamp, 'Timestamp blocco BSC')
        };
      }

      function readBnbMidnightCache() {
        try {
          const parsed = JSON.parse(localStorage.getItem(BNB_MIDNIGHT_BLOCK_CACHE_KEY) || '{}');
          return parsed && typeof parsed === 'object' ? parsed : {};
        } catch (_) { return {}; }
      }

      function saveBnbMidnightCache(value) {
        try { localStorage.setItem(BNB_MIDNIGHT_BLOCK_CACHE_KEY, JSON.stringify(value)); }
        catch (_) {}
      }

      async function findBnbBlockBeforeUtcMidnight(endpoint, latestBlock) {
        const targetTimestamp = BigInt(Math.floor(utcBurnMidnight() / 1000));
        if (latestBlock.timestamp < targetTimestamp) return latestBlock.number;

        let span = 200000n;
        let low = latestBlock.number > span ? latestBlock.number - span : 0n;
        let lowBlock = await fetchBnbBlock(endpoint, '0x' + low.toString(16));
        while (low > 0n && lowBlock.timestamp >= targetTimestamp) {
          span *= 2n;
          low = latestBlock.number > span ? latestBlock.number - span : 0n;
          lowBlock = await fetchBnbBlock(endpoint, '0x' + low.toString(16));
        }

        let high = latestBlock.number;
        while (low + 1n < high) {
          const mid = (low + high) / 2n;
          const block = await fetchBnbBlock(endpoint, '0x' + mid.toString(16));
          if (block.timestamp < targetTimestamp) low = mid;
          else high = mid;
        }
        return low;
      }

      async function resolveBnbMidnightCheckpoint(endpoint, latestBlock) {
        const day = utcBurnDayKey();
        const cached = readBnbMidnightCache();
        if (cached.day === day && /^\d+$/.test(String(cached.blockNumber || '')) && /^\d+$/.test(String(cached.balanceWei || ''))) {
          return { blockNumber: BigInt(cached.blockNumber), balanceWei: BigInt(cached.balanceWei), cached: true };
        }

        const blockNumber = await findBnbBlockBeforeUtcMidnight(endpoint, latestBlock);
        const blockTag = '0x' + blockNumber.toString(16);
        const balanceHex = await fetchBnbRpcFromEndpoint(endpoint, 'eth_getBalance', [BNB_BURN_ADDRESS, blockTag], 10000);
        const balanceWei = parseRpcHexBigInt(balanceHex, 'Saldo BNB di mezzanotte');
        saveBnbMidnightCache({ day, blockNumber: blockNumber.toString(), balanceWei: balanceWei.toString(), savedAt: Date.now() });
        return { blockNumber, balanceWei, cached: false };
      }

      async function fetchCurrentBnbBlackholeBalance() {
        let lastError = new Error('RPC BNB Smart Chain non raggiungibile');
        for (const endpoint of BNB_RPC_ENDPOINTS) {
          try {
            const latestBlock = await fetchBnbBlock(endpoint, 'latest');
            const latestTag = '0x' + latestBlock.number.toString(16);
            const balanceHex = await fetchBnbRpcFromEndpoint(endpoint, 'eth_getBalance', [BNB_BURN_ADDRESS, latestTag], 9000);
            return { endpoint, latestBlock, balanceWei: parseRpcHexBigInt(balanceHex, 'Saldo blackhole BNB') };
          } catch (error) { lastError = error; }
        }
        throw lastError;
      }

      async function updateBnbBurnData() {
        const status = $('bnb-burn-status');
        if (status) { status.textContent = t('burnUpdating'); status.className = 'burn-status'; }
        let lastError = new Error('Burn BNB non disponibile');

        // Percorso principale: saldo del blackhole al blocco precedente alle 00:00
        // confrontato con il saldo al blocco più recente.
        for (const endpoint of BNB_RPC_ENDPOINTS) {
          try {
            const latestBlock = await fetchBnbBlock(endpoint, 'latest');
            const checkpoint = await resolveBnbMidnightCheckpoint(endpoint, latestBlock);
            const latestTag = '0x' + latestBlock.number.toString(16);
            const currentHex = await fetchBnbRpcFromEndpoint(endpoint, 'eth_getBalance', [BNB_BURN_ADDRESS, latestTag], 9000);
            const currentWei = parseRpcHexBigInt(currentHex, 'Saldo blackhole BNB');
            const dailyWei = currentWei >= checkpoint.balanceWei ? currentWei - checkpoint.balanceWei : 0n;
            setExactDailyBurnAtomic(
              'BNBUSDT',
              dailyWei,
              currentWei,
              18,
              'BNB',
              'BNB Smart Chain RPC · ' + new URL(endpoint).hostname,
              'Somma netta dei BNB nativi arrivati oggi al blackhole ufficiale ' + BNB_BURN_ADDRESS + '. È una misura on-chain del blackhole; il BEP-95 viene mostrato separatamente come dato ufficiale, senza sommarlo a questa metrica. Blocco base: ' + checkpoint.blockNumber.toString() + '; blocco corrente: ' + latestBlock.number.toString() + '.'
            );
            return;
          } catch (error) { lastError = error; }
        }

        // Fallback: se un RPC non consente la lettura dello stato storico, conserva
        // un checkpoint locale giornaliero e continua ad aggiornare il saldo LIVE.
        try {
          const current = await fetchCurrentBnbBlackholeBalance();
          setDailyBurnFromCumulativeAtomic(
            'BNBUSDT',
            current.balanceWei,
            18,
            'BNB',
            'BNB Smart Chain RPC · checkpoint locale',
            'Fallback on-chain sul saldo nativo del blackhole ' + BNB_BURN_ADDRESS + '. Il provider non ha consentito la lettura dello stato al blocco di mezzanotte; il calcolo parte dal primo checkpoint locale disponibile.'
          );
          return;
        } catch (error) { lastError = error; }

        setBurnUnavailable('BNBUSDT', 'Burn BNB non raggiungibile: ' + (lastError?.message || 'errore sconosciuto'));
        setBurnMetricSnapshot('BNBUSDT');
      }

      function parseEthereumBurnText(text) {
        const clean = String(text || '').replace(/<[^>]*>/g, ' ').replace(/&nbsp;/gi, ' ').replace(/\s+/g, ' ');
        const match = clean.match(/in\s+total\s+([0-9][0-9,.]*)\s*ETH\s+(?:have\s+been\s+)?burned/i)
          || clean.match(/(?:total\s+(?:eth\s+)?burned|eth\s+burned)[^0-9]{0,80}([0-9][0-9,.]*)\s*ETH/i)
          || clean.match(/([0-9][0-9,.]*)\s*ETH[^.]{0,80}(?:total\s+burned|burned\s+total|have\s+been\s+burned)/i);
        if (!match) throw new Error('Totale ETH bruciato non trovato');
        const exact = match[1].replace(/,/g, '');
        if (!/^\d+(?:\.\d+)?$/.test(exact)) throw new Error('Formato burn ETH non valido');
        return exact;
      }

