      function parseSolanaBaseFees24h(text) {
        const plain = String(text || '').replace(/<[^>]*>/g, ' ').replace(/&nbsp;/gi, ' ').replace(/\s+/g, ' ');
        const match = plain.match(/Total Base Fees:\s*([\d,.]+)/i)
          || plain.match(/Total Base Fees[^\d]{0,30}([\d,.]+)/i);
        if (!match) throw new Error('Commissioni base SOL 24h non trovate');
        const normalized = match[1].replace(/,/g, '');
        const baseFees = Number(normalized);
        if (!Number.isFinite(baseFees) || baseFees < 0) throw new Error('Formato commissioni base SOL non valido');
        return baseFees;
      }

      function parseSolanaLastEpochBurn(text) {
        const plain = String(text || '').replace(/<[^>]*>/g, ' ').replace(/&nbsp;/gi, ' ').replace(/\s+/g, ' ');
        const match = plain.match(/last epoch Solana burned\s*([\d,.]+)\s*SOL/i)
          || plain.match(/nell['’]ultima epoca Solana ha bruciato\s*([\d,.]+)\s*SOL/i)
          || plain.match(/last epoch[^.]{0,120}burned\s*([\d,.]+)\s*SOL/i);
        if (!match) throw new Error('Burn SOL dell’ultima epoca non trovato');
        const value = Number(match[1].replace(/,/g, ''));
        if (!Number.isFinite(value) || value < 0) throw new Error('Formato burn SOL epoca non valido');
        return value;
      }


