      function utcDayElapsedFraction(now = new Date()) {
        const start = utcBurnMidnight(now.getTime());
        const end = burnRomeNextMidnight(now.getTime());
        const dayDuration = Math.max(1, end - start);
        const elapsed = Math.max(0, now.getTime() - start);
        return Math.min(1, elapsed / dayDuration);
      }

