      async function updateOreBurnData() {
        showOreBurnImmediateState();
        const refreshButton = $('ore-burn-refresh');
        if (refreshButton) refreshButton.disabled = true;

        let dailyError = null;
        let dailyEndpoint = '';
        for (const endpoint of SOLANA_SUPPLY_RPC_ENDPOINTS) {
          try {
            const daily = await fetchOreDailyAndSupply(endpoint);
            setOreDailyVisible(daily);
            dailyEndpoint = endpoint;
            dailyError = null;
            break;
          } catch (error) { dailyError = error; }
        }

        if (dailyError) {
          const cached = readBurnCache()?.OREUSD;
          const value = $('ore-burn-total');
          if (value && !cached?.displayValue) {
            value.textContent = 'In attesa LIVE…';
            value.title = 'Valore provvisorio: il provider Solana non ha risposto. Nuovo tentativo automatico tra 50 secondi.';
          }
          const status = $('ore-burn-status');
          if (status) {
            status.textContent = 'RPC giornaliero non raggiungibile · riconnessione automatica';
            status.className = 'burn-status warn';
            status.title = dailyError?.message || '';
          }
        }

        // Historical total is intentionally independent: it must never block the daily value.
        let totalError = null;
        const endpoints = dailyEndpoint
          ? [dailyEndpoint, ...SOLANA_SUPPLY_RPC_ENDPOINTS.filter(item => item !== dailyEndpoint)]
          : [...SOLANA_SUPPLY_RPC_ENDPOINTS];
        for (const endpoint of endpoints) {
          try {
            const index = await updateOreTotalIndex(endpoint);
            setOreTotalVisible(index, new URL(endpoint).hostname);
            totalError = null;
            break;
          } catch (error) { totalError = error; }
        }

        if (totalError) {
          const cached = readOreTotalBurnIndex();
          const cachedAtomic = /^\d+$/.test(String(cached.totalAtomic || '')) ? BigInt(cached.totalAtomic || '0') : 0n;
          setBurnSecondaryValue(
            'OREUSD',
            cachedAtomic > 0n
              ? (cached.complete ? '' : 'Parziale: ') + oreDisplayFromAtomic(cachedAtomic)
              : '0 ORE · RPC non disponibile',
            'Ultimo totale indicizzato localmente. Nuovo tentativo automatico tra 50 secondi.'
          );
        }

        if (refreshButton) refreshButton.disabled = false;
      }

