      const LUNA_BURN_ADDRESS = 'terra1sk06e3dyexuq4shw77y3dsv480xv42mq73anxu';
      let lunaBurnLoading = false;

      function lunaCoinAmountMicro(amount) {
        const coins = Array.isArray(amount) ? amount : (amount ? [amount] : []);
        return coins.reduce((sum, coin) => {
          if (coin && typeof coin === 'object') {
            const denom = String(coin.denom ?? coin.denomination ?? '').toLowerCase();
            const raw = String(coin.amount ?? coin.value ?? '').trim();
            if (denom === 'uluna' && /^\d+$/.test(raw)) return sum + BigInt(raw);
          }
          if (typeof coin === 'string') {
            const match = coin.trim().match(/^(\d+)uluna$/i);
            if (match) return sum + BigInt(match[1]);
          }
          return sum;
        }, 0n);
      }

      function sumLunaBurnMessages(payload) {
        let totalMicro = 0n;
        const visited = new WeakSet();

        function walk(node) {
          if (!node || typeof node !== 'object' || visited.has(node)) return;
          visited.add(node);

          const wrapped = node.value && typeof node.value === 'object' ? node.value : node;
          const toAddress = wrapped.to_address ?? wrapped.toAddress ?? '';
          const messageType = String(node['@type'] ?? node.type_url ?? node.type ?? '').toLowerCase();
          const isBankSend = messageType.includes('msgsend') || messageType.includes('bank/msgsend') || messageType.includes('cosmos.bank');

          if (toAddress === LUNA_BURN_ADDRESS && (isBankSend || wrapped.amount)) {
            totalMicro += lunaCoinAmountMicro(wrapped.amount);
            return;
          }

          Object.values(node).forEach(walk);
        }

        walk(payload);
        return totalMicro;
      }

      function lunaBurnTxRows(payload) {
        if (Array.isArray(payload?.txs)) return payload.txs;
        if (Array.isArray(payload?.transactions)) return payload.transactions;
        if (Array.isArray(payload?.result?.txs)) return payload.result.txs;
        if (Array.isArray(payload?.data?.txs)) return payload.data.txs;
        return [];
      }

      async function fetchLunaBurnFromFcd() {
        let offset = '0';
        let totalMicro = 0n;
        let pages = 0;
        const seenOffsets = new Set();

        while (pages < 20 && !seenOffsets.has(offset)) {
          seenOffsets.add(offset);
          const url = 'https://phoenix-fcd.terra.dev/v1/txs?offset=' + encodeURIComponent(offset)
            + '&limit=100&account=' + encodeURIComponent(LUNA_BURN_ADDRESS);
          const payload = await fetchJsonWithTimeout(url, 10000);
          const rows = lunaBurnTxRows(payload);
          totalMicro += sumLunaBurnMessages(rows);
          pages += 1;

          const nextRaw = payload?.next ?? payload?.pagination?.next ?? payload?.pagination?.next_offset ?? null;
          const next = nextRaw === null || nextRaw === undefined ? '' : String(nextRaw).trim();
          if (!next || next === '0' || !rows.length) break;
          offset = next;
        }

        if (totalMicro <= 0n) throw new Error('Nessun trasferimento LUNA trovato nel feed FCD');
        return { totalMicro, source: 'Terra FCD · phoenix-1' };
      }

      async function fetchLunaBurnFromLcd() {
        throw new Error('Terra LCD disattivato: uso FCD/fallback senza endpoint LCD');
      }

      async function fetchLunaBurnTotalMicro() {
        const errors = [];

        try {
          return await fetchLunaBurnFromLcd();
        } catch (error) {
          errors.push('LCD: ' + (error?.message || error));
        }

        try {
          return await fetchLunaBurnFromFcd();
        } catch (error) {
          errors.push('FCD: ' + (error?.message || error));
        }

        throw new Error('Fonti Terra LUNA non raggiungibili · ' + errors.join(' · '));
      }

