      function setupBurnLiveValueFeedback() {
        const values = document.querySelectorAll('.burn-value');
        values.forEach(element => {
          if (element.dataset.burnLiveObserver === 'true') return;
          element.dataset.burnLiveObserver = 'true';
          let last = element.textContent?.trim() || '';
          const observer = new MutationObserver(() => {
            const next = element.textContent?.trim() || '';
            if (!next || next === last) return;
            last = next;
            element.classList.remove('burn-value-live-change');
            void element.offsetWidth;
            element.classList.add('burn-value-live-change');
          });
          observer.observe(element, { childList: true, characterData: true, subtree: true });
        });
      }


