      async function loadCoinGeckoAsset(symbol, token) {
        const cfg = ASSETS[symbol];
        const selection = getTimeframeConfig();
        clearError(symbol);
        $(cfg.key + '-loader').style.display = 'grid';
        $(cfg.key + '-tick').textContent = symbol === TAI_SYMBOL
          ? (selection.fullHistory ? 'TARS AI · caricamento dal primo dato a oggi…' : `TARS AI · caricamento storico ${selection.label}…`)
          : (selection.fullHistory ? 'Caricamento storico completo…' : `Caricamento storico ${selection.label}…`);
        try {
          const [sourceCandles, coins] = await Promise.all([
            symbol === TAI_SYMBOL
              ? fetchTaiCompleteHistory()
              : fetchCoinGeckoHistory(symbol),
            fetchCoinGeckoMarkets().catch(error => {
              console.warn('CoinGecko market snapshot', symbol, error);
              return [];
            })
          ]);
          if (token !== loadToken) return;
          if (!sourceCandles.length) throw new Error('Candele CoinGecko non disponibili');
          sourceCandleHistory[symbol] = sourceCandles;
          setHistoryLoadState(symbol, sourceCandles, selection, token);
          const aggregated = aggregateCandles(sourceCandles, selection.bucket, keepsAllLoadedCandles(selection) ? Infinity : 300);
          if (!aggregated.length) throw new Error('Aggregazione CoinGecko non disponibile');
          applyAggregatedHistory(symbol, aggregated);
          if (symbol === TAI_SYMBOL && aggregated.length) {
            const bundle = charts[symbol];
            // TARS AI deve mostrare l'intero storico disponibile sul primo frame,
            // anche se una precedente vista a una sola candela era stata salvata.
            if (bundle) {
              bundle.viewLocked = false;
              bundle.savedLogicalRange = null;
              bundle.savedVisibleRange = null;
              try { bundle.chart.timeScale().fitContent(); } catch (_) {}
              Object.values(bundle.indicators || {}).forEach(indicator => {
                try { indicator.chart.timeScale().fitContent(); } catch (_) {}
              });
              requestAnimationFrame(() => {
                try { bundle.chart.timeScale().fitContent(); } catch (_) {}
              });
              setTimeout(() => {
                try { bundle.chart.timeScale().fitContent(); } catch (_) {}
              }, 120);
            }
            const firstDate = new Date(aggregated[0].time * 1000).toLocaleDateString(currentLocale());
            const lastDate = new Date(aggregated[aggregated.length - 1].time * 1000).toLocaleDateString(currentLocale());
            $(cfg.key + '-tick').textContent = `Storico completo · ${aggregated.length} candele · ${firstDate} → ${lastDate} · LIVE 1s`;
          }
          const coin = coins.find(item => item.id === cfg.supplyId);
          if (coin && symbol !== TAI_SYMBOL) updateCoinGeckoMarket(symbol, coin);
          else if (symbol !== TAI_SYMBOL || !Number.isFinite(latestMarketPrices[symbol])) setPrice(symbol, aggregated[aggregated.length - 1].close, false);
          $(cfg.key + '-loader').style.display = 'none';
        } catch (error) {
          console.error(symbol, error);
          if (symbol === TAI_SYMBOL && Number.isFinite(latestMarketPrices[TAI_SYMBOL])) {
            $(cfg.key + '-loader').style.display = 'none';
            clearError(symbol);
            return;
          }
          showError(symbol, symbol === TAI_SYMBOL ? 'Storico TARS AI in riconnessione · Bitvavo/DEX/CoinGecko. Il prezzo LIVE continua ad aggiornarsi.' : 'Impossibile caricare i dati CoinGecko. Controlla la connessione Internet e ricarica la pagina.');
          throw error;
        }
      }

      // V94 — se il WebSocket CEX è fresco, DEX/CoinGecko restano solo fallback e non sovrascrivono il LIVE.
      function altCexFreshV94(symbol, maxAge = 15000) {
        const store = window.__V94_ALT_LIVE_AT__ || {};
        const at = Number(store[symbol] || 0);
        return at > 0 && (Date.now() - at) < maxAge;
      }

      function getOrePair(payload) {
        const pairs = Array.isArray(payload?.pairs) ? payload.pairs : [];
        return pairs.find(pair => pair.pairAddress === ORE_POOL_ADDRESS) || payload?.pair || pairs[0] || null;
      }

      function updateOrePair(pair) {
        if (!pair) return;
        const cfg = ASSETS[ORE_SYMBOL];
        const price = Number(pair.priceUsd);
        const change = Number(pair.priceChange?.h24);
        const volume24h = Number(pair.volume?.h24);
        const liquidity = Number(pair.liquidity?.usd);
        const fdv = Number(pair.fdv);
        const cexFresh = altCexFreshV94(ORE_SYMBOL);
        if (Number.isFinite(price) && price > 0 && !cexFresh) {
          window.__markFeed237(ORE_SYMBOL, 'DEX Screener', Date.now(), false);
          setPrice(ORE_SYMBOL, price);
        }

        const changeEl = $(cfg.key + '-change');
        if (Number.isFinite(change) && !cexFresh) {
          changeEl.className = 'change ' + (change >= 0 ? 'positive' : 'negative');
          const orePct = Math.abs(change).toLocaleString('it-IT', {
            minimumFractionDigits: 2,
            maximumFractionDigits: 2,
            useGrouping: false
          });
          changeEl.textContent = (change >= 0 ? '▲ +' : '▼ −') + orePct + '% · 24h';
          updateTabChange(ORE_SYMBOL, change);
        }
        if (!cexFresh && Number.isFinite(volume24h)) $(cfg.key + '-high').textContent = formatVolume(volume24h, cfg.quote);
        // Liquidità e FDV sono metriche DEX e continuano a essere aggiornate anche con LBank LIVE.
        $(cfg.key + '-low').textContent = Number.isFinite(liquidity) ? formatVolume(liquidity, 'USD') : $(cfg.key + '-low').textContent;
        refreshDerivedLowReference(ORE_SYMBOL);
        $(cfg.key + '-volume').textContent = Number.isFinite(fdv) ? formatVolume(fdv, 'USD') : $(cfg.key + '-volume').textContent;
      }

      function updateOreLiveCandle(price) {
        if (!Number.isFinite(price) || !charts[ORE_SYMBOL]) return;
        const now = Math.floor(Date.now() / 1000);
        const bucket = timeframeBucketStart(now, getTimeframeConfig().bucket);
        const history = candleHistory[ORE_SYMBOL] || (candleHistory[ORE_SYMBOL] = []);
        const last = history[history.length - 1];
        let candle;

        if (last && last.time === bucket) {
          candle = {
            time: bucket,
            open: last.open,
            high: Math.max(last.high, price),
            low: Math.min(last.low, price),
            close: price
          };
        } else if (!last || bucket > last.time) {
          oreCurrentVolume = 0;
          candle = { time: bucket, open: price, high: price, low: price, close: price };
        } else {
          return;
        }

        updateLiveCandle(ORE_SYMBOL, candle, oreCurrentVolume);
      }

