      // Rotellina verticale del mouse -> scorrimento orizzontale della fila monete.
      // Il comportamento si attiva solo quando il puntatore è sopra la fila e
      // quando esiste effettivamente contenuto da scorrere lateralmente.
      $('assetSwitcher').addEventListener('wheel', event => {
        const scroller = event.currentTarget;
        const maxScrollLeft = scroller.scrollWidth - scroller.clientWidth;
        if (maxScrollLeft <= 1) return;

        const delta = Math.abs(event.deltaX) > Math.abs(event.deltaY)
          ? event.deltaX
          : event.deltaY;
        if (!delta) return;

        const atStart = scroller.scrollLeft <= 0;
        const atEnd = scroller.scrollLeft >= maxScrollLeft - 1;
        const movingLeft = delta < 0;
        const movingRight = delta > 0;

        // Ai bordi lascia proseguire lo scorrimento verticale della pagina.
        if ((atStart && movingLeft) || (atEnd && movingRight)) return;

        event.preventDefault();
        scroller.scrollLeft += delta;
      }, { passive: false });

