        if (Number.isFinite(low)) $('tai-low').textContent = formatPrice(low / eurPerUsdc, ASSETS[TAI_SYMBOL].decimals, 'USDT');
        if (Number.isFinite(volumeQuote)) $('tai-volume').textContent = formatVolume(volumeQuote / eurPerUsdc, 'USDT');
        const now = v94LiveTime();
        $('tai-tick').textContent = `${t('updated')} ${now} · LIVE · Bitvavo TAI/EUR → USDT`;
        $('tai-loader').style.display = 'none';
