/* ===== JS originale 20/107: upper-low-js-hard-blink-fix ===== */

(function(){
  'use strict';
  const BLINK_MS = 320;
  const blinkTimers = new WeakMap();
  const blinkPhase = new WeakMap();

  function alertKind(tab){
    if (!tab || !tab.classList) return null;
    if (tab.classList.contains('live-lower') || tab.classList.contains('lower-blink')) return 'low';
    if (tab.classList.contains('live-upper') || tab.classList.contains('upper-blink')) return 'upper';
    return null;
  }

  function paint(tab, kind, on){
    const light = document.body.classList.contains('light');
    let background, border, shadow;

    if (kind === 'upper') {
      if (on) {
        background = light ? '#facc15' : '#b88900';
        border = '#fde047';
        shadow = '0 0 0 3px rgba(250,204,21,.68), 0 0 26px rgba(250,204,21,.72)';
      } else {
        background = light ? '#fff4ad' : '#2c2100';
        border = light ? '#d5ae20' : '#705900';
        shadow = '0 0 0 1px rgba(250,204,21,.10), 0 0 2px rgba(250,204,21,.05)';
      }
    } else {
      if (on) {
        background = light ? '#ef4444' : '#b51632';
        border = '#ff7a86';
        shadow = '0 0 0 3px rgba(239,68,68,.68), 0 0 26px rgba(239,68,68,.72)';
      } else {
        background = light ? '#ffd0d5' : '#31070e';
        border = light ? '#cf6973' : '#781526';
        shadow = '0 0 0 1px rgba(239,68,68,.10), 0 0 2px rgba(239,68,68,.05)';
      }
    }

    // Inline !important batte tutte le vecchie regole CSS !important della dashboard.
    tab.style.setProperty('animation', 'none', 'important');
    tab.style.setProperty('-webkit-animation', 'none', 'important');
    tab.style.setProperty('background', background, 'important');
    tab.style.setProperty('background-color', background, 'important');
    tab.style.setProperty('border-color', border, 'important');
    tab.style.setProperty('box-shadow', shadow, 'important');
    tab.style.setProperty('opacity', '1', 'important');
  }

  function clearPaint(tab){
    ['animation','-webkit-animation','background','background-color','border-color','box-shadow','opacity'].forEach(prop => {
      tab.style.removeProperty(prop);
    });
  }

  function stopBlink(tab){
    const timer = blinkTimers.get(tab);
    if (timer) clearInterval(timer);
    blinkTimers.delete(tab);
    blinkPhase.delete(tab);
    clearPaint(tab);
  }

  function startBlink(tab){
    const kind = alertKind(tab);
    if (!kind) {
      stopBlink(tab);
      return;
    }
    if (blinkTimers.has(tab)) {
      // Cambia immediatamente colore se LOW prende priorità su UPPER.
      paint(tab, kind, blinkPhase.get(tab) !== false);
      return;
    }

    let on = true;
    blinkPhase.set(tab, on);
    paint(tab, kind, on);
    const timer = setInterval(() => {
      const currentKind = alertKind(tab);
      if (!currentKind || !document.documentElement.contains(tab)) {
        stopBlink(tab);
        return;
      }
      on = !on;
      blinkPhase.set(tab, on);
      paint(tab, currentKind, on);
    }, BLINK_MS);
    blinkTimers.set(tab, timer);
  }

  function syncTab(tab){
    if (alertKind(tab)) startBlink(tab);
    else stopBlink(tab);
  }

  function syncAll(){
    document.querySelectorAll('.asset-tab').forEach(syncTab);
  }

  function init(){
    syncAll();
    const observer = new MutationObserver(mutations => {
      for (const mutation of mutations) {
        if (mutation.type === 'attributes' && mutation.attributeName === 'class' && mutation.target.classList?.contains('asset-tab')) {
          syncTab(mutation.target);
        }
      }
    });
    observer.observe(document.body, {subtree:true, attributes:true, attributeFilter:['class']});

    // Cambio tema: ridisegna subito il colore dell'alert attivo.
    const bodyObserver = new MutationObserver(syncAll);
    bodyObserver.observe(document.body, {attributes:true, attributeFilter:['class']});
    window.addEventListener('pageshow', syncAll);
    document.addEventListener('visibilitychange', () => { if (!document.hidden) syncAll(); });
  }

  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', init, {once:true});
  else init();
})();


