/* ===== JS originale 22/107: movement-cursor-tooltip-glass-effect-js-final ===== */

(function(){
  'use strict';

  function isAlert(tab){
    return tab.classList.contains('live-upper') ||
           tab.classList.contains('upper-blink') ||
           tab.classList.contains('live-lower') ||
           tab.classList.contains('lower-blink');
  }

  // Le vecchie patch SU/GIU dipingevano direttamente lo style inline.
  // Le rimuoviamo soltanto quando si tratta del vecchio pulse movement,
  // cosi il nuovo layer vetro ::after resta l'unico effetto sul quadrante.
  function clearLegacyMovementInline(tab){
    if (!tab || isAlert(tab)) return;
    if (!(tab.classList.contains('live-up') || tab.classList.contains('live-down'))) return;
    if (tab.dataset.movePulsePainted !== '1') return;
    ['background','background-color','border-color','box-shadow'].forEach(function(prop){
      tab.style.removeProperty(prop);
    });
    delete tab.dataset.movePulsePainted;
  }

  function updateCursor(tab, clientX, clientY){
    if (isAlert(tab)) return;
    const rect = tab.getBoundingClientRect();
    if (!rect.width || !rect.height) return;
    const x = Math.max(0, Math.min(100, ((clientX - rect.left) / rect.width) * 100));
    const y = Math.max(0, Math.min(100, ((clientY - rect.top) / rect.height) * 100));
    tab.style.setProperty('--cursor-x', x.toFixed(1) + '%');
    tab.style.setProperty('--cursor-y', y.toFixed(1) + '%');
  }

  function bindTab(tab){
    if (tab.dataset.cursorGlassBound === '1') return;
    tab.dataset.cursorGlassBound = '1';

    tab.addEventListener('pointermove', function(ev){
      updateCursor(tab, ev.clientX, ev.clientY);
    }, {passive:true});

    tab.addEventListener('pointerleave', function(){
      tab.style.setProperty('--cursor-x', '50%');
      tab.style.setProperty('--cursor-y', '50%');
    }, {passive:true});

    tab.addEventListener('touchstart', function(ev){
      const t = ev.touches && ev.touches[0];
      if (t) updateCursor(tab, t.clientX, t.clientY);
    }, {passive:true});
  }

  function sync(){
    document.querySelectorAll('.asset-tab').forEach(function(tab){
      bindTab(tab);
      clearLegacyMovementInline(tab);
    });
  }

  function init(){
    sync();
    const observer = new MutationObserver(function(){ sync(); });
    observer.observe(document.body, {subtree:true, attributes:true, attributeFilter:['class','style']});
    window.addEventListener('pageshow', sync);
    document.addEventListener('visibilitychange', function(){ if (!document.hidden) sync(); });
  }

  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', init, {once:true});
  else init();
})();


