    marketCap: 28219526,
    circulatingSupply: 489649,
    totalSupply: 484440.52,
    maxSupply: 3000000,
    low24: 52.77,
    high24: 59.99,
    /* Ultimo snapshot reale visibile nel file/screenshot dell'utente.
       Serve SOLO come primo frame: ogni risposta LIVE valida lo sostituisce. */
    hashrate: 1.967,
    difficulty: 0.05274,
    productionCost: 49.35,
    avgDeployed: 5.5554,
    avgMiners: 116,
    liquidity: 628860,
    holders: 33073,
    stakingApy: 14.4,
