      const dashboardPrice=readDashboardPrice('ore-tab-price');
      if (dashboardPrice) state.price=dashboardPrice;
      const circ=pick(state.circulatingSupply,VERIFIED.circulatingSupply);
      const price=pick(state.price,VERIFIED.price);
