    const topPoolShare = num(data.topPoolShare);

    e.primary.textContent = hashrate ? fmtHashrate(hashrate) : 'Ultimo dato reale non disponibile';
    e.secondary.textContent = difficulty ? fmtDifficulty(difficulty) : 'Ultimo dato reale non disponibile';
    e.primary.dataset.btcMiningReal = hashrate ? 'true' : 'false';
    e.secondary.dataset.btcMiningReal = difficulty ? 'true' : 'false';

    const set = (id, value) => { const el = byId(id); if (el) el.textContent = value; };
    set('btc-mining-height', height ? '#' + fmtInt(height) : 'Ultimo dato reale');
    set('btc-mining-reward', reward ? fmt(reward, 4) + ' BTC' : 'Ultimo dato reale');
    set('btc-mining-retarget', change !== null ? (change >= 0 ? '+' : '') + fmt(change, 2) + '%' : 'Ultimo dato reale');
    set('btc-mining-remaining', remaining !== null && remaining >= 0 ? fmtInt(remaining) : 'Ultimo dato reale');
    set('btc-mining-progress', progress !== null ? fmt(progress, 2) + '%' : 'Ultimo dato reale');
    set('btc-mining-blocktime', avgBlockTime !== null ? fmtDurationSeconds(avgBlockTime) : 'Ultimo dato reale');
    if (eta) {
      try {
        set('btc-mining-eta', new Intl.DateTimeFormat('it-IT', {
          day:'2-digit', month:'2-digit', hour:'2-digit', minute:'2-digit'
        }).format(new Date(eta)));
      } catch (_) { set('btc-mining-eta', 'Ultimo dato reale'); }
    } else set('btc-mining-eta', 'Ultimo dato reale');
    set('btc-mining-top-pool',
      topPool ? topPool + (topPoolShare !== null ? ' · ' + fmt(topPoolShare, 1) + '%' : '') : 'Ultimo dato reale');

    if (e.status) {
      const hText = height ? ' · Blocco #' + fmtInt(height) : '';
      if (mode === 'live') {
        e.status.textContent = 'MINING BTC LIVE' + hText + (quality ? ' · ' + quality : '');
        e.status.className = 'burn-status live';
      } else if (mode === 'cached') {
        e.status.textContent = 'Ultimo dato reale · ' + (cacheAge(data.updatedAt) || 'cache');
        e.status.className = 'burn-status warn';
      } else {
        e.status.textContent = 'BTC MINING · ULTIMO DATO REALE · SINCRONIZZAZIONE LIVE';
        e.status.className = 'burn-status warn';
      }
    }

    if (e.source) {
      e.source.textContent = 'Fonte LIVE: mempool.space · Bitcoin mainnet';
    }

    if (e.updated) {
      const when = Number(data.updatedAt) || Date.now();
      try {
        e.updated.textContent = (mode === 'waiting' ? 'Tentativo LIVE ' : 'Aggiornato ') +
          new Intl.DateTimeFormat('it-IT', {
            day: undefined,
            month: undefined,
            hour:'2-digit', minute:'2-digit', second:'2-digit'
          }).format(new Date(when)) + ' · ogni 10 s';
      } catch (_) { e.updated.textContent = 'Aggiornamento automatico ogni 10 s'; }
    }

