(() => {
  'use strict';
  const NOTIFICATION_PREF_KEY = 'crypto-dashboard-threshold-notifications-v81';

  /* Migrazione V82: elimina eventuali target prezzo salvati dalle versioni precedenti. */
  try { localStorage.removeItem('crypto-dashboard-price-targets-v80'); } catch (_) {}

  function notificationsEnabled() {
    try { return localStorage.getItem(NOTIFICATION_PREF_KEY) === 'true'; } catch (_) { return false; }
  }
  function assetName(symbol) {
    const tab = Array.from(document.querySelectorAll('.asset-tab[data-symbol]'))
      .find(el => el.dataset.symbol === String(symbol));
    return tab?.querySelector('.asset-tab-copy strong')?.textContent?.trim() || String(symbol).replace(/USDT$|USD$/,'');
  }
  function money(value, cfg) {
    const n = Number(value);
    if (!Number.isFinite(n)) return '—';
    const decimals = Math.max(0, Math.min(10, Number(cfg?.decimals ?? 4)));
    const quote = String(cfg?.quote || (String(cfg?.symbol || '').endsWith('USD') ? 'USD' : 'USDT'));
    return n.toLocaleString('it-IT', { minimumFractionDigits: Math.min(decimals, 2), maximumFractionDigits: decimals }) + ' ' + quote;
  }
  function toast(kind, title, body) {
    let stack = document.getElementById('thresholdToastStackV80');
    if (!stack) {
      stack = document.createElement('div');
      stack.id = 'thresholdToastStackV80';
      stack.setAttribute('aria-live','polite');
      document.body.appendChild(stack);
    }
    const el = document.createElement('div');
    el.className = 'threshold-toast-v80 ' + kind;
    const strong = document.createElement('strong');
    strong.textContent = title;
    const span = document.createElement('span');
    span.textContent = body;
    el.append(strong, span);
    stack.appendChild(el);
    setTimeout(() => { el.style.opacity='0'; el.style.transform='translateY(-6px)'; }, 4700);
    setTimeout(() => el.remove(), 5200);
  }
  function systemNotify(title, body, tag) {
    if (!notificationsEnabled()) return false;
    try {
      if (!('Notification' in window) || Notification.permission !== 'granted') return false;
      const n = new Notification(title, { body, tag, renotify:true, silent:false });
      setTimeout(() => { try { n.close(); } catch (_) {} }, 9000);
      return true;
    } catch (_) { return false; }
  }

  window.__dashboardThresholdNotify = function(kind, symbol, threshold, cfg) {
    if (!notificationsEnabled()) return;
    const name = assetName(symbol);
    let title, body;
    if (kind === 'upper') {
      title = '🟡 ' + name + ' · UPPER raggiunto';
      body = 'Prezzo arrivato alla soglia UPPER: ' + money(threshold, cfg);
    } else if (kind === 'low') {
      title = '🔴 ' + name + ' · PRICE LOW raggiunto';
      body = 'Prezzo arrivato al PRICE LOW 24H: ' + money(threshold, cfg);
    } else {
      return;
    }
    systemNotify(title, body, 'crypto-' + kind + '-' + symbol);
    toast(kind, title, body);
  };

  /* Disabilita esplicitamente la vecchia funzione target se fosse rimasta in memoria. */
  try { delete window.__dashboardPriceTargetTick; } catch (_) { window.__dashboardPriceTargetTick = undefined; }
})();


