/* ===== JS originale 32/107: v89-icon-motion-js-fix-script ===== */

(() => {
  'use strict';

  function installToolbarMotion() {
    const settingsButton = document.getElementById('settingsToggle');
    const soundButton = document.getElementById('soundToggle');
    const settingsIcon = settingsButton && settingsButton.querySelector('.frontal-icon');
    const soundIcon = soundButton && soundButton.querySelector('.frontal-icon');

    if (!settingsButton || !soundButton || !settingsIcon || !soundIcon) return;

    const timers = new WeakMap();

    function clearTimers(icon) {
      const active = timers.get(icon) || [];
      active.forEach(id => window.clearTimeout(id));
      timers.set(icon, []);
    }

    function later(icon, fn, ms) {
      const active = timers.get(icon) || [];
      const id = window.setTimeout(fn, ms);
      active.push(id);
      timers.set(icon, active);
    }

    function setMotion(icon, transform, duration, easing) {
      icon.style.setProperty('animation', 'none', 'important');
      icon.style.setProperty('-webkit-animation', 'none', 'important');
      icon.style.setProperty('transition', `transform ${duration}ms ${easing}`, 'important');
      icon.style.setProperty('-webkit-transition', `-webkit-transform ${duration}ms ${easing}`, 'important');
      icon.style.setProperty('transform', transform, 'important');
      icon.style.setProperty('-webkit-transform', transform, 'important');
    }

    function animateSettings() {
      clearTimers(settingsIcon);
      settingsIcon.style.setProperty('transform-origin', '50% 50%', 'important');

      setMotion(settingsIcon, 'rotate(0deg) scale(1)', 0, 'linear');
      requestAnimationFrame(() => {
        requestAnimationFrame(() => {
          setMotion(settingsIcon, 'rotate(28deg) scale(1.02)', 180, 'ease-out');
          later(settingsIcon, () => {
            setMotion(settingsIcon, 'rotate(0deg) scale(1)', 180, 'ease-in');
          }, 190);
        });
      });
    }

    function animateBell() {
      clearTimers(soundIcon);
      soundIcon.style.setProperty('transform-origin', '50% 12%', 'important');

      setMotion(soundIcon, 'rotate(0deg) scale(1)', 0, 'linear');
      requestAnimationFrame(() => {
        requestAnimationFrame(() => {
          setMotion(soundIcon, 'rotate(28deg) scale(1.02)', 145, 'ease-out');

          later(soundIcon, () => {
            setMotion(soundIcon, 'rotate(-28deg) scale(1.02)', 190, 'ease-in-out');
          }, 150);

          later(soundIcon, () => {
            setMotion(soundIcon, 'rotate(0deg) scale(1)', 170, 'ease-out');
          }, 345);
        });
      });
    }

    /* Hover desktop */
    settingsButton.addEventListener('mouseenter', animateSettings);
    soundButton.addEventListener('mouseenter', animateBell);

    /* Clic mouse/touch */
    settingsButton.addEventListener('click', animateSettings);
    soundButton.addEventListener('click', animateBell);

    /* Stato iniziale frontale */
    settingsIcon.style.setProperty('transform', 'rotate(0deg)', 'important');
    soundIcon.style.setProperty('transform', 'rotate(0deg)', 'important');
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', installToolbarMotion, { once: true });
  } else {
    installToolbarMotion();
  }
})();


