(() => {
  'use strict';
  const REFRESH_MS = 30000;
  const CACHE_KEY = 'dashboard_btc_rainbow_live_v1';
  const GENESIS_MS = Date.UTC(2009, 0, 3);
  const SOURCES = [
    { name:'Binance', url:'https://api.binance.com/api/v3/ticker/price?symbol=BTCUSDT', read:p => ({ value:Number(p?.price), timestamp:Date.now() }) },
    { name:'CoinGecko', url:'https://api.coingecko.com/api/v3/simple/price?ids=bitcoin&vs_currencies=usd&include_last_updated_at=true', read:p => ({ value:Number(p?.bitcoin?.usd), timestamp:Number(p?.bitcoin?.last_updated_at) || Date.now() }) },
    { name:'CoinPaprika', url:'https://api.coinpaprika.com/v1/tickers/btc-bitcoin', read:p => ({ value:Number(p?.quotes?.USD?.price), timestamp:p?.last_updated ?? Date.now() }) }
  ];
  const ZONES = [
    { key:'z0', max:0.35, label:'Molto basso' },
    { key:'z1', max:0.60, label:'Basso' },
    { key:'z2', max:0.85, label:'Accumulo' },
    { key:'z3', max:1.20, label:'Equilibrio' },
    { key:'z4', max:1.70, label:'Caldo' },
    { key:'z5', max:2.40, label:'Molto caldo' },
    { key:'z6', max:Infinity, label:'Euforia' }
  ];
  let timer = null, inFlight = false, lastValid = NaN;
  function toMillis(v){ if(v==null||v==='') return NaN; if(typeof v==='number' || /^\d+(?:\.\d+)?$/.test(String(v))){ let n=Number(v); if(!Number.isFinite(n)) return NaN; return n<1e12 ? n*1000 : n; } const p=Date.parse(String(v)); return Number.isFinite(p)?p:NaN; }
  async function fetchJson(url, timeoutMs=9000){ const c=typeof AbortController!=='undefined'?new AbortController():null; const t=setTimeout(()=>c?.abort(),timeoutMs); try{ const r=await fetch(url+(url.includes('?')?'&':'?')+'_='+Date.now(), { cache:'no-store', mode:'cors', credentials:'omit', headers:{ Accept:'application/json' }, signal:c?.signal }); if(!r.ok) throw new Error('HTTP '+r.status); return await r.json(); } finally { clearTimeout(t); } }
  function formatUsdCompact(v){
    if(!Number.isFinite(v)) return '—';
    try { return new Intl.NumberFormat(undefined,{ style:'currency', currency:'USD', notation:'compact', maximumFractionDigits:v>=100000 ? 1 : 2 }).format(v); }
    catch(_){
      if(v>=1e9) return '$'+(v/1e9).toFixed(2)+'B';
      if(v>=1e6) return '$'+(v/1e6).toFixed(2)+'M';
      if(v>=1e3) return '$'+(v/1e3).toFixed(1)+'K';
      return '$'+v.toFixed(0);
    }
  }
  function fairPrice(nowMs){
    const days = Math.max(1, (nowMs - GENESIS_MS) / 86400000);
    const logd = Math.log10(days);
    return Math.pow(10, 5.845 * logd - 17.01);
  }
  function zoneForRatio(ratio){
    for(const z of ZONES){ if(ratio <= z.max) return z; }
    return ZONES[ZONES.length - 1];
  }
  function positionPercent(price, fair){
    const lower = Math.max(1, fair * 0.25);
    const upper = Math.max(lower * 1.01, fair * 3.20);
    const pos = ((Math.log(price) - Math.log(lower)) / (Math.log(upper) - Math.log(lower))) * 100;
    return Math.max(0, Math.min(100, pos));
  }
  function paint(price, timestamp, source, cached=false){
    const pill = document.getElementById('btcRainbowPill');
    const valueEl = document.getElementById('btcRainbowValue');
    if(!pill || !valueEl || !Number.isFinite(price) || price <= 0) return false;
    const stamp = Number.isFinite(toMillis(timestamp)) ? toMillis(timestamp) : Date.now();
    const fair = fairPrice(Date.now());
    const ratio = price / fair;
    const zone = zoneForRatio(ratio);
    const pos = positionPercent(price, fair);
    pill.dataset.state = 'live';
    pill.dataset.zone = zone.key;
    pill.style.setProperty('--btc-rainbow-position', pos + '%');
    pill.setAttribute('aria-valuenow', String(Number(pos.toFixed(1))));
    valueEl.textContent = formatUsdCompact(price);
    pill.title = 'BTC ARCOBALENO: ' + formatUsdCompact(price) + ' · ' + zone.label;
    lastValid = price;
    window.__rainbowQuotesV136 ||= {};
    window.__rainbowQuotesV136['btc']={value:price,timestamp:stamp,source,cached};
    pill.dataset.numericValue=String(price);
    pill.dataset.updatedAt=String(stamp);
    pill.dataset.freshness=cached?'stale':'fresh';
    window.dispatchEvent(new CustomEvent('rainbow-quote-v136',{detail:{asset:'btc',value:price}}));
    if(!cached){
      try{ localStorage.setItem(CACHE_KEY, JSON.stringify({ value:price, timestamp:stamp, source })); }catch(_){ }
    }
    return true;
  }
  function restoreCache(){
    try {
      const x = JSON.parse(localStorage.getItem(CACHE_KEY) || 'null');
      return x && Number.isFinite(Number(x.value)) ? paint(Number(x.value), x.timestamp, x.source || 'CACHE', true) : false;
    } catch(_){ return false; }
  }
  function setError(){
    const pill = document.getElementById('btcRainbowPill');
    const valueEl = document.getElementById('btcRainbowValue');
    if(!pill || !valueEl) return;
    if(Number.isFinite(lastValid)) return;
    pill.dataset.state = 'error';
    pill.dataset.zone = 'z3';
    pill.style.setProperty('--btc-rainbow-position', '50%');
    valueEl.textContent = '—';
  }
  async function refresh(){
    if(inFlight) return;
    inFlight = true;
    let ok = false;
    try {
      for(const source of SOURCES){
        try {
          const p = await fetchJson(source.url);
          const x = source.read(p || {});
          if(!Number.isFinite(x.value) || x.value <= 0) throw new Error('Valore non valido');
          paint(x.value, x.timestamp, source.name, false);
          ok = true;
          break;
        } catch(e){ console.warn('BTC ARCOBALENO ' + source.name, e); }
      }
      if(!ok) setError();
    } finally {
      inFlight = false;
    }
  }
  function readDashboardLivePrice(){
    const el = document.getElementById('btc-price');
    if(!el) return NaN;
    let s = String(el.textContent || '').trim().replace(/\s+/g,'').replace(/[^0-9,.-]/g,'');
    if(!s) return NaN;
    const lc=s.lastIndexOf(','), ld=s.lastIndexOf('.');
    if(lc>ld) s=s.replace(/\./g,'').replace(',', '.'); else s=s.replace(/,/g,'');
    return Number(s);
  }
  function syncDashboardLive(){
    const p = readDashboardLivePrice();
    if(Number.isFinite(p) && p>0 && p!==lastValid) paint(p, Date.now(), 'Dashboard', false);
  }
  function startLiveBridge(){
    syncDashboardLive();
    const el=document.getElementById('btc-price');
    if(el && typeof MutationObserver!=='undefined'){
      const mo=new MutationObserver(syncDashboardLive);
      mo.observe(el,{childList:true,characterData:true,subtree:true});
    }
    setInterval(syncDashboardLive, 1000);
  }
  window.refreshRainbowBTCV136=refresh;
  function start(){ restoreCache(); refresh(); startLiveBridge(); if(!timer) timer = setInterval(refresh, REFRESH_MS); }
  if(document.readyState === 'loading') document.addEventListener('DOMContentLoaded', start, { once:true });
  else start();
  window.addEventListener('online', refresh, { passive:true });
  document.addEventListener('visibilitychange', () => { if(!document.hidden) refresh(); });
})();


