    if (!data.length) {
      ctx.fillStyle=text;ctx.textAlign='center';ctx.textBaseline='middle';ctx.font='12px -apple-system,BlinkMacSystemFont,Segoe UI,sans-serif';
      ctx.fillText('Caricamento grafico arcobaleno ETH…',w/2,h/2);currentEl.textContent='—';return;
    }
