    boundaryRows.forEach(b=>{min=Math.min(min,...b);max=Math.max(max,...b);});
    min=Math.max(.000001,min*.82);max=Math.max(min*1.01,max*1.18);
    const logMin=Math.log(min),logMax=Math.log(max),logSpan=Math.max(.000001,logMax-logMin);
    const xAt=i=>pad.l+(data.length<=1?pw/2:i*pw/(data.length-1));
    const yAt=v=>pad.t+(logMax-Math.log(Math.max(min,v)))/logSpan*ph;
    ctx.strokeStyle=grid;ctx.lineWidth=1;ctx.globalAlpha=.55;
    for(let gx=1;gx<5;gx++){const x=pad.l+pw*gx/5;ctx.beginPath();ctx.moveTo(x,pad.t);ctx.lineTo(x,pad.t+ph);ctx.stroke();}
    ctx.globalAlpha=1;

    // V6 — mantiene il rainbow diagonale ma elimina gli artefatti all'estrema destra.
    const EXTRA_X = 14;
