    ctx.font='10px -apple-system,BlinkMacSystemFont,Segoe UI,sans-serif';ctx.textAlign='right';ctx.textBaseline='middle';
    for(let i=0;i<5;i++){const ratio=i/4,value=Math.exp(logMax-logSpan*ratio),y=yAt(value);ctx.strokeStyle=grid;ctx.globalAlpha=.65;ctx.beginPath();ctx.moveTo(pad.l,y+.5);ctx.lineTo(pad.l+pw,y+.5);ctx.stroke();ctx.globalAlpha=1;ctx.fillStyle=text;ctx.fillText(formatUsdCompact(value),pad.l-8,y);}
    const marks=data.length<5?data.map((_,i)=>i):[0,Math.floor((data.length-1)/4),Math.floor((data.length-1)/2),Math.floor((data.length-1)*3/4),data.length-1];
    ctx.fillStyle=text;ctx.textAlign='center';ctx.textBaseline='top';
    for(const idx of marks)ctx.fillText(formatDate(data[idx].t,currentRange==='max'),xAt(idx),pad.t+ph+11);
    // V7 — linea tratteggiata perfettamente allineata e parallela alle linee Rainbow.
