    ctx.beginPath();data.forEach((p,i)=>{const x=xAt(i),y=yAt(p.v);i===0?ctx.moveTo(x,y):ctx.lineTo(x,y);});ctx.strokeStyle=mainText;ctx.lineWidth=2.1;ctx.lineJoin='miter';ctx.lineCap='butt';ctx.stroke();
