      ctx.beginPath(); ctx.arc(hx,hy,5,0,Math.PI*2); ctx.fillStyle=hoverZone.color; ctx.fill();
      ctx.beginPath(); ctx.arc(hx,hy,8,0,Math.PI*2); ctx.strokeStyle=hoverZone.color; ctx.globalAlpha=.18; ctx.lineWidth=2; ctx.stroke(); ctx.globalAlpha=1;
      const priceLabel = formatUsd(hp.v);
      const dateLabel = new Intl.DateTimeFormat(undefined,{day:'2-digit',month:'short',year:'numeric'}).format(new Date(hp.t));
      ctx.font='700 12px -apple-system,BlinkMacSystemFont,Segoe UI,sans-serif';
