  canvas.addEventListener('mouseleave',()=>{if(hoverIndex!==-1){hoverIndex=-1;draw();}},{passive:true});
  canvas.addEventListener('touchstart',e=>{const t=e.touches?.[0];if(t)updateHoverFromClientX(t.clientX);},{passive:true});
