      const hp = data[hoverIndex];
      const hx = xAt(hoverIndex), hy = yAt(hp.v);
      ctx.save();
      ctx.setLineDash([4,4]);
      ctx.lineWidth = 1;
      ctx.strokeStyle = 'rgba(255,255,255,.48)';
      ctx.beginPath(); ctx.moveTo(hx,pad.t); ctx.lineTo(hx,pad.t+ph); ctx.stroke();
