  function openChart(){hoverIndex=-1;lastFocused=document.activeElement;overlay.hidden=false;document.documentElement.style.overflow='hidden';currentRange='max';requestAnimationFrame(()=>{closeBtn.focus({preventScroll:true});load('max');});if(!liveTimer)liveTimer=setInterval(refreshLiveOnly,1000);}
