/* ===== JS originale 40/107: fear-greed-click-chart-live-v1 ===== */

(() => {
  'use strict';
  const pill = document.getElementById('fearGreedPill');
  const overlay = document.getElementById('fearGreedChartOverlay');
  const closeBtn = document.getElementById('fearGreedChartClose');
  const canvas = document.getElementById('fearGreedHistoryCanvas');
  const frame = document.getElementById('fearGreedChartFrame');
  const loading = document.getElementById('fearGreedChartLoading');
  const currentEl = document.getElementById('fearGreedChartCurrent');
  const rangeBtns = Array.from(document.querySelectorAll('[data-fng-range]'));
  if (!pill || !overlay || !closeBtn || !canvas || !frame || !currentEl) return;

  const ctx = canvas.getContext('2d');
  const HISTORY_URL = 'https://api.alternative.me/fng/?limit=0&format=json';
  const CACHE_KEY = 'dashboard_fear_greed_history_real_v1';
  const ZONES = [
    { min:0, max:24, color:'#ff3b5f', label:'Paura estrema' },
    { min:25, max:44, color:'#f59e0b', label:'Paura' },
    { min:45, max:55, color:'#facc15', label:'Neutrale' },
    { min:56, max:74, color:'#66d68f', label:'Avidità' },
    { min:75, max:100, color:'#159c62', label:'Avidità estrema' }
  ];

  let fullData = [];
  let data = [];
  let currentRange = 'max';
  let hoverIndex = -1;
  let resizeRaf = 0;
  let lastFocused = null;
  let refreshTimer = null;

  pill.tabIndex = 0;
  pill.setAttribute('aria-haspopup','dialog');
  pill.setAttribute('aria-controls','fearGreedChartOverlay');
  pill.setAttribute('aria-label','Apri grafico Paura e Avidità');

  function css(name,fallback){
    const palette={'--panel':'#ffffff','--panel-2':'#f6f7f9','--text':'#15191d','--muted':'#6b7480','--grid':'#e4e7eb','--border':'#dfe2e6'};
    return palette[name]||fallback;
  }

  function zoneFor(v) {
    const n = Math.max(0, Math.min(100, Number(v)));
    return ZONES.find(z => n >= z.min && n <= z.max) || ZONES[2];
  }
  function parseRows(payload) {
    const rows = Array.isArray(payload?.data) ? payload.data : [];
    const seen = new Map();
    for (const r of rows) {
      const tRaw = Number(r?.timestamp);
      const t = Number.isFinite(tRaw) ? (tRaw < 1e12 ? tRaw * 1000 : tRaw) : Date.parse(String(r?.timestamp || ''));
      const v = Number(r?.value);
      if (!Number.isFinite(t) || !Number.isFinite(v)) continue;
      const d = new Date(t); d.setUTCHours(0,0,0,0);
      seen.set(d.getTime(), { t:d.getTime(), v:Math.max(0,Math.min(100,v)), c:String(r?.value_classification || '') });
    }
    return Array.from(seen.values()).sort((a,b)=>a.t-b.t);
  }
  function cached() { return window.__dashboardChartHistorySaved('fng').rows.slice(); }
  function readLiveFromPill() {
    const raw = String(document.getElementById('fearGreedValue')?.textContent || '').replace('/100','').replace(',','.').trim();
    const v = Number(raw);
    if (!Number.isFinite(v)) return null;
    const stamp=Number(document.getElementById('fearGreedPill')?.dataset.updatedAt);
    if(!stamp)return null;
    const d = new Date(stamp); d.setUTCHours(0,0,0,0);
    return { t:d.getTime(), v:Math.max(0,Math.min(100,v)), c:zoneFor(v).label };
  }
  function appendLive(rows) {
    const out = Array.isArray(rows) ? rows.slice() : [];
    const live = readLiveFromPill();
    if (!live) return out;
    if (!out.length || out[out.length-1].t < live.t) out.push(live);
    else if (out[out.length-1].t === live.t) out[out.length-1] = live;
    return out;
  }
  function filterRange(rows, range) {
    if (!rows.length || range === 'max') return rows.slice();
    const days = range === '7d' ? 7 : range === '30d' ? 30 : range === '90d' ? 90 : 365;
    const end = rows[rows.length-1].t;
    const cutoff = end - (days-1)*86400000;
    const visible = rows.filter(r => r.t >= cutoff && r.t <= end);
    return visible.length ? visible : rows.slice(-Math.min(days, rows.length));
  }
  async function fetchHistory() {
    const payload = await window.__dashboardChartHistoryFetch('fng', 'max');
    const rows = appendLive((payload.rows || []).map(x => ({t:Number(x?.t),v:Number(x?.v),c:''})));
    if (!rows.length) throw new Error('Storico vuoto');
    try { localStorage.setItem(CACHE_KEY, JSON.stringify({savedAt:Date.now(),source:payload.source||'LIVE',rows})); } catch (_) {}
    return rows;
  }
  function resizeCanvas() {
    const rect = frame.getBoundingClientRect();
    const dpr = Math.min(2, window.devicePixelRatio || 1);
    const w = Math.max(320, Math.round(rect.width));
    const h = Math.max(280, Math.round(rect.height));
    if (canvas.width !== Math.round(w*dpr) || canvas.height !== Math.round(h*dpr)) {
      canvas.width = Math.round(w*dpr); canvas.height = Math.round(h*dpr);
      canvas.style.width = w+'px'; canvas.style.height = h+'px';
    }
    ctx.setTransform(dpr,0,0,dpr,0,0);
    return {w,h};
  }
  function formatDate(ms, short=false) {
    return new Intl.DateTimeFormat(undefined, short ? {day:'2-digit',month:'2-digit'} : {day:'2-digit',month:'short',year:'numeric'}).format(new Date(ms));
  }
  function draw() {
    if (overlay.hidden) return;
    const {w,h} = resizeCanvas();
    ctx.clearRect(0,0,w,h);
    const bg = css('--panel-2','#151921');
    const grid = css('--grid','#252a33');
    const text = css('--muted','#8f99a8');
    const mainText = css('--text','#f5f7fa');
    ctx.fillStyle = bg; ctx.fillRect(0,0,w,h);
    const pad = {l:48,r:18,t:18,b:38};
    const pw = Math.max(1,w-pad.l-pad.r), ph = Math.max(1,h-pad.t-pad.b);
    const xAt = i => pad.l + (data.length <= 1 ? pw/2 : i*pw/(data.length-1));
    const yAt = v => pad.t + (100-Math.max(0,Math.min(100,v)))/100*ph;

    // Fasce colorate orizzontali.
    for (const z of ZONES) {
      const top = yAt(z.max + (z.max < 100 ? 1 : 0));
      const bottom = yAt(z.min);
      ctx.fillStyle = z.color + '24';
      ctx.fillRect(pad.l, top, pw, Math.max(1,bottom-top));
    }

    ctx.font='10px -apple-system,BlinkMacSystemFont,Segoe UI,sans-serif';
    ctx.textAlign='right'; ctx.textBaseline='middle';
    for (const tick of [0,10,20,25,30,40,50,60,70,75,80,90,100]) {
      const y = yAt(tick);
      ctx.strokeStyle = tick===25 ? 'rgba(245,158,11,.55)' : tick===75 ? 'rgba(21,156,98,.60)' : grid;
      ctx.globalAlpha = (tick%10===0 || tick===25 || tick===75) ? .72 : .35;
      ctx.beginPath(); ctx.moveTo(pad.l,y+.5); ctx.lineTo(pad.l+pw,y+.5); ctx.stroke();
      ctx.globalAlpha=1;
      if (tick%10===0 || tick===25 || tick===75) {
        const z = zoneFor(tick);
        ctx.fillStyle = (tick===25 || tick===75) ? z.color : text;
        ctx.fillText(tick+'%', pad.l-7, y);
      }
    }

    if (!data.length) {
      ctx.fillStyle=text; ctx.textAlign='center'; ctx.textBaseline='middle';
      ctx.fillText('Storico reale non disponibile',w/2,h/2);
      return;
    }

    const marks = data.length < 5 ? data.map((_,i)=>i) : [0,Math.floor((data.length-1)/4),Math.floor((data.length-1)/2),Math.floor((data.length-1)*3/4),data.length-1];
    ctx.fillStyle=text; ctx.textAlign='center'; ctx.textBaseline='top';
    for (const idx of marks) ctx.fillText(formatDate(data[idx].t,true),xAt(idx),pad.t+ph+10);

    // Area + linea con gradiente verticale. Curva morbida Catmull-Rom -> Bezier
    // per ottenere un andamento realmente ondulato anche su PC/Android.
    const area = ctx.createLinearGradient(0,pad.t,0,pad.t+ph);
    area.addColorStop(0,'rgba(21,156,98,.22)');
    area.addColorStop(.25,'rgba(102,214,143,.16)');
    area.addColorStop(.5,'rgba(250,204,21,.12)');
    area.addColorStop(.75,'rgba(245,158,11,.15)');
    area.addColorStop(1,'rgba(255,59,95,.20)');

    const smoothPoints = data.map((p,i)=>({x:xAt(i), y:yAt(p.v)}));
    function traceFearGreedSmooth(points, tension=0.18){
      if(!points.length) return;
      ctx.moveTo(points[0].x, points[0].y);
      if(points.length===1) return;
      if(points.length===2){ ctx.lineTo(points[1].x, points[1].y); return; }
      for(let i=0;i<points.length-1;i++){
        const p0=points[Math.max(0,i-1)], p1=points[i], p2=points[i+1], p3=points[Math.min(points.length-1,i+2)];
        const cp1x=p1.x+(p2.x-p0.x)*tension;
        const cp1y=p1.y+(p2.y-p0.y)*tension;
        const cp2x=p2.x-(p3.x-p1.x)*tension;
        const cp2y=p2.y-(p3.y-p1.y)*tension;
        ctx.bezierCurveTo(cp1x,cp1y,cp2x,cp2y,p2.x,p2.y);
      }
    }

    ctx.beginPath();
    traceFearGreedSmooth(smoothPoints);
    ctx.lineTo(xAt(data.length-1),pad.t+ph);
    ctx.lineTo(xAt(0),pad.t+ph);
    ctx.closePath();
    ctx.fillStyle=area;
    ctx.fill();

    ctx.beginPath();
    traceFearGreedSmooth(smoothPoints);
    ctx.strokeStyle=mainText;
    ctx.lineWidth=2.25;
    ctx.lineJoin='round';
    ctx.lineCap='round';
    ctx.stroke();

    const last=data[data.length-1], lastZone=zoneFor(last.v), lx=xAt(data.length-1), ly=yAt(last.v);
    ctx.beginPath();ctx.arc(lx,ly,4.5,0,Math.PI*2);ctx.fillStyle=lastZone.color;ctx.fill();
    ctx.beginPath();ctx.arc(lx,ly,8.5,0,Math.PI*2);ctx.strokeStyle=lastZone.color;ctx.globalAlpha=.28;ctx.lineWidth=3;ctx.stroke();ctx.globalAlpha=1;

    if (hoverIndex >= 0 && hoverIndex < data.length) {
      const hp = data[hoverIndex], hz=zoneFor(hp.v), hx=xAt(hoverIndex), hy=yAt(hp.v);
      ctx.save();
      ctx.setLineDash([4,4]);ctx.lineWidth=1;ctx.strokeStyle='rgba(255,255,255,.48)';
      ctx.beginPath();ctx.moveTo(hx,pad.t);ctx.lineTo(hx,pad.t+ph);ctx.stroke();
      ctx.beginPath();ctx.moveTo(pad.l,hy);ctx.lineTo(pad.l+pw,hy);ctx.stroke();ctx.setLineDash([]);
      ctx.beginPath();ctx.arc(hx,hy,5,0,Math.PI*2);ctx.fillStyle=hz.color;ctx.fill();
      ctx.beginPath();ctx.arc(hx,hy,9,0,Math.PI*2);ctx.strokeStyle=hz.color;ctx.globalAlpha=.30;ctx.lineWidth=3;ctx.stroke();ctx.globalAlpha=1;

      const valueLabel=(Math.round(hp.v*10)/10).toLocaleString(undefined,{maximumFractionDigits:1})+'%';
      const dateLabel=formatDate(hp.t,false);
      const statusLabel=hz.label;
      ctx.font='700 13px -apple-system,BlinkMacSystemFont,Segoe UI,sans-serif';
      const w1=ctx.measureText(valueLabel).width;
      ctx.font='10px -apple-system,BlinkMacSystemFont,Segoe UI,sans-serif';
      const w2=Math.max(ctx.measureText(dateLabel).width,ctx.measureText(statusLabel).width);
      const boxW=Math.max(132,Math.ceil(Math.max(w1,w2)+24)), boxH=63;
      let boxX=hx+14, boxY=hy-boxH-14;
      if(boxX+boxW>w-8)boxX=hx-boxW-14;if(boxX<8)boxX=8;
      if(boxY<8)boxY=hy+14;if(boxY+boxH>h-8)boxY=h-boxH-8;
      ctx.fillStyle='rgba(10,13,18,.95)';ctx.strokeStyle=hz.color;ctx.globalAlpha=1;ctx.lineWidth=1;
      ctx.beginPath();if(ctx.roundRect)ctx.roundRect(boxX,boxY,boxW,boxH,9);else ctx.rect(boxX,boxY,boxW,boxH);ctx.fill();ctx.stroke();
      ctx.textAlign='left';ctx.textBaseline='top';
      ctx.font='700 13px -apple-system,BlinkMacSystemFont,Segoe UI,sans-serif';ctx.fillStyle=hz.color;ctx.fillText(valueLabel,boxX+11,boxY+8);
      ctx.font='10px -apple-system,BlinkMacSystemFont,Segoe UI,sans-serif';ctx.fillStyle='rgba(235,239,245,.78)';ctx.fillText(statusLabel,boxX+11,boxY+29);ctx.fillText(dateLabel,boxX+11,boxY+44);
      ctx.restore();
    }

    currentEl.textContent=(Math.round(last.v*10)/10).toLocaleString(undefined,{maximumFractionDigits:1});
    currentEl.style.color=lastZone.color;
    frame.title='Paura & Avidità · '+last.v+'/100 · '+lastZone.label+' · '+formatDate(last.t,false);
  }
  async function load(range) {
    hoverIndex=-1;
    currentRange=range||'90d';
    rangeBtns.forEach(btn=>btn.classList.toggle('active',btn.dataset.fngRange===currentRange));
    const cacheRows=appendLive(fullData.length?fullData:cached());
    if(cacheRows.length){fullData=cacheRows;data=filterRange(fullData,currentRange);loading.hidden=true;draw();}else{data=[];loading.hidden=false;draw();}
    try {
      const rows=await fetchHistory();fullData=rows;data=filterRange(fullData,currentRange);loading.hidden=true;draw();
    } catch(err) {
      console.warn('PAURA & AVIDITÀ storico',err);
      if(!data.length){loading.hidden=false;loading.textContent='Connessione storico reale…';}
    }
  }
  function hoverFromEvent(e) {
    if (!data.length || overlay.hidden) return;
    const rect=canvas.getBoundingClientRect();
    const clientX=e?.touches?.[0]?.clientX ?? e?.changedTouches?.[0]?.clientX ?? e?.clientX;
    if(!Number.isFinite(clientX))return;
    const padL=48,padR=18,pw=Math.max(1,rect.width-padL-padR);
    const x=Math.max(padL,Math.min(rect.width-padR,clientX-rect.left));
    hoverIndex=data.length<=1?0:Math.max(0,Math.min(data.length-1,Math.round(((x-padL)/pw)*(data.length-1))));
    draw();
  }
  function clearHover(){if(hoverIndex!==-1){hoverIndex=-1;draw();}}
  function openChart(){lastFocused=document.activeElement;overlay.hidden=false;document.documentElement.style.overflow='hidden';requestAnimationFrame(()=>{closeBtn.focus({preventScroll:true});load(currentRange);});if(!refreshTimer)refreshTimer=setInterval(()=>{if(!overlay.hidden)load(currentRange);},30000);}
  function closeChart(){overlay.hidden=true;document.documentElement.style.overflow='';hoverIndex=-1;try{lastFocused?.focus?.({preventScroll:true});}catch(_){} }

  pill.addEventListener('click', openChart);
  pill.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();openChart();}});
  closeBtn.addEventListener('click',closeChart);
  overlay.addEventListener('click',e=>{if(e.target===overlay)closeChart();});
  document.addEventListener('keydown',e=>{if(!overlay.hidden&&e.key==='Escape')closeChart();});
  rangeBtns.forEach(btn=>btn.addEventListener('click',()=>load(btn.dataset.fngRange||'90d')));
  canvas.addEventListener('pointermove',hoverFromEvent,{passive:true});
  canvas.addEventListener('mousemove',hoverFromEvent,{passive:true});
  canvas.addEventListener('pointerleave',clearHover,{passive:true});
  canvas.addEventListener('mouseleave',clearHover,{passive:true});
  canvas.addEventListener('touchmove',hoverFromEvent,{passive:true});
  canvas.addEventListener('touchstart',hoverFromEvent,{passive:true});
  window.addEventListener('resize',()=>{if(overlay.hidden)return;cancelAnimationFrame(resizeRaf);resizeRaf=requestAnimationFrame(draw);},{passive:true});
  window.addEventListener('online',()=>{if(!overlay.hidden)load(currentRange);},{passive:true});
  document.addEventListener('visibilitychange',()=>{if(!document.hidden&&!overlay.hidden)load(currentRange);});
  // Shared layout updates for desktop, tablet rotation and browser toolbar changes.
  let layoutFrame=0;
  function refreshLayout(){
    if(overlay.hidden)return;
    cancelAnimationFrame(layoutFrame);
    layoutFrame=requestAnimationFrame(draw);
  }
  if(typeof ResizeObserver!=='undefined')new ResizeObserver(refreshLayout).observe(frame);
  window.visualViewport?.addEventListener('resize',refreshLayout,{passive:true});
  window.addEventListener('orientationchange',refreshLayout,{passive:true});
  if(typeof MutationObserver!=='undefined'){
    const themeObserver=new MutationObserver(refreshLayout);
    themeObserver.observe(document.documentElement,{attributes:true,attributeFilter:['data-theme','class']});
    themeObserver.observe(document.body,{attributes:true,attributeFilter:['data-theme','class']});
  }

  function resumeLivePanelV135(){if(!document.hidden&&!overlay.hidden)load(currentRange);}
  window.addEventListener('dashboard-pill-update',resumeLivePanelV135);
  window.addEventListener('online',resumeLivePanelV135);
  window.addEventListener('pageshow',resumeLivePanelV135);
  document.addEventListener('visibilitychange',resumeLivePanelV135);

  // V143: modalità riferimento rimossa; pannello sempre LIVE.

})();


