/* ===== JS originale 41/107: altcoin-index-click-chart-live-v1 ===== */

(() => {
  'use strict';
  const pill = document.getElementById('altcoinIndexPill');
  const overlay = document.getElementById('altcoinIndexChartOverlay');
  const closeBtn = document.getElementById('altcoinIndexChartClose');
  const canvas = document.getElementById('altcoinIndexHistoryCanvas');
  const frame = document.getElementById('altcoinIndexChartFrame');
  const loading = document.getElementById('altcoinIndexChartLoading');
  const currentEl = document.getElementById('altcoinIndexChartCurrent');
  const rangeBtns = Array.from(document.querySelectorAll('[data-altcoin-range]'));
  if (!pill || !overlay || !closeBtn || !canvas || !frame) return;

  const ctx = canvas.getContext('2d');
  const CACHE_PREFIX = 'dashboard_altcoin_history_cmc_real_v5_';
  const CACHE_ALL_KEY = 'dashboard_altcoin_history_cmc_real_v5_all';
  const HISTORY_CSV_URL = 'https://raw.githubusercontent.com/bykarantelicom/crypto-datasets/refs/heads/main/data/metric-daily.csv';
  const ALTSEASON_API_URL = 'https://bykaranteli.com/api/public/altseason';
  const CMC_HISTORY_URL = 'https://pro-api.coinmarketcap.com/public-api/v1/altcoin-season-index/historical';
  const CMC_LATEST_URL = 'https://pro-api.coinmarketcap.com/public-api/v1/altcoin-season-index/latest';
  let currentRange = '90d';
  let data = [];
  let resizeRaf = 0;
  let lastFocused = null;
  let hoverIndex = -1;
  let refreshTimer = null;

  pill.tabIndex = 0;
  pill.setAttribute('aria-haspopup', 'dialog');
  pill.setAttribute('aria-controls', 'altcoinIndexChartOverlay');
  pill.setAttribute('aria-label', 'Apri grafico Altcoin Season Index');
  canvas.style.cursor = 'crosshair';

  function css(name, fallback) {
    const value = getComputedStyle(document.body).getPropertyValue(name).trim();
    return value || fallback;
  }

  function parseTime(value) {
    const ms = Date.parse(String(value || ''));
    if (Number.isFinite(ms)) return ms;
    const n = Number(value);
    if (!Number.isFinite(n)) return NaN;
    return n < 1e12 ? n * 1000 : n;
  }

  function normalize(payload) {
    const raw = payload?.data?.points ?? payload?.data ?? payload?.points ?? [];
    const rows = Array.isArray(raw) ? raw : [];
    const seen = new Map();
    for (const row of rows) {
      const t = parseTime(row?.timestamp ?? row?.snapshot_time ?? row?.time ?? row?.date);
      const v = Number(row?.altcoin_index ?? row?.value ?? row?.index);
      if (!Number.isFinite(t) || !Number.isFinite(v)) continue;
      seen.set(t, { t, v: Math.max(0, Math.min(100, v)) });
    }
    return Array.from(seen.values()).sort((a,b) => a.t - b.t);
  }

  function mergeRows(...groups) {
    const byTime = new Map();
    groups.flat().forEach(row => {
      const t = Number(row?.t), v = Number(row?.v);
      if (Number.isFinite(t) && Number.isFinite(v)) byTime.set(t, {t, v:Math.max(0,Math.min(100,v))});
    });
    return Array.from(byTime.values()).sort((a,b) => a.t-b.t);
  }

  function filterRange(rows, range) {
    if (!Array.isArray(rows) || !rows.length) return [];
    if(range==='max') return rows.slice();
    const days = range === '7d' ? 7 : range === '30d' ? 30 : 90;
    const latest = rows[rows.length-1].t;
    const cutoff = latest - (days - 1) * 86400000;
    return rows.filter(row => row.t >= cutoff);
  }

  function parseMetricCsv(text) {
    const rows = [];
    String(text || '').split(/\r?\n/).forEach(line => {
      if (!line || !line.startsWith('altseason_index,')) return;
      const parts = line.split(',');
      const t = Date.parse(String(parts[1] || '').trim() + 'T00:00:00Z');
      const v = Number(parts[2]);
      if (Number.isFinite(t) && Number.isFinite(v)) rows.push({t, v:Math.max(0,Math.min(100,v))});
    });
    return rows.sort((a,b) => a.t-b.t);
  }

  function normalizeByKaranteli(payload) {
    const candidates = [
      payload?.history, payload?.daily_history, payload?.dailyHistory,
      payload?.points, payload?.series, payload?.data?.history,
      payload?.data?.points, payload?.data?.series
    ];
    const raw = candidates.find(Array.isArray) || [];
    const rows = [];
    for (const row of raw) {
      const t = parseTime(row?.timestamp ?? row?.time ?? row?.date ?? row?.day ?? row?.ts);
      const v = Number(row?.altcoin_index ?? row?.altseason_index ?? row?.index ?? row?.value ?? row?.score);
      if (Number.isFinite(t) && Number.isFinite(v)) rows.push({t, v:Math.max(0,Math.min(100,v))});
    }
    return mergeRows(rows);
  }

  async function fetchJsonCors(url, timeoutMs=12000) {
    const controller = typeof AbortController !== 'undefined' ? new AbortController() : null;
    const timer = setTimeout(() => controller?.abort(), timeoutMs);
    try {
      const response = await fetch(url + (url.includes('?') ? '&' : '?') + '_=' + Date.now(), {
        cache:'no-store', mode:'cors', credentials:'omit', headers:{Accept:'application/json'}, signal:controller?.signal
      });
      if (!response.ok) throw new Error('HTTP ' + response.status);
      return await response.json();
    } finally { clearTimeout(timer); }
  }

  async function fetchHistory(range) {
    const safeRange = range === 'max' || range === '7d' || range === '30d' || range === '90d' ? range : '90d';
    const payload = await window.__dashboardChartHistoryFetch('altcoin', safeRange);
    let rows = mergeRows((payload.rows || []).map(x => ({t:Number(x?.t),v:Number(x?.v)})));
    rows = appendLive(rows);
    rows = filterRange(rows, safeRange);
    if (!rows.length) throw new Error('Nessun dato reale disponibile per ' + safeRange);
    try { localStorage.setItem(CACHE_PREFIX + safeRange, JSON.stringify({savedAt:Date.now(),source:payload.source||'LIVE',rows})); } catch (_) {}
    return rows;
  }

  function cachedAllHistory() {
    try {
      const parsed = JSON.parse(localStorage.getItem(CACHE_ALL_KEY) || 'null');
      if (!parsed || !Array.isArray(parsed.rows)) return [];
      return mergeRows(parsed.rows.map(x => ({t:Number(x?.t), v:Number(x?.v)})));
    } catch (_) { return []; }
  }

  function cachedHistory(range) { return filterRange(window.__dashboardChartHistorySaved('altcoin').rows,range); }

  function appendLive(rows) {
    const liveValue = Number(String(document.getElementById('altcoinIndexValue')?.textContent || '').replace('/100','').replace(',','.'));
    if (!Number.isFinite(liveValue)) return rows;
    const out = rows.slice();
    const now = Number(document.getElementById('altcoinIndexPill')?.dataset.updatedAt);
    if(!now || (out.length && now<out[out.length-1].t))return out;
    if (!out.length || now - out[out.length - 1].t > 5 * 60 * 1000) out.push({ t: now, v: Math.max(0, Math.min(100, liveValue)) });
    else out[out.length - 1] = { t: out[out.length - 1].t, v: Math.max(0, Math.min(100, liveValue)) };
    return out;
  }

  function resizeCanvas() {
    const rect = frame.getBoundingClientRect();
    const dpr = Math.min(2, window.devicePixelRatio || 1);
    const w = Math.max(320, Math.round(rect.width));
    const h = Math.max(260, Math.round(rect.height));
    if (canvas.width !== Math.round(w*dpr) || canvas.height !== Math.round(h*dpr)) {
      canvas.width = Math.round(w*dpr);
      canvas.height = Math.round(h*dpr);
      canvas.style.width = w + 'px';
      canvas.style.height = h + 'px';
    }
    ctx.setTransform(dpr,0,0,dpr,0,0);
    return { w, h };
  }

  function formatDate(ms, compact=false) {
    const opts = currentRange === 'max' ? {month:'short',year:'numeric'} : currentRange === '90d'
      ? {day:'2-digit', month:'short'}
      : compact ? {day:'2-digit',month:'2-digit'} : {day:'2-digit',month:'short'};
    return new Intl.DateTimeFormat(undefined, opts).format(new Date(ms));
  }

  function requestedDays(range) {
    return range === '7d' ? 7 : range === '30d' ? 30 : 90;
  }

  function visibleDomain(rows, range) {
    if (Array.isArray(rows) && rows.length) {
      const start = Number(rows[0]?.t);
      const end = Number(rows[rows.length - 1]?.t);
      if (Number.isFinite(start) && Number.isFinite(end) && end > start) return { start, end };
    }
    const end = Date.now();
    const days = requestedDays(range);
    return { start: end - (days - 1) * 86400000, end };
  }

  function draw() {
    if (overlay.hidden) return;
    const {w,h} = resizeCanvas();
    ctx.clearRect(0,0,w,h);
    const bg = '#f6f7f9';
    const grid = '#e4e7eb';
    const text = '#777f8b';
    const mainText = '#15191d';
    ctx.fillStyle = bg; ctx.fillRect(0,0,w,h);

    const scale=Math.max(1,Math.min(1.5,w/500));
    const pad = {l:42*scale,r:16*scale,t:14*scale,b:34*scale};
    const pw = Math.max(1,w-pad.l-pad.r), ph = Math.max(1,h-pad.t-pad.b);
    const domain = visibleDomain(data, currentRange);
    const span = Math.max(1, domain.end - domain.start);
    const xAtTime = t => pad.l + Math.max(0, Math.min(1, (t - domain.start) / span)) * pw;
    const xAt = i => xAtTime(data[i]?.t ?? domain.start);
    const yAt = v => pad.t + (100-Math.max(0,Math.min(100,v)))/100*ph;

    // Zone leggere: sotto 25 arancio, sopra 75 blu.
    ctx.fillStyle = 'rgba(255,173,36,.055)';
    ctx.fillRect(pad.l, yAt(25), pw, yAt(0)-yAt(25));
    ctx.fillStyle = 'rgba(51,153,255,.055)';
    ctx.fillRect(pad.l, yAt(100), pw, yAt(75)-yAt(100));

    ctx.lineWidth = 1;
    ctx.font = `${11*scale}px -apple-system,BlinkMacSystemFont,Segoe UI,sans-serif`;
    ctx.textAlign = 'right'; ctx.textBaseline = 'middle';
    for (const tick of [0,25,50,75,100]) {
      const y = yAt(tick);
      const hideGuide = tick === 25 || tick === 75;
      if (!hideGuide) {
        ctx.strokeStyle = grid;
        ctx.setLineDash([]);
        ctx.beginPath(); ctx.moveTo(pad.l,y+.5); ctx.lineTo(pad.l+pw,y+.5); ctx.stroke();
      }
      ctx.setLineDash([]);
      ctx.fillStyle = tick===25 ? '#ffad24' : tick===75 ? '#3399ff' : text;
      ctx.fillText(String(tick) + '%', pad.l-7, y);
    }

    if (!data.length) {
      ctx.fillStyle = text;
      ctx.textAlign='center'; ctx.textBaseline='middle';
      ctx.fillText('Storico non disponibile', w/2, h/2);
      return;
    }

    // Etichette tempo: l'intervallo selezionato viene mostrato per intero.
    const tickCount = currentRange === '90d' ? 6 : currentRange === '30d' ? 5 : 4;
    ctx.fillStyle = text; ctx.textBaseline='top'; ctx.textAlign='center';
    for (let i = 0; i < tickCount; i++) {
      const ratio = tickCount === 1 ? 0 : i / (tickCount - 1);
      const t = domain.start + span * ratio;
      const x = pad.l + pw * ratio;
      if (i === 0) ctx.textAlign = 'left';
      else if (i === tickCount - 1) ctx.textAlign = 'right';
      else ctx.textAlign = 'center';
      ctx.fillText(formatDate(t,true), x, pad.t+ph+12);
    }
    ctx.textAlign='center';

    // ALTCOIN INDEX V397 — onda continua e ben visibile su tutta la larghezza del grafico.
    // I valori mostrati al cursore restano quelli reali; la linea usa una lieve modulazione visiva
    // continua sopra il trend reale, così non compaiono più tratti piatti tra i campioni giornalieri.
    const realPoints = data.map((p,i) => ({x:xAt(i), y:yAt(p.v), t:Number(p.t), v:Number(p.v)}));

    function buildContinuousWave(points) {
      if (!points.length) return [];
      if (points.length === 1) return [{x:points[0].x, y:points[0].y}];

      const sampleCount = Math.max(220, Math.min(1400, Math.round(pw * 1.35)));
      const amplitudePx = Math.max(5.5, Math.min(13.0, ph * 0.032));
      const cycles = Math.max(6, Math.min(22, Math.round(pw / 58)));
      const out = [];
      let seg = 0;

      for (let s = 0; s <= sampleCount; s++) {
        const ratio = s / sampleCount;
        const x = pad.l + ratio * pw;

        while (seg < points.length - 2 && x > points[seg + 1].x) seg++;
        const a = points[seg];
        const b = points[Math.min(points.length - 1, seg + 1)];
        const dx = Math.max(0.0001, b.x - a.x);
        const local = Math.max(0, Math.min(1, (x - a.x) / dx));

        // Interpolazione morbida del trend reale, senza gradini.
        const ease = local * local * (3 - 2 * local);
        const baseY = a.y + (b.y - a.y) * ease;

        // Onda continua da sinistra a destra. Parte e termina sul valore reale.
        const edgeEnvelope = Math.sin(Math.PI * ratio);
        const wave = Math.sin(ratio * Math.PI * 2 * cycles) * amplitudePx * (0.72 + 0.28 * edgeEnvelope);
        const y = Math.max(pad.t + 2, Math.min(pad.t + ph - 2, baseY + wave));
        out.push({x, y});
      }

      // Mantiene esattamente gli estremi reali.
      out[0] = {x:points[0].x, y:points[0].y};
      out[out.length - 1] = {x:points[points.length - 1].x, y:points[points.length - 1].y};
      return out;
    }

    const smoothPoints = buildContinuousWave(realPoints);
    const markerInset = Math.max(9 * scale, 9);
    function clampPlotPoint(x, y, inset = 0) {
      return {
        x: Math.max(pad.l + inset, Math.min(pad.l + pw - inset, x)),
        y: Math.max(pad.t + inset, Math.min(pad.t + ph - inset, y))
      };
    }
    function yOnSmoothLineAtX(x, fallbackY) {
      if (!smoothPoints.length) return fallbackY;
      const minX = smoothPoints[0].x;
      const maxX = smoothPoints[smoothPoints.length - 1].x;
      const targetX = Math.max(minX, Math.min(maxX, x));
      let lo = 0, hi = smoothPoints.length - 1;
      while (lo < hi) {
        const mid = Math.floor((lo + hi) / 2);
        if (smoothPoints[mid].x < targetX) lo = mid + 1;
        else hi = mid;
      }
      const b = smoothPoints[Math.min(smoothPoints.length - 1, lo)];
      const a = smoothPoints[Math.max(0, lo - 1)];
      if (!a || !b) return fallbackY;
      const dx = b.x - a.x;
      if (Math.abs(dx) < 0.0001) return b.y;
      const ratio = (targetX - a.x) / dx;
      return a.y + (b.y - a.y) * ratio;
    }
    // V400: NON spostare i due punti terminali verso l'interno.
    // Lo spostamento creava un segmento che tornava indietro su sé stesso,
    // visibile come una piccola linea orizzontale a sinistra e a destra.
    // La forma ondulata e tutti i campioni interni restano identici.
    function traceSmoothSeries(points) {
      if (!points.length) return;
      ctx.moveTo(points[0].x, points[0].y);
      if (points.length === 1) return;
      for (let i = 1; i < points.length; i++) {
        const p = points[i];
        ctx.lineTo(p.x, p.y);
      }
    }

    const grad = ctx.createLinearGradient(0,pad.t,0,pad.t+ph);
    grad.addColorStop(0,'rgba(51,153,255,.18)');
    grad.addColorStop(.5,'rgba(167,139,250,.08)');
    grad.addColorStop(1,'rgba(255,173,36,.10)');
    ctx.beginPath();
    traceSmoothSeries(smoothPoints);
    ctx.lineTo(smoothPoints[smoothPoints.length-1].x, pad.t+ph); ctx.lineTo(smoothPoints[0].x,pad.t+ph); ctx.closePath();
    ctx.fillStyle = grad; ctx.fill();

    // Linea principale ondulata: sopra 50% blu, sotto 50% arancione.
    const threshold = 50;
    const blueLine = '#3399ff';
    const orangeLine = '#ffad24';
    const lineGrad = ctx.createLinearGradient(0,pad.t,0,pad.t+ph);
    lineGrad.addColorStop(0, blueLine);
    lineGrad.addColorStop(.499, blueLine);
    lineGrad.addColorStop(.501, orangeLine);
    lineGrad.addColorStop(1, orangeLine);
    ctx.beginPath();
    traceSmoothSeries(smoothPoints);
    ctx.lineWidth = 2.2*scale; ctx.lineJoin='miter'; ctx.lineCap='butt';
    ctx.strokeStyle = lineGrad;
    ctx.stroke();

    // Ultimo valore reale e pallino finale del grafico.
    const last = data[data.length-1];
    const lastRawX = xAt(data.length - 1);
    const lastRawY = yAt(last.v);
    const lastY = yOnSmoothLineAtX(lastRawX, lastRawY);
    const lastColor = last.v >= threshold ? blueLine : orangeLine;
    ctx.beginPath();
    ctx.arc(lastRawX, lastY, 4.5 * scale, 0, Math.PI * 2);
    ctx.fillStyle = lastColor;
    ctx.fill();
    ctx.beginPath();
    ctx.arc(lastRawX, lastY, 8 * scale, 0, Math.PI * 2);
    ctx.strokeStyle = lastColor;
    ctx.globalAlpha = .25;
    ctx.lineWidth = 3;
    ctx.stroke();
    ctx.globalAlpha = 1;

    // Cursore interattivo: data + percentuale esatta del punto selezionato.
    if (hoverIndex >= 0 && hoverIndex < data.length) {
      const hp = data[hoverIndex];
      const hoverBaseX = xAt(hoverIndex);
      const hoverBaseY = yAt(hp.v);
      const isLastHoverPoint = hoverIndex === data.length - 1;
      const hoverPoint = isLastHoverPoint
        ? { x: lastRawX, y: lastY }
        : clampPlotPoint(hoverBaseX, yOnSmoothLineAtX(hoverBaseX, hoverBaseY), markerInset);
      const hx = hoverPoint.x;
      const hy = hoverPoint.y;
      const hoverColor = hp.v >= threshold ? blueLine : orangeLine;

      ctx.save();
      ctx.setLineDash([4,4]);
      ctx.lineWidth = 1;
      ctx.strokeStyle = 'rgba(255,255,255,.34)';
      ctx.beginPath(); ctx.moveTo(hx, pad.t); ctx.lineTo(hx, pad.t + ph); ctx.stroke();
      ctx.beginPath(); ctx.moveTo(pad.l, hy); ctx.lineTo(pad.l + pw, hy); ctx.stroke();
      ctx.setLineDash([]);

      ctx.beginPath(); ctx.arc(hx, hy, 5, 0, Math.PI*2); ctx.fillStyle = hoverColor; ctx.fill();
      ctx.beginPath(); ctx.arc(hx, hy, 9, 0, Math.PI*2); ctx.strokeStyle = hoverColor; ctx.globalAlpha = .28; ctx.lineWidth = 3; ctx.stroke(); ctx.globalAlpha = 1;

      const pctText = (Math.round(hp.v * 10) / 10).toLocaleString(undefined,{maximumFractionDigits:1}) + '%';
      const dateText = new Intl.DateTimeFormat(undefined,{day:'2-digit',month:'short',year:'numeric'}).format(new Date(hp.t));
      ctx.font = '800 13px -apple-system,BlinkMacSystemFont,Segoe UI,sans-serif';
      const pctW = ctx.measureText(pctText).width;
      ctx.font = '10px -apple-system,BlinkMacSystemFont,Segoe UI,sans-serif';
      const dateW = ctx.measureText(dateText).width;
      const boxW = Math.max(112, Math.ceil(Math.max(pctW, dateW) + 24));
      const boxH = 50;
      let boxX = hx + 12;
      if (boxX + boxW > w - 8) boxX = hx - boxW - 12;
      boxX = Math.max(8, boxX);
      let boxY = hy - boxH - 12;
      if (boxY < 8) boxY = hy + 12;
      if (boxY + boxH > h - 8) boxY = h - boxH - 8;

      const r = 9;
      ctx.beginPath();
      ctx.moveTo(boxX+r, boxY); ctx.lineTo(boxX+boxW-r, boxY);
      ctx.quadraticCurveTo(boxX+boxW, boxY, boxX+boxW, boxY+r);
      ctx.lineTo(boxX+boxW, boxY+boxH-r); ctx.quadraticCurveTo(boxX+boxW, boxY+boxH, boxX+boxW-r, boxY+boxH);
      ctx.lineTo(boxX+r, boxY+boxH); ctx.quadraticCurveTo(boxX, boxY+boxH, boxX, boxY+boxH-r);
      ctx.lineTo(boxX, boxY+r); ctx.quadraticCurveTo(boxX, boxY, boxX+r, boxY); ctx.closePath();
      ctx.fillStyle = 'rgba(10,13,18,.94)'; ctx.fill();
      ctx.strokeStyle = 'rgba(255,255,255,.18)'; ctx.lineWidth = 1; ctx.stroke();

      ctx.textAlign = 'left'; ctx.textBaseline = 'top';
      ctx.font = '800 13px -apple-system,BlinkMacSystemFont,Segoe UI,sans-serif';
      ctx.fillStyle = hoverColor; ctx.fillText(pctText, boxX+12, boxY+8);
      ctx.font = '10px -apple-system,BlinkMacSystemFont,Segoe UI,sans-serif';
      ctx.fillStyle = '#cbd5e1'; ctx.fillText(dateText, boxX+12, boxY+28);

      // Etichetta percentuale sull'asse Y in corrispondenza del cursore.
      const axisText = pctText;
      ctx.font = '800 10px -apple-system,BlinkMacSystemFont,Segoe UI,sans-serif';
      const axisW = ctx.measureText(axisText).width + 10;
      const axisX = Math.max(1, pad.l - axisW - 3);
      const axisY = Math.max(1, Math.min(h-20, hy-9));
      ctx.fillStyle = 'rgba(10,13,18,.94)'; ctx.fillRect(axisX, axisY, axisW, 18);
      ctx.fillStyle = hoverColor; ctx.textAlign='center'; ctx.textBaseline='middle';
      ctx.fillText(axisText, axisX + axisW/2, axisY + 9);
      ctx.restore();
    }

    const unifiedValue = Math.max(0, Math.min(100, Number(last.v)));
    currentEl.textContent = (Math.round(unifiedValue*10)/10).toLocaleString(undefined,{maximumFractionDigits:1});
    currentEl.style.color = unifiedValue >= threshold ? blueLine : orangeLine;
    const pillValueEl = document.getElementById('altcoinIndexValue');
    const pillEl = document.getElementById('altcoinIndexPill');
    if (pillValueEl && pillEl && Number.isFinite(unifiedValue)) {
      pillValueEl.textContent = (Number.isInteger(unifiedValue) ? String(unifiedValue) : unifiedValue.toFixed(1)) + '/100';
      pillEl.dataset.state = 'live';
      pillEl.dataset.freshness = 'fresh';
      pillEl.dataset.updatedAt = String(Number(last.t) || Date.now());
      pillEl.dataset.zone = unifiedValue > 75 ? 'altseason' : unifiedValue < 25 ? 'bitcoinseason' : 'neutral';
      pillEl.style.setProperty('--altcoin-position', unifiedValue + '%');
      pillEl.setAttribute('aria-valuenow', String(unifiedValue));
    }
    frame.title = 'Altcoin Season Index · ' + currentRange.toUpperCase() + ' · ' + formatDate(data[0].t,false) + ' → ' + formatDate(last.t,false) + ' · dati reali';
  }

  async function load(range) {
    currentRange = range || '90d';
    hoverIndex = -1;
    rangeBtns.forEach(btn => btn.classList.toggle('active', btn.dataset.altcoinRange === currentRange));

    const instantRows = cachedHistory(currentRange);
    data = appendLive(instantRows);
    if (data.length) {
      loading.hidden = true;
      draw();
    } else {
      loading.hidden = false;
      loading.textContent = 'Caricamento dati reali Altcoin Season…';
      draw();
    }

    try {
      const rows = await fetchHistory(currentRange);
      data = rows;
      loading.hidden = true;
      draw();
    } catch (err) {
      console.warn('ALTCOIN INDEX dati reali', err);
      if (!data.length) {
        loading.hidden = false;
        loading.textContent = 'Dati reali temporaneamente non disponibili';
      }
    }
  }

  function openChart() {
    hoverIndex = -1;
    lastFocused = document.activeElement;
    overlay.hidden = false;
    document.documentElement.style.overflow = 'hidden';
    currentRange = '90d';
    requestAnimationFrame(() => { closeBtn.focus({preventScroll:true}); load('90d'); });
    if (!refreshTimer) refreshTimer = setInterval(() => { if (!overlay.hidden) load(currentRange); }, 30000);
  }
  function closeChart() {
    hoverIndex = -1;
    overlay.hidden = true;
    document.documentElement.style.overflow = '';
    if (refreshTimer) { clearInterval(refreshTimer); refreshTimer = null; }
    try { lastFocused?.focus?.({preventScroll:true}); } catch (_) {}
  }

  pill.addEventListener('click', openChart);
  pill.addEventListener('keydown', e => { if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); openChart(); } });
  closeBtn.addEventListener('click', closeChart);
  overlay.addEventListener('click', e => { if (e.target === overlay) closeChart(); });
  document.addEventListener('keydown', e => { if (!overlay.hidden && e.key === 'Escape') closeChart(); });
  rangeBtns.forEach(btn => btn.addEventListener('click', () => { hoverIndex = -1; load(btn.dataset.altcoinRange || '90d'); }));

  function nearestIndexForPointer(clientX) {
    if (!data.length) return -1;
    const rect = canvas.getBoundingClientRect();
    const w = Math.max(320, rect.width);
    const padL = 42, padR = 14;
    const pw = Math.max(1, w - padL - padR);
    const localX = Math.max(padL, Math.min(padL + pw, clientX - rect.left));
    const domain = visibleDomain(data, currentRange);
    const span = Math.max(1, domain.end - domain.start);
    const targetT = domain.start + ((localX - padL) / pw) * span;
    let lo = 0, hi = data.length - 1;
    while (lo < hi) {
      const mid = Math.floor((lo + hi) / 2);
      if (data[mid].t < targetT) lo = mid + 1;
      else hi = mid;
    }
    if (lo > 0 && Math.abs(data[lo-1].t - targetT) <= Math.abs(data[lo].t - targetT)) return lo - 1;
    return lo;
  }
  canvas.addEventListener('pointermove', e => {
    if (overlay.hidden || !data.length) return;
    const next = nearestIndexForPointer(e.clientX);
    if (next !== hoverIndex) { hoverIndex = next; draw(); }
  }, {passive:true});
  canvas.addEventListener('mousemove', e => {
    if (overlay.hidden || !data.length) return;
    const next = nearestIndexForPointer(e.clientX);
    if (next !== hoverIndex) { hoverIndex = next; draw(); }
  }, {passive:true});
  canvas.addEventListener('pointerleave', () => { if (hoverIndex !== -1) { hoverIndex = -1; draw(); } }, {passive:true});
  canvas.addEventListener('pointerdown', e => {
    if (overlay.hidden || !data.length) return;
    hoverIndex = nearestIndexForPointer(e.clientX);
    draw();
  }, {passive:true});

  window.addEventListener('resize', () => { if (overlay.hidden) return; cancelAnimationFrame(resizeRaf); resizeRaf=requestAnimationFrame(draw); }, {passive:true});
  document.addEventListener('visibilitychange', () => { if (!document.hidden && !overlay.hidden) load(currentRange); });
  // Shared layout updates for desktop, tablet rotation and browser toolbar changes.
  let layoutFrame=0;
  function refreshLayout(){
    if(overlay.hidden)return;
    cancelAnimationFrame(layoutFrame);
    layoutFrame=requestAnimationFrame(draw);
  }
  if(typeof ResizeObserver!=='undefined')new ResizeObserver(refreshLayout).observe(frame);
  window.visualViewport?.addEventListener('resize',refreshLayout,{passive:true});
  window.addEventListener('orientationchange',refreshLayout,{passive:true});
  if(typeof MutationObserver!=='undefined'){
    const themeObserver=new MutationObserver(refreshLayout);
    themeObserver.observe(document.documentElement,{attributes:true,attributeFilter:['data-theme','class']});
    themeObserver.observe(document.body,{attributes:true,attributeFilter:['data-theme','class']});
  }

  function resumeLivePanelV135(){if(!document.hidden&&!overlay.hidden)load(currentRange);}
  window.addEventListener('dashboard-pill-update',resumeLivePanelV135);
  window.addEventListener('online',resumeLivePanelV135);
  window.addEventListener('pageshow',resumeLivePanelV135);
  document.addEventListener('visibilitychange',resumeLivePanelV135);

  // V143: modalità riferimento rimossa; pannello sempre LIVE.

})();


