/* ===== JS originale 43/107: rainbow-pill-live-color-v79-graph-sync-script ===== */

(() => {
  'use strict';
  if (window.__RAINBOW_PILL_GRAPH_SYNC_V79__) return;
  window.__RAINBOW_PILL_GRAPH_SYNC_V79__ = true;

  /*
    V79 — BTC/ETH pillole sincronizzate con lo STESSO modello dei grafici Rainbow.
    - stessa regressione fitRainbowModel
    - stessi RAINBOW_OFFSETS per ciascun asset
    - stessi BAND_COLORS dei canvas BTC/ETH
    - stesso storico __dashboardChartHistoryFetch/__dashboardChartHistorySaved
    - stesso prezzo live __rainbowQuotesV136 / card principale
  */
  const CFG = {
    btc: {
      pill:'btcRainbowPill', value:'btcRainbowValue', price:'btc-price',
      genesis:Date.UTC(2009,0,3),
      offsets:[-0.45,-0.35,-0.25,-0.15,-0.05,0.05,0.15,0.25,0.35,0.45],
      cssPosition:'--btc-rainbow-position', cssColor:'--btc-rainbow-color'
    },
    eth: {
      pill:'ethRainbowPill', value:'ethRainbowValue', price:'eth-price',
      genesis:Date.UTC(2015,6,30),
      offsets:[-0.54,-0.42,-0.30,-0.18,-0.06,0.06,0.18,0.30,0.42,0.54],
      cssPosition:'--eth-rainbow-position', cssColor:'--eth-rainbow-color'
    }
  };
  const BAND_COLORS=['#1d4ed8','#2563eb','#06b6d4','#10b981','#84cc16','#facc15','#fb923c','#f97316','#ef4444'];
  const modelState={btc:null,eth:null};
  const rowsState={btc:[],eth:[]};
  let refreshBusy=false;

  function cleanRows(rows){
    const byTime=new Map();
    for(const r of (Array.isArray(rows)?rows:[])){
      const t=Number(r?.t), v=Number(r?.v);
      if(Number.isFinite(t)&&Number.isFinite(v)&&v>0) byTime.set(t,{t,v});
    }
    return Array.from(byTime.values()).sort((a,b)=>a.t-b.t);
  }

  function parsePriceText(text){
    let s=String(text||'').trim().replace(/\s+/g,'').replace(/[^0-9,.-]/g,'');
    if(!s) return NaN;
    const lc=s.lastIndexOf(','), ld=s.lastIndexOf('.');
    if(lc>ld) s=s.replace(/\./g,'').replace(',', '.');
    else s=s.replace(/,/g,'');
    return Number(s);
  }

  function readPrice(asset){
    const shared=Number(window.__rainbowQuotesV136?.[asset]?.value);
    if(Number.isFinite(shared)&&shared>0) return shared;
    const el=document.getElementById(CFG[asset].price);
    const n=parsePriceText(el?.textContent);
    return Number.isFinite(n)&&n>0?n:NaN;
  }

  function quoteTime(asset){
    const raw=Number(window.__rainbowQuotesV136?.[asset]?.timestamp);
    return Number.isFinite(raw)&&raw>0?raw:Date.now();
  }

  function appendLive(rows,asset){
    const out=cleanRows(rows);
    const price=readPrice(asset);
    if(!Number.isFinite(price)||price<=0) return out;
    const q=window.__rainbowQuotesV136?.[asset];
    if(q?.cached) return out;
    const d=new Date(quoteTime(asset));
    d.setUTCHours(0,0,0,0);
    const t=d.getTime();
    if(!out.length||out[out.length-1].t<t) out.push({t,v:price});
    else out[out.length-1]={t,v:price};
    return out;
  }

  function fitRainbowModel(rows,genesis){
    const pts=[];
    for(const p of rows||[]){
      const days=(Number(p?.t)-genesis)/86400000;
      const price=Number(p?.v);
      if(!Number.isFinite(days)||days<=30||!Number.isFinite(price)||price<=0) continue;
      pts.push([Math.log(days),Math.log10(price)]);
    }
    if(pts.length<20) return null;
    let sx=0,sy=0,sxx=0,sxy=0;
    for(const [x,y] of pts){sx+=x;sy+=y;sxx+=x*x;sxy+=x*y;}
    const n=pts.length, den=n*sxx-sx*sx;
    if(!Number.isFinite(den)||Math.abs(den)<1e-12) return null;
    const a=(n*sxy-sx*sy)/den;
    const b=(sy-a*sx)/n;
    return {a,b};
  }

  function modelPrice(ms,model,cfg,offset=0){
    if(!model) return NaN;
    const days=Math.max(31,(ms-cfg.genesis)/86400000);
    return Math.pow(10,model.a*Math.log(days)+model.b+offset);
  }

  function stateFor(price,ms,model,cfg){
    const center=modelPrice(ms,model,cfg,0);
    if(!Number.isFinite(center)||center<=0||!Number.isFinite(price)||price<=0) return null;
    const off=Math.log10(price)-Math.log10(center);
    let idx=0;
    while(idx<cfg.offsets.length-1 && off>cfg.offsets[idx+1]) idx++;
    idx=Math.max(0,Math.min(BAND_COLORS.length-1,idx));

    const lo=cfg.offsets[0], hi=cfg.offsets[cfg.offsets.length-1];
    const pos=Math.max(0,Math.min(100,((off-lo)/(hi-lo))*100));
    return {index:idx,color:BAND_COLORS[idx],position:pos,offset:off};
  }

  function fmt(v){
    if(!Number.isFinite(v)) return '—';
    try{
      return new Intl.NumberFormat('it-IT',{
        style:'currency',currency:'USD',maximumFractionDigits:v>=1000?0:2
      }).format(v);
    }catch(_){return '$'+v.toFixed(v>=1000?0:2);}
  }

  function paint(asset){
    const cfg=CFG[asset];
    const pill=document.getElementById(cfg.pill);
    const value=document.getElementById(cfg.value);
    if(!pill||!value) return;
    const price=readPrice(asset);
    if(!Number.isFinite(price)||price<=0) return;

    /* Rifit con il live di oggi: identico ad appendLive() usato dal grafico. */
    const liveRows=appendLive(rowsState[asset],asset);
    let model=fitRainbowModel(liveRows,cfg.genesis)||modelState[asset];
    if(!model) return;
    modelState[asset]=model;

    const st=stateFor(price,quoteTime(asset),model,cfg);
    if(!st) return;

    value.textContent=fmt(price);
    value.style.setProperty('color',st.color,'important');
    value.style.setProperty('-webkit-text-fill-color',st.color,'important');
    value.style.setProperty('text-shadow','0 0 8px '+st.color+'55','important');

    pill.dataset.rainbowBand=String(st.index);
    /* Compatibilità con gli stili storici a 7 zone, senza cambiare il colore reale V79. */
    pill.dataset.zone='z'+Math.max(0,Math.min(6,Math.round(st.index*6/(BAND_COLORS.length-1))));
    pill.style.setProperty(cfg.cssPosition,st.position.toFixed(2)+'%');
    pill.style.setProperty(cfg.cssColor,st.color,'important');
    pill.setAttribute('aria-valuenow',st.position.toFixed(1));
    pill.dataset.rainbowGraphSync='true';
    pill.dataset.rainbowGraphColor=st.color;
  }

  function sync(){paint('btc');paint('eth');}

  async function loadModel(asset){
    const cfg=CFG[asset];
    let rows=[];
    try{
      const saved=window.__dashboardChartHistorySaved?.(asset);
      rows=cleanRows(saved?.rows||[]);
    }catch(_){}

    if(rows.length>=20){
      rowsState[asset]=rows;
      modelState[asset]=fitRainbowModel(appendLive(rows,asset),cfg.genesis);
      paint(asset);
    }

    try{
      if(typeof window.__dashboardChartHistoryFetch==='function'){
        const payload=await window.__dashboardChartHistoryFetch(asset,'max');
        const fresh=cleanRows(payload?.rows||[]);
        if(fresh.length>=20){
          rowsState[asset]=fresh;
          modelState[asset]=fitRainbowModel(appendLive(fresh,asset),cfg.genesis);
          paint(asset);
        }
      }
    }catch(err){
      console.warn(asset.toUpperCase()+' Rainbow pill graph sync',err);
    }
  }

  async function refreshModels(){
    if(refreshBusy) return;
    refreshBusy=true;
    try{await Promise.all([loadModel('btc'),loadModel('eth')]);}
    finally{refreshBusy=false;sync();}
  }

  function observePrice(id){
    const el=document.getElementById(id);
    if(!el||typeof MutationObserver==='undefined') return;
    new MutationObserver(sync).observe(el,{childList:true,characterData:true,subtree:true});
  }

  function start(){
    observePrice('btc-price');
    observePrice('eth-price');
    refreshModels();
    sync();
    setInterval(sync,500);
    setInterval(refreshModels,60000);
  }

  if(document.readyState==='loading') document.addEventListener('DOMContentLoaded',start,{once:true});
  else start();

  window.addEventListener('rainbow-quote-v136',sync,{passive:true});
  window.addEventListener('online',refreshModels,{passive:true});
  window.addEventListener('pageshow',()=>{refreshModels();setTimeout(sync,60);},{passive:true});
  window.addEventListener('focus',()=>setTimeout(sync,60),{passive:true});
  document.addEventListener('visibilitychange',()=>{if(!document.hidden){refreshModels();sync();}},{passive:true});
})();


