/* ===== JS originale 44/107: fear-greed-number-color-v83-script ===== */

(function(){
  'use strict';
  if(window.__FNG_NUMBER_COLOR_V80__) return;
  window.__FNG_NUMBER_COLOR_V80__=true;
  const COLORS={
    'extreme-fear':'#ff3b5f',
    'fear':'#f59e0b',
    'neutral':'#facc15',
    'greed':'#66d68f',
    'extreme-greed':'#159c62'
  };
  function zoneFromValue(v){
    v=Number(v);
    if(!Number.isFinite(v)) return 'neutral';
    if(v<=24) return 'extreme-fear';
    if(v<=44) return 'fear';
    if(v<=55) return 'neutral';
    if(v<=74) return 'greed';
    return 'extreme-greed';
  }
  function numericValue(){
    const el=document.getElementById('fearGreedValue');
    if(!el) return NaN;
    const raw=String(el.textContent||'').replace('/100','').replace(',','.').trim();
    return Number(raw);
  }
  function paint(){
    const pill=document.getElementById('fearGreedPill');
    const el=document.getElementById('fearGreedValue');
    if(!pill||!el) return;
    const v=numericValue();
    const zone=Number.isFinite(v)?zoneFromValue(v):(pill.dataset.zone||'neutral');
    const color=COLORS[zone]||COLORS.neutral;
    if(pill.dataset.zone!==zone) pill.dataset.zone=zone;
    pill.style.setProperty('--fng-color',color);
    el.style.setProperty('color',color,'important');
    el.style.setProperty('-webkit-text-fill-color',color,'important');
    el.style.setProperty('text-shadow','0 0 8px '+color+'55','important');
  }
  function boot(){
    paint();
    const pill=document.getElementById('fearGreedPill');
    const el=document.getElementById('fearGreedValue');
    if(typeof MutationObserver!=='undefined'){
      if(el){
        const mo=new MutationObserver(paint);
        mo.observe(el,{childList:true,characterData:true,subtree:true});
      }
      /* V83: niente observer sugli attributi della pillola: evita cicli ricorsivi. */
    }
    setInterval(paint,1000);
  }
  if(document.readyState==='loading') document.addEventListener('DOMContentLoaded',boot,{once:true}); else boot();
})();


