/* ===== JS originale 49/107: final-24h-absolute-change-live ===== */

(()=>{
'use strict';
if(window.__FINAL_24H_ABSOLUTE_CHANGE__) return;
window.__FINAL_24H_ABSOLUTE_CHANGE__ = true;

const prefixes=[
  'btc','eth','bnb','sol','ray','inj','ore','tai',
  'virtual','wld','orai','tao','lunc','luna'
];

const states=new Map();

function parseItalianPrice(text){
  const raw=String(text||'').trim();
  if(!raw || raw==='—') return null;

  const numberMatch=raw.match(/[-+]?\d[\d.]*?(?:,\d+)?(?=\s|$)/);
  if(!numberMatch) return null;

  const numeric=Number(numberMatch[0].replace(/\./g,'').replace(',','.'));
  if(!Number.isFinite(numeric)) return null;

  const comma=numberMatch[0].lastIndexOf(',');
  const decimals=comma>=0 ? numberMatch[0].length-comma-1 : 0;
  const quote=(raw.match(/\b([A-Z]{2,8})\b\s*$/)||[])[1] || '';

  return {value:numeric,decimals,quote};
}

function parsePercent(raw){
  const s=String(raw||'').trim();
  if(!s || s==='—') return null;

  const matches=[...s.matchAll(/([+\-−]?)\s*(\d+(?:[.,]\d+)?)\s*%/g)];
  if(!matches.length) return null;

  const m=matches[matches.length-1];
  const value=Number(m[2].replace(',','.'));
  if(!Number.isFinite(value)) return null;

  const negative=m[1]==='-' || m[1]==='−' || /▼/.test(s);
  return {value:negative ? -Math.abs(value) : Math.abs(value)};
}

function formatDelta(value,decimals,quote){
  const sign=value>=0?'+':'−';
  const abs=Math.abs(value);
  const d=Math.max(0,Math.min(8,Number(decimals)||0));
  const formatted=abs.toLocaleString('it-IT',{
    minimumFractionDigits:d,
    maximumFractionDigits:d,
    useGrouping:true
  });
  return sign+formatted+(quote?' '+quote:'');
}

function formatPct(value){
  const sign=value>=0?'+':'−';
  return sign+Math.abs(value).toLocaleString('it-IT',{
    minimumFractionDigits:2,
    maximumFractionDigits:2,
    useGrouping:false
  })+'% 24h';
}

function update(prefix,source){
  const priceEl=document.getElementById(prefix+'-price');
  const changeEl=document.getElementById(prefix+'-change');
  if(!priceEl || !changeEl) return;

  let st=states.get(prefix)||{pct:null,writing:false};
  if(st.writing) return;

  // Quando il feed originale riscrive la variazione, salviamo la % fresca.
  if(source==='change' || !st.pct){
    const parsed=parsePercent(changeEl.textContent);
    if(parsed) st.pct=parsed.value;
  }

  const price=parseItalianPrice(priceEl.textContent);
  if(!price || !Number.isFinite(st.pct)){
    states.set(prefix,st);
    return;
  }

  // Ricava la variazione assoluta 24h dal prezzo LIVE e dalla % 24h.
  const factor=1+(st.pct/100);
  if(!Number.isFinite(factor) || factor<=0){
    states.set(prefix,st);
    return;
  }

  const previous=price.value/factor;
  const delta=price.value-previous;

  const exact = prefix === 'ore'
    ? (
        '+' + Math.abs(delta).toLocaleString('it-IT',{
          minimumFractionDigits:Math.max(0,Math.min(8,Number(price.decimals)||0)),
          maximumFractionDigits:Math.max(0,Math.min(8,Number(price.decimals)||0)),
          useGrouping:true
        }) + (price.quote ? ' ' + price.quote : '') +
        '   +' + Math.abs(st.pct).toLocaleString('it-IT',{
          minimumFractionDigits:2,
          maximumFractionDigits:2,
          useGrouping:false
        }) + '% 24h'
      )
    : formatDelta(delta,price.decimals,price.quote)+'   '+formatPct(st.pct);

  if(String(changeEl.textContent||'').trim()!==exact){
    st.writing=true;
    changeEl.textContent=exact;
    queueMicrotask(()=>{st.writing=false;});
  }

  states.set(prefix,st);
}

function bind(prefix){
  const priceEl=document.getElementById(prefix+'-price');
  const changeEl=document.getElementById(prefix+'-change');
  if(!priceEl || !changeEl) return;

  const initial=parsePercent(changeEl.textContent);
  states.set(prefix,{pct:initial?.value ?? null,writing:false});

  if(typeof MutationObserver==='function'){
    new MutationObserver(()=>update(prefix,'price'))
      .observe(priceEl,{childList:true,characterData:true,subtree:true});

    new MutationObserver(()=>{
      const st=states.get(prefix);
      if(st?.writing) return;
      update(prefix,'change');
    }).observe(changeEl,{childList:true,characterData:true,subtree:true});
  }

  update(prefix,'change');
}

function init(){
  prefixes.forEach(bind);
  try{document.documentElement.dataset.final24h='absolute-change-and-percent';}catch(_){}
}

if(document.readyState==='loading'){
  document.addEventListener('DOMContentLoaded',init,{once:true});
}else{
  init();
}

window.addEventListener('pageshow',()=>{
  prefixes.forEach(p=>update(p,'price'));
},{passive:true});
})();


