/* ===== JS originale 55/107: v125-windows-mobile-chart-js ===== */

(() => {
  const ua = String(navigator.userAgent || '');
  const platform = String(navigator.platform || '');
  const isWindows = Boolean(
    window.__DASHBOARD_WINDOWS__ ||
    /Windows/i.test(ua) ||
    /^Win/i.test(platform)
  );

  if (!isWindows) return;

  document.documentElement.classList.add('windows-mobile-chart');

  const syncWindowsCharts = () => {
    try {
      Object.entries(window.charts || {}).forEach(([symbol, bundle]) => {
        if (!bundle?.chart) return;

        const cfg = window.ASSETS?.[symbol];
        const container = cfg ? document.getElementById(cfg.key + '-chart') : null;
        if (container) {
          const rect = container.getBoundingClientRect();
          if (rect.width > 10 && rect.height > 10) {
            try {
              bundle.chart.applyOptions({
                width: Math.round(rect.width),
                height: Math.round(rect.height),
                leftPriceScale: {
                  visible: false
                },
                rightPriceScale: {
                  visible: true,
                  borderVisible: true,
                  minimumWidth: 92,
                  entireTextOnly: true
                },
                handleScroll: {
                  mouseWheel: false,
                  pressedMouseMove: false,
                  horzTouchDrag: false,
                  vertTouchDrag: false
                },
                handleScale: {
                  axisPressedMouseMove: { time: true, price: true },
                  axisDoubleClickReset: { time: true, price: true },
                  mouseWheel: true,
                  pinch: true
                }
              });
            } catch (_) {}
          }
        }

        Object.values(bundle.indicators || {}).forEach(indicator => {
          const el = indicator?.container;
          if (!el || !indicator.chart) return;
          const r = el.getBoundingClientRect();
          if (r.width > 10 && r.height > 10) {
            try {
              indicator.chart.applyOptions({
                width: Math.round(r.width),
                height: Math.round(r.height)
              });
            } catch (_) {}
          }
        });
      });
    } catch (_) {}
  };

  requestAnimationFrame(() => {
    syncWindowsCharts();
    requestAnimationFrame(syncWindowsCharts);
  });

  setTimeout(syncWindowsCharts, 120);
  setTimeout(syncWindowsCharts, 500);
  window.addEventListener('resize', syncWindowsCharts, { passive: true });
})();


