/* ===== JS originale 56/107: raydium-dati-v22-controller ===== */

(() => {
  'use strict';

  const OWNER='DdHDoz94o2WJmD9myRobHCwtx1bESpHTd4SSPe6VEZaz';
  const MINT='4k3Dyjzvzp8eMZWUXbBCjEvwSkkk59S5iCNLY3QrkX6R';
  const STORE='crypto-dashboard-ray-v22-real-data';
  const SOLSCAN_TOKENS='https://public-api.solscan.io/account/tokens?account='+encodeURIComponent(OWNER);
  const SOLSCAN_TRANSFERS='https://public-api.solscan.io/account/splTransfers';
  const RPCS=[
    'https://api.mainnet-beta.solana.com',
    'https://solana-rpc.publicnode.com',
    'https://solana.drpc.org',
    'https://solana.api.onfinality.io/public'
  ];

  // Ultimo totale pubblico verificato disponibile prima della creazione del file.
  // Serve solo ad evitare un trattino al primo frame; viene rimpiazzato appena una fonte LIVE risponde.
  const VERIFIED_SEED_TOTAL=84740000;
  const VERIFIED_SEED_DATE='2026-09-01';

  const $=id=>document.getElementById(id);
  let busy=false;
  let lastGood=null;

  function dayRome(ts=Date.now()){
    try{return new Intl.DateTimeFormat('en-CA',{timeZone:'Europe/Rome',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date(ts))}
    catch(_){return new Date(ts).toISOString().slice(0,10)}
  }
  function midnightRomeUnix(){
    const now=new Date(), parts={};
    new Intl.DateTimeFormat('en-US',{timeZone:'Europe/Rome',year:'numeric',month:'2-digit',day:'2-digit'})
      .formatToParts(now).forEach(p=>{if(p.type!=='literal')parts[p.type]=p.value});
    const target=Date.UTC(+parts.year,+parts.month-1,+parts.day,0,0,0);
    const probe=new Date(target), z={};
    new Intl.DateTimeFormat('en-US',{timeZone:'Europe/Rome',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',second:'2-digit',hourCycle:'h23'})
      .formatToParts(probe).forEach(p=>{if(p.type!=='literal')z[p.type]=p.value});
    const represented=Date.UTC(+z.year,+z.month-1,+z.day,+z.hour,+z.minute,+z.second);
    let candidate=target-(represented-target);
    const probe2=new Date(candidate), z2={};
    new Intl.DateTimeFormat('en-US',{timeZone:'Europe/Rome',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',second:'2-digit',hourCycle:'h23'})
      .formatToParts(probe2).forEach(p=>{if(p.type!=='literal')z2[p.type]=p.value});
    const represented2=Date.UTC(+z2.year,+z2.month-1,+z2.day,+z2.hour,+z2.minute,+z2.second);
    candidate += target-represented2;
    return Math.floor(candidate/1000);
  }
  function clock(){
    try{return new Intl.DateTimeFormat('it-IT',{timeZone:'Europe/Rome',hour:'2-digit',minute:'2-digit',second:'2-digit'}).format(new Date())}
    catch(_){return new Date().toLocaleTimeString('it-IT')}
  }
  function fmt(n,approx=false){
    n=Number(n); if(!Number.isFinite(n)||n<0)n=0;
    const text=new Intl.NumberFormat('it-IT',{maximumFractionDigits:6}).format(n)+' RAY';
    return text;
  }
  function read(){try{return JSON.parse(localStorage.getItem(STORE)||'{}')||{}}catch(_){return{}}}
  function save(v){try{localStorage.setItem(STORE,JSON.stringify({...read(),...v}))}catch(_){}}
  function validNum(v){return Number.isFinite(Number(v))&&Number(v)>=0}

  function ensurePair(){
    const section=$('ray-burn-section'); if(!section)return false;
    const grid=section.querySelector('.burn-daily-total-v34');
    if(grid){grid.style.setProperty('display','grid','important');grid.style.setProperty('visibility','visible','important');grid.style.setProperty('opacity','1','important')}
    const dl=$('ray-v40-daily-label'),tl=$('ray-v40-total-label');
    if(dl)dl.textContent='RAY buyback oggi · LIVE';
    if(tl)tl.textContent='RAY buyback holding · totale LIVE';
    const oldGrid=$('ray-v21-grid'); if(oldGrid)oldGrid.style.setProperty('display','none','important');
    return true;
  }

  function paint(daily,total,source='LIVE',approxTotal=false,approxDaily=false){
    ensurePair();
    const dText=fmt(daily,approxDaily), tText=fmt(total,approxTotal);
    const values=[
      ['ray-v40-daily',dText],['ray-burn-total',dText],
      ['ray-v40-total',tText],['ray-burn-secondary',tText]
    ];
    for(const [id,text] of values){const el=$(id);if(el){el.textContent=text;el.dataset.realOnchain='true';el.dataset.rayV22='true'}}
    const dn=$('ray-v40-daily-note'),tn=$('ray-v40-total-note');
    if(dn){dn.textContent=(approxDaily?'Dato provvisorio · ':'LIVE · ')+source+' · oggi Europe/Rome · '+clock();dn.classList.toggle('live',!approxDaily)}
    if(tn){tn.textContent=(approxTotal?'Ultimo totale pubblico verificato '+VERIFIED_SEED_DATE+' · ':'LIVE · ')+source+' · '+clock();tn.classList.toggle('live',!approxTotal)}
    const status=$('ray-burn-status'),src=$('ray-burn-source'),upd=$('ray-burn-updated');
    if(status){status.textContent='RAY · OGGI + TOTALE · DATI';status.className='burn-status '+((approxTotal||approxDaily)?'warn':'live')}
    if(src)src.textContent='Fonte: '+source+' · Raydium buyback holding';
    if(upd)upd.textContent=clock()+' · '+((approxTotal||approxDaily)?'ultimo dato disponibile':'LIVE');
  }

  function initialPaint(){
    ensurePair();
    const c=read(),today=dayRome();
    const total=validNum(c.total)?Number(c.total):VERIFIED_SEED_TOTAL;
    const totalApprox=!validNum(c.total);
    // Niente trattini. Se non abbiamo ancora un giornaliero reale della data odierna,
    // parte da 0 e viene sostituito dal primo dato Solscan/RPC ricevuto.
    const sameDay=c.day===today&&validNum(c.daily);
    const daily=sameDay?Number(c.daily):0;
    paint(daily,total,sameDay?(c.source||'cache LIVE'):'aggiornamento in corso',totalApprox,!sameDay);
  }

  async function getJson(url,timeout=10000){
    const ac=new AbortController(),timer=setTimeout(()=>ac.abort(),timeout);
    try{
      const r=await fetch(url,{method:'GET',mode:'cors',cache:'no-store',credentials:'omit',signal:ac.signal,headers:{'Accept':'application/json'}});
      if(!r.ok)throw new Error('HTTP '+r.status);
      return await r.json();
    }finally{clearTimeout(timer)}
  }

  function parseSolscanTokenTotal(payload){
    const rows=Array.isArray(payload)?payload:(Array.isArray(payload?.data)?payload.data:(Array.isArray(payload?.items)?payload.items:[]));
    let total=0,found=false;
    for(const row of rows){
      const token=String(row?.tokenAddress??row?.mint??row?.token_address??'');
      if(token!==MINT)continue;
      const ta=row?.tokenAmount??row?.token_amount??row?.amount??{};
      const dec=Number(ta?.decimals??row?.decimals??6);
      let ui=Number(ta?.uiAmount??ta?.uiAmountString??row?.uiAmount??row?.ui_amount);
      if(!Number.isFinite(ui)){
        const raw=String(ta?.amount??row?.amountRaw??row?.rawAmount??'');
        if(/^\d+$/.test(raw)&&Number.isFinite(dec))ui=Number(raw)/Math.pow(10,dec);
      }
      if(Number.isFinite(ui)&&ui>=0){total+=ui;found=true}
    }
    if(!found)throw new Error('RAY non trovato nella risposta Solscan');
    return total;
  }

  function transferRows(payload){
    if(Array.isArray(payload))return payload;
    if(Array.isArray(payload?.data))return payload.data;
    if(Array.isArray(payload?.items))return payload.items;
    if(Array.isArray(payload?.data?.items))return payload.data.items;
    return [];
  }
  function parseSolscanDaily(payload,midnight){
    const rows=transferRows(payload);
    let daily=0,matched=0;
    for(const row of rows){
      const token=String(row?.tokenAddress??row?.mint??row?.token_address??'');
      const bt=Number(row?.blockTime??row?.block_time??row?.timestamp??0);
      if(token!==MINT||!Number.isFinite(bt)||bt<midnight)continue;
      const kind=String(row?.changeType??row?.change_type??row?.type??'').toLowerCase();
      const owner=String(row?.owner??row?.destination_owner??row?.to_owner??'');
      // Legacy Solscan account/splTransfers è già account-scoped. Se espone owner,
      // richiediamo che corrisponda al buyback wallet. Contiamo solo incrementi.
      if(owner&&owner!==OWNER)continue;
      if(kind&& !/inc|in|receive|deposit/.test(kind))continue;
      const dec=Number(row?.decimals??6);
      let raw=row?.changeAmount??row?.change_amount??row?.amount;
      let amount=Number(raw);
      if(!Number.isFinite(amount))continue;
      if(Number.isInteger(dec)&&dec>=0)amount=amount/Math.pow(10,dec);
      if(amount>=0){daily+=amount;matched++}
    }
    // Una risposta valida con zero righe dopo mezzanotte significa 0 RAY oggi.
    return {daily,matched,rows:rows.length};
  }

  async function solscanPair(){
    const midnight=midnightRomeUnix(),now=Math.floor(Date.now()/1000);
    const totalPayload=await getJson(SOLSCAN_TOKENS,9000);
    const total=parseSolscanTokenTotal(totalPayload);
    const urls=[
      SOLSCAN_TRANSFERS+'?account='+encodeURIComponent(OWNER)+'&fromTime='+midnight+'&toTime='+now+'&limit=50&offset=0',
      SOLSCAN_TRANSFERS+'?address='+encodeURIComponent(OWNER)+'&fromTime='+midnight+'&toTime='+now+'&limit=50&offset=0'
    ];
    let lastErr=null;
    for(const u of urls){
      try{
        const p=await getJson(u,10000);
        const d=parseSolscanDaily(p,midnight);
        return {daily:d.daily,total,source:'Solscan REST',detail:d};
      }catch(e){lastErr=e}
    }
    // Il totale è comunque reale anche se lo storico non risponde.
    return {daily:null,total,source:'Solscan REST',error:lastErr};
  }

  async function postRpc(endpoint,method,params,timeout=10000){
    const ac=new AbortController(),timer=setTimeout(()=>ac.abort(),timeout);
    try{
      const r=await fetch(endpoint,{method:'POST',mode:'cors',cache:'no-store',credentials:'omit',signal:ac.signal,
        headers:{'Content-Type':'application/json','Accept':'application/json'},
        body:JSON.stringify({jsonrpc:'2.0',id:1,method,params})});
      if(!r.ok)throw new Error('HTTP '+r.status);
      const j=await r.json(); if(j?.error)throw new Error(j.error.message||'RPC error'); return j.result;
    }finally{clearTimeout(timer)}
  }

  async function rpcSnapshot(){
    let last;
    for(const ep of RPCS){
      try{
        const result=await postRpc(ep,'getTokenAccountsByOwner',[OWNER,{mint:MINT},{encoding:'jsonParsed',commitment:'confirmed'}],10000);
        const rows=Array.isArray(result?.value)?result.value:[];
        if(!rows.length)throw new Error('nessun account RAY');
        let total=0; const accounts=[];
        for(const r of rows){
          const a=r?.account?.data?.parsed?.info?.tokenAmount;
          const ui=Number(a?.uiAmountString??a?.uiAmount);
          if(Number.isFinite(ui))total+=ui;
          if(r?.pubkey)accounts.push(String(r.pubkey));
        }
        if(!Number.isFinite(total)||total<=0)throw new Error('saldo RAY non valido');
        return {total,accounts,endpoint:ep};
      }catch(e){last=e}
    }
    throw last||new Error('RPC non disponibile');
  }

  async function refresh(){
    if(busy||document.hidden||navigator.onLine===false)return;
    busy=true;
    const cached=read(),today=dayRome();
    try{
      let pair=null;
      try{pair=await solscanPair()}catch(_){pair=null}

      if(pair&&validNum(pair.total)){
        const dailyReal=validNum(pair.daily);
        const daily=dailyReal?Number(pair.daily):(cached.day===today&&validNum(cached.daily)?Number(cached.daily):0);
        paint(daily,Number(pair.total),pair.source,false,!dailyReal);
        save({total:Number(pair.total),totalAt:Date.now(),daily:dailyReal?Number(pair.daily):(cached.day===today?cached.daily:undefined),day:today,source:pair.source});
        lastGood={daily,total:Number(pair.total),source:pair.source,dailyReal};
        // Se Solscan ha dato solo il saldo, RPC può eventualmente completare/riconfermare.
        if(dailyReal)return;
      }

      const snap=await rpcSnapshot();
      const d=(cached.day===today&&validNum(cached.daily))?Number(cached.daily):0;
      paint(d,snap.total,'Solana RPC',false,!(cached.day===today&&validNum(cached.daily)));
      save({total:snap.total,totalAt:Date.now(),day:today,source:'Solana RPC'});
      lastGood={daily:d,total:snap.total,source:'Solana RPC',dailyReal:false};
    }catch(e){
      // Mai più "—": mantieni l'ultimo numero disponibile e segnala soltanto nella nota.
      const c=read(),same=c.day===today&&validNum(c.daily);
      const total=validNum(c.total)?Number(c.total):VERIFIED_SEED_TOTAL;
      const daily=same?Number(c.daily):0;
      paint(daily,total,same?(c.source||'ultimo dato LIVE'):'ultimo dato disponibile',!validNum(c.total),!same);
    }finally{busy=false}
  }

  function boot(){
    initialPaint();
    setTimeout(refresh,120);
    setInterval(refresh,20000);
    // Re-applica i numeri se un vecchio controller della dashboard prova a rimettere trattini/testi.
    setInterval(()=>{
      const c=read(),today=dayRome();
      const same=c.day===today&&validNum(c.daily);
      const total=validNum(c.total)?Number(c.total):VERIFIED_SEED_TOTAL;
      const daily=same?Number(c.daily):0;
      const visibleDaily=$('ray-v40-daily'),visibleTotal=$('ray-v40-total');
      if(!visibleDaily||!/\d/.test(visibleDaily.textContent||'')||!visibleTotal||!/\d/.test(visibleTotal.textContent||'')){
        paint(daily,total,c.source||'aggiornamento in corso',!validNum(c.total),!same);
      }
    },1500);
    window.addEventListener('online',refresh,{passive:true});
    window.addEventListener('focus',refresh,{passive:true});
    document.addEventListener('visibilitychange',()=>{if(!document.hidden)refresh()});
    window.refreshRaydiumBuybackV22=refresh;
  }
  if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',boot,{once:true});else boot();
})();


;
/* ===== JS originale 57/107: ipad-top-five-pills-live-v88 ===== */

(() => {
  'use strict';
  if (window.__IPAD_TOP_FIVE_PILLS_V88__) return;
  window.__IPAD_TOP_FIVE_PILLS_V88__ = true;

  const ua = String(navigator.userAgent || '');
  const touches = Number(navigator.maxTouchPoints || 0);
  const isIpad = /iPad|EdgiOS/i.test(ua) || ((/Macintosh|MacIntel/i.test(ua) || navigator.platform === 'MacIntel') && touches > 1) || window.__DASHBOARD_IPAD_PRO_12_9__ === true;
  if (!isIpad) return;

  document.documentElement.classList.add('ipad-pill-data-v88');

  const VALUE_IDS = ['globalTotalValue','globalTotal2Value','globalTotal3Value','altcoinIndexValue','fearGreedValue'];
  const PILL_IDS = ['globalTotalPill','globalTotal2Pill','globalTotal3Pill','altcoinIndexPill','fearGreedPill'];
  function byId(id) { return document.getElementById(id); }
  function hasLiveValue(id) {
    const el = byId(id);
    if (!el) return false;
    const txt = String(el.textContent || '').trim();
    return !!txt && txt !== '—' && /\d/.test(txt);
  }
  function allReady() { return VALUE_IDS.every(hasLiveValue); }
  function forceLabels() {
    const p2 = byId('globalTotal2Pill');
    const p3 = byId('globalTotal3Pill');
    const p2Label = p2 && p2.querySelector('.global-marketcap-pill-label');
    const p3Label = p3 && p3.querySelector('.global-marketcap-pill-label');
    if (p2Label) p2Label.textContent = 'TOTAL 1';
    if (p3Label) p3Label.textContent = 'TOTAL 2';
    if (p2) p2.title = String(p2.title || '').replace(/^TOTAL\s*2/i, 'TOTAL 1');
    if (p3) p3.title = String(p3.title || '').replace(/^TOTAL\s*3/i, 'TOTAL 2');
  }
  function reveal() {
    forceLabels();
    PILL_IDS.forEach(id => {
      const pill = byId(id);
      if (!pill) return;
      pill.style.setProperty('visibility', 'visible', 'important');
      pill.style.setProperty('opacity', '1', 'important');
    });
    [['globalTotalPill','globalTotalValue'],['globalTotal2Pill','globalTotal2Value'],['globalTotal3Pill','globalTotal3Value'],['altcoinIndexPill','altcoinIndexValue'],['fearGreedPill','fearGreedValue']].forEach(([pillId, valueId]) => {
      const pill = byId(pillId);
      if (pill && hasLiveValue(valueId)) pill.dataset.state = 'live';
    });
  }
  function kick() {
    reveal();
    try { if (typeof window.refreshTopFivePillsV88 === 'function') window.refreshTopFivePillsV88(); else if (typeof window.refreshTopFivePillsV10 === 'function') window.refreshTopFivePillsV10(); } catch (_) {}
    setTimeout(reveal, 180);
    setTimeout(reveal, 900);
  }
  function watchdog() {
    reveal();
    if (!allReady()) kick();
  }
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', () => {
      reveal();
      setTimeout(kick, 120);
      setTimeout(kick, 900);
      setTimeout(kick, 2200);
    }, { once: true });
  } else {
    reveal();
    setTimeout(kick, 120);
    setTimeout(kick, 900);
    setTimeout(kick, 2200);
  }
  window.addEventListener('pageshow', kick, { passive: true });
  window.addEventListener('focus', kick, { passive: true });
  window.addEventListener('online', kick, { passive: true });
  window.addEventListener('orientationchange', () => setTimeout(kick, 140), { passive: true });
  document.addEventListener('visibilitychange', () => { if (!document.hidden) kick(); }, { passive: true });
  setInterval(watchdog, 2500);
})();


