/* ===== JS originale 64/107: v114-wld-orai-burn-daily-total-script ===== */

(() => {
  'use strict';
  if(window.__WLD_ORAI_BURN_DAILY_TOTAL_V114__) return;
  window.__WLD_ORAI_BURN_DAILY_TOTAL_V114__=true;

  const CFG={
    wld:{
      daily:'0 WLD',
      total:'0 WLD',
      dailyNote:'Nessun burn periodico o automatico previsto dalla tokenomics ufficiale.',
      totalNote:'Nessun burn ufficiale documentato; supply cap iniziale 10.000.000.000 WLD.'
    },
    orai:{
      daily:'Non pubblicato',
      total:'67.258.449,4 ORAI',
      dailyNote:'Non viene inventato un valore giornaliero: le fonti ufficiali pubblicano burn storici, non un contatore 24h.',
      totalNote:'Totale storico documentato: 63.000.000 + 258.449,4 + 3.000.000 + 500.000 + 500.000 ORAI.'
    }
  };

  function build(key){
    const section=document.getElementById(key+'-burn-section');
    if(!section) return;
    let grid=section.querySelector('.v114-burn-pair');
    if(!grid){
      grid=document.createElement('div');
      grid.className='v114-burn-pair';
      const base=section.querySelector('.burn-grid');
      if(base) base.insertAdjacentElement('beforebegin',grid);
      else section.querySelector('.burn-head')?.insertAdjacentElement('afterend',grid);
    }
    const c=CFG[key];
    grid.innerHTML=`
      <div class="burn-item">
        <span class="burn-label">Burn giornaliero (24h)</span>
        <strong class="burn-value" id="${key}-v114-daily">${c.daily}</strong>
        <small class="burn-note">${c.dailyNote}</small>
      </div>
      <div class="burn-item">
        <span class="burn-label">Totale bruciato</span>
        <strong class="burn-value" id="${key}-v114-total">${c.total}</strong>
        <small class="burn-note">${c.totalNote}</small>
      </div>`;
    section.dataset.dailyTotalVisible='v114';
  }

  function boot(){build('wld');build('orai');}
  if(document.readyState==='loading') document.addEventListener('DOMContentLoaded',boot,{once:true});
  else boot();
  setTimeout(boot,300);
  setTimeout(boot,1200);
})();


