/* ===== JS originale 71/107: universal-preview-v146-script ===== */

(() => {
  'use strict';
  if (window.__UNIVERSAL_PREVIEW_V146__) return;
  window.__UNIVERSAL_PREVIEW_V146__ = true;

  const root = document.documentElement;
  const ua = String(navigator.userAgent || '');
  const platform = String(navigator.platform || '');
  const touch = Number(navigator.maxTouchPoints || 0);
  const isiPad = /iPad/i.test(ua) || (platform === 'MacIntel' && touch > 1);
  const isiPhone = /iPhone|iPod/i.test(ua);
  const isAndroid = /Android/i.test(ua);
  const isWindows = /Windows/i.test(ua) || /^Win/i.test(platform);
  const isMac = !isiPad && (/Macintosh|Mac OS X/i.test(ua) || /^Mac/i.test(platform));
  const isChromeOS = /CrOS/i.test(ua);
  const isLinux = !isAndroid && /Linux/i.test(ua);

  const os = isiPad ? 'ipados' : isiPhone ? 'ios' : isAndroid ? 'android' : isWindows ? 'windows' : isMac ? 'macos' : isChromeOS ? 'chromeos' : isLinux ? 'linux' : 'other';
  root.dataset.previewOs = os;
  root.dataset.universalPreview = 'v146';

  let raf = 0;
  function syncViewport() {
    cancelAnimationFrame(raf);
    raf = requestAnimationFrame(() => {
      const vv = window.visualViewport;
      const h = Math.max(1, Math.round(vv?.height || window.innerHeight || root.clientHeight || 1));
      const w = Math.max(1, Math.round(vv?.width || window.innerWidth || root.clientWidth || 1));
      root.style.setProperty('--universal-vh', h + 'px');
      root.style.setProperty('--universal-vw', w + 'px');
      root.dataset.previewViewport = w + 'x' + h;
    });
  }

  let resizeTimer = 0;
  function refreshCharts() {
    clearTimeout(resizeTimer);
    resizeTimer = setTimeout(() => {
      try { window.dispatchEvent(new Event('resize')); } catch (_) {}
    }, 80);
  }

  function wake() {
    syncViewport();
    refreshCharts();
  }

  syncViewport();
  window.addEventListener('resize', syncViewport, { passive: true });
  window.addEventListener('orientationchange', wake, { passive: true });
  window.addEventListener('pageshow', wake, { passive: true });
  window.addEventListener('focus', wake, { passive: true });
  window.visualViewport?.addEventListener('resize', wake, { passive: true });
  window.visualViewport?.addEventListener('scroll', syncViewport, { passive: true });
  document.addEventListener('visibilitychange', () => { if (!document.hidden) wake(); }, { passive: true });

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', wake, { once: true });
  } else {
    wake();
  }
})();


