 function clock(ms=Date.now()){try{return new Intl.DateTimeFormat('it-IT',{hour:'2-digit',minute:'2-digit',second:'2-digit',timeZone:'Europe/Rome'}).format(new Date(ms));}catch(_){return new Date(ms).toLocaleTimeString('it-IT');}}
 function dayKey(){try{return new Intl.DateTimeFormat('en-CA',{year:'numeric',month:'2-digit',day:'2-digit',timeZone:'Europe/Rome'}).format(new Date());}catch(_){return new Date().toISOString().slice(0,10);}}
 function num(v){let s=String(v??'').trim().replace(/\s/g,'');if(!s)return null;if(s.includes(',')&&s.includes('.'))s=s.lastIndexOf(',')>s.lastIndexOf('.')?s.replace(/\./g,'').replace(',','.'):s.replace(/,/g,'');else if(s.includes(','))s=s.replace(',','.');s=s.replace(/[^0-9+\-.eE]/g,'');const n=Number(s);return Number.isFinite(n)?n:null;}
