/* ===== JS originale 74/107: ore-absolute-percent-v163 ===== */

(()=>{
  'use strict';
  if (window.__ORE_ABS_PERCENT_V163__) return;
  window.__ORE_ABS_PERCENT_V163__ = true;

  function parseNum(raw){
    let s=String(raw||'').trim().replace(/\s/g,'').replace(/[−–—]/g,'-');
    s=s.replace(/[^0-9+\-.,]/g,'');
    if(!s) return NaN;
    if(s.includes(',')&&s.includes('.')){
      s=s.lastIndexOf(',')>s.lastIndexOf('.')?s.replace(/\./g,'').replace(',','.'):s.replace(/,/g,'');
    }else if(s.includes(',')) s=s.replace(',','.');
    const n=Number(s); return Number.isFinite(n)?n:NaN;
  }
  function fmt(v,d=3){
    return new Intl.NumberFormat('it-IT',{minimumFractionDigits:d,maximumFractionDigits:d,useGrouping:false}).format(Math.abs(v));
  }
  function fmtPct(v){
    return new Intl.NumberFormat('it-IT',{minimumFractionDigits:2,maximumFractionDigits:2,useGrouping:false}).format(Math.abs(v));
  }
  function pctFromText(text){
    const s=String(text||'').replace(/[−–—]/g,'-');
    const all=[...s.matchAll(/([+\-])\s*(\d+(?:[.,]\d+)?)\s*%/g)];
    if(!all.length) return NaN;
    const m=all[all.length-1];
    const n=parseNum(m[2]);
    return Number.isFinite(n)?(m[1]==='-'?-Math.abs(n):Math.abs(n)):NaN;
  }
  function currentPrice(){
    const el=document.getElementById('ore-price');
    if(!el) return NaN;
    const m=String(el.textContent||'').match(/\d[\d.,]*/);
    return m?parseNum(m[0]):NaN;
  }
  function quoteUnit(){
    const t=String(document.getElementById('ore-price')?.textContent||'').toUpperCase();
    return t.includes('USDT')?'USDT':(t.includes('USD')?'USD':'USDT');
  }
  function sync(){
    if(document.body?.classList.contains('prices-hidden')) return;
    const el=document.getElementById('ore-change');
    if(!el) return;
    const pct=pctFromText(el.textContent);
    const price=currentPrice();
    if(!Number.isFinite(pct)||!Number.isFinite(price)||price<=0||pct<=-99.99) return;

    const open=price/(1+pct/100);
    const delta=price-open;
    if(!Number.isFinite(delta)) return;
    const up=pct>=0;
    const sign=up?'+':'−';
    const next=`${sign}${fmt(delta,3)} ${quoteUnit()}   ${sign}${fmtPct(pct)}% 24h`;
    if(el.textContent!==next) el.textContent=next;
    el.classList.toggle('positive',up);
    el.classList.toggle('negative',!up);
  }

  function start(){
    sync();
    window.setInterval(()=>{if(!document.hidden)sync();},1200);
  }
  if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',start,{once:true});else start();
  window.addEventListener('pageshow',sync,{passive:true});
  window.addEventListener('focus',sync,{passive:true});
  document.addEventListener('visibilitychange',()=>{if(!document.hidden)sync();},{passive:true});
})();


