/* ===== JS originale 83/107: v178-chart-touch-crosshair-adapter ===== */

(() => {
  'use strict';

  const ids = [
    'altcoinIndexHistoryCanvas',
    'fearGreedHistoryCanvas',
    'btcRainbowHistoryCanvas',
    'ethRainbowHistoryCanvas'
  ];

  function attach(canvas){
    if(!canvas || canvas.dataset.v178TouchReady === '1') return;
    canvas.dataset.v178TouchReady = '1';

    function sendPoint(touch){
      if(!touch) return;
      const ev = new MouseEvent('mousemove', {
        bubbles:true,
        cancelable:true,
        clientX:touch.clientX,
        clientY:touch.clientY,
        screenX:touch.screenX || 0,
        screenY:touch.screenY || 0,
        view:window
      });
      canvas.dispatchEvent(ev);
    }

    canvas.addEventListener('touchstart', e => {
      sendPoint(e.touches && e.touches[0]);
    }, {passive:true});

    canvas.addEventListener('touchmove', e => {
      sendPoint(e.touches && e.touches[0]);
    }, {passive:true});

    canvas.addEventListener('pointerdown', e => {
      if(e.pointerType === 'touch'){
        const ev = new MouseEvent('mousemove', {
          bubbles:true,
          cancelable:true,
          clientX:e.clientX,
          clientY:e.clientY,
          view:window
        });
        canvas.dispatchEvent(ev);
      }
    }, {passive:true});
  }

  function init(){
    ids.forEach(id => attach(document.getElementById(id)));
  }

  if(document.readyState === 'loading'){
    document.addEventListener('DOMContentLoaded', init, {once:true});
  } else {
    init();
  }

  window.addEventListener('pageshow', init);
})();


