/* ===== JS originale 86/107: v225-orderbook-pulse-bootstrap ===== */

(function(){
  'use strict';
  function ensurePulse(el){
    if (!el) return;
    el.classList.add('pulse');
    if (el.dataset.dir !== 'up' && el.dataset.dir !== 'down') el.dataset.dir = 'up';
    el.style.setProperty('display', 'inline-flex', 'important');
    el.style.setProperty('visibility', 'visible', 'important');
    el.style.setProperty('opacity', '1', 'important');
    const svg = el.querySelector('.orderbook-direction-svg');
    if (svg) {
      svg.style.setProperty('display', 'block', 'important');
      svg.style.setProperty('visibility', 'visible', 'important');
      svg.style.setProperty('opacity', '1', 'important');
    }
    const arrow = el.querySelector('.orderbook-direction-arrow');
    if (arrow && !arrow.getAttribute('d')) {
      arrow.setAttribute('d', 'M32 23.5 L40.2 37.2 H23.8 Z');
    }
  }
  function boot(root){
    (root || document).querySelectorAll?.('.orderbook-direction').forEach(ensurePulse);
  }
  function start(){
    boot(document);
    try {
      const mo = new MutationObserver(mutations => {
        for (const m of mutations) {
          for (const node of m.addedNodes || []) {
            if (!node || node.nodeType !== 1) continue;
            if (node.matches && node.matches('.orderbook-direction')) ensurePulse(node);
            boot(node);
          }
        }
      });
      mo.observe(document.body, { childList: true, subtree: true });
    } catch (_) {}
    setInterval(() => boot(document), 2500);
  }
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', start, { once:true });
  else start();
})();


