/* ===== JS originale 88/107: v257-long-short-compact-all-crypto-js ===== */

(function(){
  'use strict';

  const SYMBOL_BY_KEY = {
    btc:'BTCUSDT', eth:'ETHUSDT', bnb:'BNBUSDT', sol:'SOLUSDT', ray:'RAYUSDT',
    inj:'INJUSDT', ore:'OREUSD', tai:'TAIUSD', virtual:'VIRTUALUSDT', wld:'WLDUSDT',
    orai:'ORAIUSD', tao:'TAOUSDT', lunc:'LUNCUSDT', luna:'LUNAUSDT'
  };
  const KEY_BY_SYMBOL = Object.fromEntries(Object.entries(SYMBOL_BY_KEY).map(([k,v])=>[v,k]));
  const state = Object.create(null);

  function safeNotional(rows){
    if(!Array.isArray(rows)) return 0;
    let total=0;
    for(const row of rows){
      const p=Number(row && row[0]);
      const q=Number(row && row[1]);
      if(Number.isFinite(p) && p>0 && Number.isFinite(q) && q>0) total += p*q;
    }
    return total;
  }

  function createForCard(card){
    if(!card || card.querySelector('.long-short-compact-v257')) return;
    const key=(card.id||'').replace(/-market$/,'');
    if(!SYMBOL_BY_KEY[key]) return;
    const row=document.createElement('div');
    row.className='long-short-compact-v257';
    row.dataset.key=key;
    row.dataset.live='false';
    row.setAttribute('role','status');
    row.setAttribute('aria-live','polite');
    row.title='Pressione LONG/SHORT LIVE calcolata dalla profondità dell’orderbook';
    row.innerHTML='<span class="ls-dots-v260 ls-dots-long-v260" aria-hidden="true"><i class="ls-dot-v260"></i><i class="ls-dot-v260"></i><i class="ls-dot-v260"></i><i class="ls-dot-v260"></i><i class="ls-dot-v260"></i></span><span class="ls-long-v257">LONG <b>--%</b></span><span class="ls-sep-v257">|</span><span class="ls-short-v257">SHORT <b>--%</b></span><span class="ls-dots-v260 ls-dots-short-v260" aria-hidden="true"><i class="ls-dot-v260"></i><i class="ls-dot-v260"></i><i class="ls-dot-v260"></i><i class="ls-dot-v260"></i><i class="ls-dot-v260"></i></span>';

    const metrics=card.querySelector('.metrics');
    const chartWrap=card.querySelector('.chart-wrap');
    if(metrics && metrics.parentNode===card) metrics.insertAdjacentElement('afterend',row);
    else if(chartWrap && chartWrap.parentNode===card) card.insertBefore(row,chartWrap);
    else card.appendChild(row);
  }

  function ensureRows(){
    document.querySelectorAll('.market-card').forEach(createForCard);
  }

  function paint(symbol,longPct){
    const key=KEY_BY_SYMBOL[symbol];
    if(!key) return;
    const card=document.getElementById(key+'-market');
    const row=card && card.querySelector('.long-short-compact-v257');
    if(!row) return;
    const lp=Math.max(0,Math.min(100,Math.round(longPct)));
    const sp=100-lp;
    const l=row.querySelector('.ls-long-v257 b');
    const s=row.querySelector('.ls-short-v257 b');
    if(l) l.textContent=lp+'%';
    if(s) s.textContent=sp+'%';
    row.dataset.live='true';
    row.setAttribute('aria-label','LONG '+lp+'%, SHORT '+sp+'%');
  }

  window.__updateLongShortV257=function(symbol,bids,asks){
    const bid=safeNotional(bids);
    const ask=safeNotional(asks);
    const total=bid+ask;
    if(!(total>0)) return;
    const raw=bid/total*100;
    const prev=state[symbol];
    // Smorzamento leggero per evitare lampeggi rapidi ma mantenere il dato LIVE.
    const next=Number.isFinite(prev) ? (prev*0.72 + raw*0.28) : raw;
    state[symbol]=next;
    paint(symbol,next);
  };

  ensureRows();
  if(document.readyState==='loading') document.addEventListener('DOMContentLoaded',ensureRows,{once:true});
  const observer=new MutationObserver(ensureRows);
  observer.observe(document.documentElement,{childList:true,subtree:true});
})();


