    const el = $('globalTotalDefiValue');
    const trend = $('globalTotalDefiTrend');
    const n = Number(value);
    const pct = Number(change24h);
    if (!pill || !el || !Number.isFinite(n) || n <= 0) return false;

    const previous = Number(pill.dataset.numericValue);
    let direction = 'neutral';
    if (Number.isFinite(previous) && previous > 0) {
      const deltaPct = ((n - previous) / previous) * 100;
      if (Math.abs(deltaPct) >= 0.000001) direction = deltaPct > 0 ? 'up' : 'down';
    }
    el.textContent = compactUsd(n);
    if (trend) trend.textContent = direction === 'up' ? 'SU' : direction === 'down' ? 'GIÙ' : 'STABILE';
    pill.dataset.numericValue = String(n);
