/* ===== JS originale 99/107: v315-cross-platform-chart-resize ===== */

(() => {
  'use strict';
  if (window.__DASHBOARD_CROSS_PLATFORM_V315__) return;
  window.__DASHBOARD_CROSS_PLATFORM_V315__ = true;
  let frame = 0;
  let retry = 0;
  const dimensionsV316 = new WeakMap();
  function sizeOne(chart, container) {
    if (!chart || !container || !container.isConnected) return false;
    const rect = container.getBoundingClientRect();
    const w = Math.round(rect.width);
    const h = Math.round(rect.height);
    // Never resize a display:none chart to 0x0.
    if (w < 25 || h < 25) return false;
    const dpr = window.devicePixelRatio || 1;
    const prev = dimensionsV316.get(chart);
    if (prev && prev.w === w && prev.h === h && prev.dpr === dpr) return true;
    try {
      chart.applyOptions({width:w, height:h});
      dimensionsV316.set(chart, {w, h, dpr});
      return true;
    } catch (_) { return false; }
  }
  function sync() {
    frame = 0;
    const tab = document.querySelector('.asset-tab.active[data-symbol]');
    if (!tab || !window.charts || !window.ASSETS) return;
    const symbol = tab.dataset.symbol;
    const b = window.charts[symbol];
    if (!b || !b.chart) return;
    const card = document.getElementById(window.ASSETS[symbol]?.key + '-market');
    if (!card || card.hidden || card.classList.contains('market-hidden')) return;
    sizeOne(b.chart, b.chartContainer || document.getElementById(window.ASSETS[symbol].key + '-chart'));
    Object.values(b.indicators || {}).forEach(i => sizeOne(i?.chart, i?.container));
    try { b.roundedCandlesV63?.schedule?.(); } catch (_) {}
  }
  function schedule() {
    if (document.hidden) return;
    if (frame) cancelAnimationFrame(frame);
    frame = requestAnimationFrame(sync);
  }
  function wake() {
    schedule();
    clearTimeout(retry);
    retry = setTimeout(schedule, 140);
  }
  document.addEventListener('click', e => {
    if (e.target.closest?.('.asset-tab[data-symbol], .timeframe-btn, [data-timeframe], .indicator-toggle')) wake();
  }, {passive:true, capture:true});
  window.addEventListener('resize', wake, {passive:true});
  window.addEventListener('orientationchange', wake, {passive:true});
  window.addEventListener('pageshow', wake, {passive:true});
  window.addEventListener('focus', wake, {passive:true});
  document.addEventListener('visibilitychange', () => { if (!document.hidden) wake(); }, {passive:true});
  window.visualViewport?.addEventListener('resize', wake, {passive:true});
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', wake, {once:true});
  else wake();
})();


