/* ===== JS originale 102/107: v349-native-copy-paste ===== */

(function(){
  'use strict';
  if(window.__V349_NATIVE_PASTE__)return;
  window.__V349_NATIVE_PASTE__=true;
  // Il browser gestisce già Ctrl/Cmd+V e il menu "Incolla" con pressione lunga.
  // Interveniamo soltanto quando il testo copiato comprende un importo con etichette
  // come "83.134,18 USDT", "$83,134.18", o "BTC: 83 134,18".
  function numberFromWebsite(raw){
    const text=String(raw||'').replace(/[\u2212\u2012\u2013\u2014]/g,'-').replace(/[\u200e\u200f\u2066-\u2069]/g,'');
    const hits=text.match(/[+-]?(?:\d[\d\s\u00a0\u202f.,'’]*\d|\d|[.,]\d+)(?:[eE][+-]?\d+)?/g);
    if(!hits||!hits.length)return null;
    for(let candidate of hits){
      // Elimina i raggruppamenti con spazi/apostrofi: il resto rimane come sul sito.
      candidate=candidate.replace(/[\s\u00a0\u202f'’]/g,'').replace(/^[+]/,'');
      if(!candidate||!/\d/.test(candidate))continue;
      // Se un sito copia un numero con separatori incompleti, non inventiamo valori.
      let check=candidate;
      const dot=check.lastIndexOf('.'),comma=check.lastIndexOf(',');
      if(dot>=0&&comma>=0){
        check=comma>dot?check.replace(/\./g,'').replace(',','.'):check.replace(/,/g,'');
      }else if(comma>=0)check=check.replace(',','.');
      if(!/^-?(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][+-]?\d+)?$/.test(check))continue;
      const n=Number(check);
      if(!Number.isFinite(n))continue;
      // I Futures non accettano margini, prezzi o leve negativi.
      if(n<0)continue;
      return candidate;
    }
    return null;
  }
  const selector='.v336-futures-surface input[data-field], .v330-converter-wrap input[data-role="amount"], .v325-crypto-converter-surface input[data-role="amount"], .v325-crypto-converter-surface input[data-role="rate"]';
  document.addEventListener('paste',function(event){
    const field=event.target;
    if(!(field instanceof HTMLInputElement)||!field.matches(selector)||field.disabled||field.readOnly)return;
    // Se il sistema non fornisce clipboardData, lasciamo lavorare l'incolla nativo.
    const copied=event.clipboardData&&event.clipboardData.getData('text/plain');
    if(!copied)return;
    const amount=numberFromWebsite(copied);
    if(amount===null)return; // Non alterare l'incolla nativo per contenuto non numerico.
    event.preventDefault();
    field.value=amount;
    // Attiva la logica già presente: calcoli LIVE/manuali e salvataggio locale V346.
    field.dispatchEvent(new Event('input',{bubbles:true}));
  },false);
})();


