/* ===== JS originale 104/107: v436-force-no-blue-border-crypto-tabs-runtime ===== */

(function(){
  function paintTab(tab){
    if(!tab || !tab.classList || !tab.classList.contains('asset-tab')) return;
    tab.style.setProperty('outline','none','important');
    tab.style.setProperty('outline-offset','0','important');
    tab.style.setProperty('border-color','transparent','important');
    tab.style.setProperty('box-shadow','none','important');
    tab.style.setProperty('-webkit-box-shadow','none','important');
    tab.style.setProperty('-webkit-tap-highlight-color','transparent','important');
    tab.style.setProperty('appearance','none','important');
    tab.style.setProperty('-webkit-appearance','none','important');
  }
  function paintAll(){
    document.querySelectorAll('.asset-tab').forEach(paintTab);
  }
  function onInteraction(ev){
    const tab = ev.target && ev.target.closest ? ev.target.closest('.asset-tab') : null;
    if(!tab) return;
    paintTab(tab);
    requestAnimationFrame(function(){ paintTab(tab); });
    setTimeout(function(){ paintTab(tab); }, 0);
    setTimeout(function(){ paintTab(tab); }, 60);
    setTimeout(function(){ paintTab(tab); }, 180);
  }
  document.addEventListener('DOMContentLoaded', paintAll, {once:true});
  window.addEventListener('load', paintAll, {once:true});
  document.addEventListener('pointerdown', onInteraction, true);
  document.addEventListener('click', onInteraction, true);
  document.addEventListener('touchstart', onInteraction, true);
  document.addEventListener('focusin', onInteraction, true);
  document.addEventListener('keydown', function(ev){
    if(ev.key === 'Enter' || ev.key === ' ' || ev.key === 'Spacebar') onInteraction(ev);
  }, true);
  const mo = new MutationObserver(function(mutations){
    let refresh = false;
    for(const m of mutations){
      if(m.type === 'attributes'){
        const el = m.target;
        if(el && el.classList && el.classList.contains('asset-tab')) {
          paintTab(el);
          refresh = true;
        }
      } else if(m.addedNodes && m.addedNodes.length) {
        refresh = true;
      }
    }
    if(refresh) paintAll();
  });
  mo.observe(document.documentElement, {subtree:true, childList:true, attributes:true, attributeFilter:['class','style','aria-selected']});
  setInterval(paintAll, 1000);
})();


