/* ===== JS originale 106/107: v441-follow-active-crypto-chart-timeframe-navigation ===== */

(function () {
  'use strict';
  const timeframeBar = document.getElementById('timeframes');
  const controls = timeframeBar ? timeframeBar.closest('nav.controls') : document.querySelector('nav.controls');
  const cards = Array.from(document.querySelectorAll('.market-grid > .market-card'));
  const tabs = Array.from(document.querySelectorAll('.asset-tab[aria-controls]'));
  if (!controls || !cards.length) return;

  function visible(card) {
    return !!card && !card.hidden && !card.classList.contains('market-hidden')
      && card.getAttribute('aria-hidden') !== 'true';
  }
  function activeCard() {
    const activeTab = tabs.find(tab => tab.getAttribute('aria-selected') === 'true')
      || tabs.find(tab => tab.classList.contains('active'));
    const match = activeTab && document.getElementById(activeTab.getAttribute('aria-controls'));
    if (match && visible(match)) return match;
    return cards.find(visible) || match || cards[0];
  }
  function placeControls() {
    const card = activeCard();
    const chart = card && card.querySelector('.chart-wrap');
    if (!chart) return;
    // Keep the ONE original nav and #timeframes alive, retaining click listeners.
    if (controls.parentNode !== card || controls.nextElementSibling !== chart) {
      card.insertBefore(controls, chart);
    }
  }
  let scheduled = false;
  function schedulePlacement() {
    if (scheduled) return;
    scheduled = true;
    requestAnimationFrame(function () {
      scheduled = false;
      placeControls();
    });
  }
  const observer = new MutationObserver(schedulePlacement);
  cards.forEach(card => observer.observe(card, {
    attributes: true, attributeFilter: ['class', 'hidden', 'aria-hidden']
  }));
  tabs.forEach(tab => observer.observe(tab, {
    attributes: true, attributeFilter: ['class', 'aria-selected']
  }));
  document.addEventListener('click', function (e) {
    if (e.target.closest && e.target.closest('.asset-tab[data-symbol]')) schedulePlacement();
  }, false);
  document.addEventListener('DOMContentLoaded', schedulePlacement, { once: true });
  window.addEventListener('load', schedulePlacement, { once: true });
  placeControls();
})();


