/* ===== JS originale 107/107: v451-top-200-market-runtime ===== */

(function(){
  'use strict';
  const q = id => document.getElementById(id);
  const menu=q('v442MenuButton'), drawer=q('v442MarketDrawer'), shade=q('v442MarketShade');
  const close=q('v442MarketClose'), dashboardNav=q('v442MarketDashboardNav'), marketNav=q('v442MarketNav');
  const rows=q('v442MarketRows'), status=q('v442MarketStatus'), count=q('v442MarketCount'), search=q('v442MarketSearch');
  if(!menu || !drawer || !shade || !rows) return;

  const SOURCE='https://api.coingecko.com/api/v3/coins/markets?vs_currency=usd&order=market_cap_desc&per_page=200&page=1&sparkline=true&price_change_percentage=1h,24h,7d';
  const SECONDARY='https://api.coinlore.net/api/tickers/?start=';
  const CACHE_KEY='dashboard_market_v473_top200_v1';
  const HISTORY_CACHE='dashboard_market_v472_history_v1';
  const CACHE_AGE=60*1000, AUTO_REFRESH=60*1000;

  let coins=[], fetchedAt=0, lastAttempt=0, loading=false, timer=null, firstOpened=false, previousFocus=null;
  let histories={}, historyQueue=[], historyBusy=false, historyFailures=0;
  const failedSymbols=new Set();
  const retryHistoryAt=new Map();
  try{histories=JSON.parse(localStorage.getItem(HISTORY_CACHE)||'{}')||{};}catch(_){histories={};}

  function historyKey(c){return String(c.symbol||'').trim().toUpperCase();}

  // V454: raccolta solo di prezzi osservati durante questa sessione, nessuno storico 7g.
  const liveSeries=new Map();
  function liveKey(c){return String(c.id||c.symbol||'').trim().toLowerCase();}
  function observeLivePrice(c){
    const price=Number(c.current_price), key=liveKey(c);
    if(!key||!Number.isFinite(price)||price<=0)return;
    const series=liveSeries.get(key)||[];
    const now=Date.now();
    if(!series.length || now-series[series.length-1].at>=8000){
      series.push({at:now,price});
    }else if(series[series.length-1].price!==price){
      series[series.length-1]={at:now,price};
    }
    while(series.length>45)series.shift();
    liveSeries.set(key,series);
  }

  // V457: Binance mini-ticker stream updates supported USDT pairs between API snapshots.
  // USDT is quoted as USDT, not an exact USD conversion; on-screen values for
  // streamed pairs are indicative USD-equivalent prices.
  let marketSocket=null, marketSocketRetry=null, marketRenderTimer=null, socketConnected=false;
  let streamedCount=0, lastStreamAt=0;
  const streamName='!miniTicker@arr';
  function streamStatus(){
    if(!document.body.classList.contains('v442-market-open'))return;
    if(socketConnected && Date.now()-lastStreamAt<30000){
      setStatus('LIVE Binance · '+streamedCount+' coppie USDT aggiornate · valori indicativi USD/USDT · altre crypto tramite CoinGecko/CoinLore ogni 60 s');
    }
  }
  function applyStream(data){
    if(!Array.isArray(data)||!coins.length)return;
    const bySymbol=new Map();
    coins.forEach(c=>{
      const key=String(c.symbol||'').toUpperCase();
      if(key && !bySymbol.has(key))bySymbol.set(key,c);
    });
    let touched=0;
    for(const entry of data){
      const pair=String(entry?.s||'');
      if(!pair.endsWith('USDT'))continue;
      const token=pair.slice(0,-4), c=bySymbol.get(token);
      if(!c)continue;
      const price=Number(entry.c), open=Number(entry.o);
      if(!Number.isFinite(price)||price<=0)continue;
      // Prefer data only if the current row uses a uniquely matched symbol.
      // Exclude stablecoins where USD/USDT fluctuations are not comparable.
      if(['USDT','USDC','DAI','TUSD','FDUSD','USDE','PYUSD'].includes(token))continue;
      c.current_price=price;
      if(Number.isFinite(open)&&open>0)c.price_change_percentage_24h=(price/open-1)*100;
      observeLivePrice(c);touched++;
    }
    if(!touched)return;
    streamedCount=touched; lastStreamAt=Date.now();
    if(!marketRenderTimer){
      marketRenderTimer=setTimeout(()=>{
        marketRenderTimer=null;
        if(document.body.classList.contains('v442-market-open')){render();streamStatus();}
      },1800);
    }
  }
  function connectMarketStream(){
    if(marketSocket||!document.body.classList.contains('v442-market-open')||!coins.length||typeof WebSocket==='undefined')return;
    try{
      const ws=new WebSocket('wss://stream.binance.com:9443/ws/'+streamName);
      marketSocket=ws;
      ws.onopen=()=>{socketConnected=true;streamStatus();};
      ws.onmessage=e=>{
        try{const payload=JSON.parse(e.data);applyStream(Array.isArray(payload)?payload:(payload?.data||[]));}catch(_){}
      };
      ws.onerror=()=>{socketConnected=false;try{ws.close();}catch(_){}};
      ws.onclose=()=>{
        socketConnected=false;
        if(marketSocket===ws)marketSocket=null;
        if(document.body.classList.contains('v442-market-open')){
          clearTimeout(marketSocketRetry);
          marketSocketRetry=setTimeout(connectMarketStream,10000);
        }
      };
    }catch(_){marketSocketRetry=setTimeout(connectMarketStream,10000);}
  }
  function disconnectMarketStream(){
    clearTimeout(marketSocketRetry);clearTimeout(marketRenderTimer);
    marketSocketRetry=null;marketRenderTimer=null;socketConnected=false;
    const ws=marketSocket;marketSocket=null;
    if(ws){ws.onclose=null;try{ws.close();}catch(_){}}
  }
  function nf(d=2){return new Intl.NumberFormat('it-IT',{maximumFractionDigits:d,minimumFractionDigits:0});}
  function fmtPrice(v){
    if(!Number.isFinite(v)) return '—';
    const dec=Math.abs(v)>=1000?2:Math.abs(v)>=1?2:Math.abs(v)>=0.01?4:Math.abs(v)>=0.0001?6:10;
    return new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:dec,minimumFractionDigits:Math.min(2,dec)}).format(v);
  }
  function fmtBig(v){
    if(!Number.isFinite(v)) return '—';
    return '$'+new Intl.NumberFormat('en-US',{notation:'compact',compactDisplay:'short',maximumFractionDigits:2}).format(v);
  }
  function fmtSupply(v){
    if(!Number.isFinite(v) || v<=0) return '—';
    return new Intl.NumberFormat('en-US',{notation:'compact',compactDisplay:'short',maximumFractionDigits:2}).format(v);
  }
  function setStatus(message,error=false){status.textContent=message;status.dataset.error=error?'true':'false';}
  function cacheRead(){
    try{
      const raw=localStorage.getItem(CACHE_KEY);
      if(!raw)return;
      const c=JSON.parse(raw);
      if(Array.isArray(c.coins)&&c.coins.length&&Number.isFinite(c.at)){
        coins=c.coins.slice(0,200); coins.forEach(observeLivePrice); fetchedAt=c.at;
      }
    }catch(_){ }
  }
  function cacheWrite(){try{localStorage.setItem(CACHE_KEY,JSON.stringify({at:fetchedAt,coins:coins}));}catch(_){}}
  function saveHistories(){
    try{
      const entries=Object.entries(histories).sort((a,b)=>(b[1]?.at||0)-(a[1]?.at||0)).slice(0,220);
      localStorage.setItem(HISTORY_CACHE,JSON.stringify(Object.fromEntries(entries)));
    }catch(_){ }
  }

  async function historyJson(url){
    const ctl=new AbortController(), tm=setTimeout(()=>ctl.abort(),12000);
    try{
      const response=await fetch(url,{mode:'cors',credentials:'omit',cache:'no-store',signal:ctl.signal});
      if(!response.ok) throw Error('HTTP '+response.status);
      return await response.json();
    }finally{clearTimeout(tm);}
  }

  function deriveHistory(points){
    const ordered=(points||[])
      .map(p=>({time:Number(p.time),price:Number(p.price)}))
      .filter(p=>Number.isFinite(p.time)&&Number.isFinite(p.price)&&p.price>0)
      .sort((a,b)=>a.time-b.time)
      .filter((p,i,a)=>i===0||p.time>a[i-1].time);
    // Almeno 24 osservazioni effettive distribuite su un arco di 24 ore.
    if(ordered.length<24 || ordered[ordered.length-1].time-ordered[0].time<86400)
      throw Error('Storico orario insufficiente');
    const samples=ordered.length>168
      ? Array.from({length:168},(_,i)=>ordered[Math.round(i*(ordered.length-1)/167)])
      : ordered;
    return {at:Date.now(),spark:samples.map(p=>p.price)};
  }

  async function getHistory(c){
    let error;
    // CoinGecko /markets con sparkline=true restituisce gia lo storico orario
    // in un'unica chiamata per tutte le Top 200.
    const already=c.sparkline_in_7d?.price;
    if(Array.isArray(already)&&already.filter(x=>Number(x)>0).length>=24){
      return {at:Date.now(),spark:already.map(Number).filter(v=>Number.isFinite(v)&&v>0)};
    }
    const symbol=historyKey(c);
    // Binance: 168 vere candele orarie per le coppie quotate USDT.
    // Non si inventa uno storico nei casi in cui la coppia non esiste.
    if(/^[A-Z0-9]{2,18}$/.test(symbol) && !['USDT','USDC','FDUSD','DAI'].includes(symbol)){
      try{
        const json=await historyJson('https://data-api.binance.vision/api/v3/klines?symbol='+encodeURIComponent(symbol+'USDT')+'&interval=1h&limit=168');
        if(!Array.isArray(json) || json.length<24 || !Array.isArray(json[0])) throw Error('Binance storico assente');
        return deriveHistory(json.map(k=>({time:Number(k[0])/1000,price:Number(k[4])})));
      }catch(e){error=e;}
    }
    if(/^[A-Z0-9]{2,18}$/.test(symbol)){
      try{
        const json=await historyJson('https://min-api.cryptocompare.com/data/v2/histohour?fsym='+encodeURIComponent(symbol)+'&tsym=USD&limit=168');
        if(json.Response==='Error'||!Array.isArray(json.Data?.Data)) throw Error(json.Message||'Storico CryptoCompare assente');
        return deriveHistory(json.Data.Data.map(p=>({time:p.time,price:p.close})));
      }catch(e){error=e;}
    }
    const id=String(c.id||'');
    if(id && !/^\\d+$/.test(id)){
      try{
        const json=await historyJson('https://api.coingecko.com/api/v3/coins/'+encodeURIComponent(id)+'/market_chart?vs_currency=usd&days=7');
        if(!Array.isArray(json.prices)) throw Error('Storico CoinGecko assente');
        return deriveHistory(json.prices.map(x=>({time:x[0]/1000,price:x[1]})));
      }catch(e){error=e;}
    }
    throw error||Error('Storico non disponibile');
  }

  function applyHistoricalData(c){
    const h=histories[historyKey(c)];
    if(!h || !Number.isFinite(h.at) || Date.now()-h.at>6*60*60*1000) return;
    if(Number.isFinite(h.change24d)) c.price_change_percentage_24d_in_currency=h.change24d;
    if(Array.isArray(h.spark) && h.spark.length>=24) c.sparkline_in_7d={price:h.spark};
  }

  function queueVisibleHistories(){

    if(!document.body.classList.contains('v442-market-open')) return;
    const viewport=q('v442MarketScroll')||drawer;
    const rect=viewport.getBoundingClientRect();
    const visibleKeys=[];
    const backgroundKeys=[];
    let first=0;
    Array.from(rows.querySelectorAll('tr.v442-market-row')).forEach(tr=>{
      const key=tr.dataset.historyKey;
      const c=coins.find(item=>historyKey(item)===key);
      if(!c || (Array.isArray(c.sparkline_in_7d?.price) && c.sparkline_in_7d.price.length>=24) || histories[key]?.at>Date.now()-6*60*60*1000 || historyQueue.includes(key) || (retryHistoryAt.get(key)||0)>Date.now()) return;
      const b=tr.getBoundingClientRect();
      const visible=(b.bottom>=rect.top && b.top<=rect.bottom+240)||first<20;
      first++;
      (visible?visibleKeys:backgroundKeys).push(key);
    });
    historyQueue.push(...visibleKeys, ...backgroundKeys);
    drainHistoryQueue();
  }

  async function drainHistoryQueue(){
    if(historyBusy) return;
    historyBusy=true;
    while(historyQueue.length && document.body.classList.contains('v442-market-open')){
      const key=historyQueue.shift();
      const c=coins.find(item=>historyKey(item)===key);
      if(!c || histories[key]?.at>Date.now()-6*60*60*1000 || (retryHistoryAt.get(key)||0)>Date.now()) continue;
      try{
        histories[key]=await getHistory(c);
        failedSymbols.delete(key);retryHistoryAt.delete(key);
        coins.filter(x=>historyKey(x)===key).forEach(applyHistoricalData);
        saveHistories();
        render(false);
      }catch(e){failedSymbols.add(key);retryHistoryAt.set(key,Date.now()+3*60*1000);historyFailures++;}
      await new Promise(resolve=>setTimeout(resolve,700));
    }
    historyBusy=false;
    if(historyFailures>0 && historyFailures===failedSymbols.size && historyFailures>=5){
      setStatus('Prezzi disponibili · alcune serie non sono raggiungibili per '+historyFailures+' crypto. Nuovo tentativo automatico al prossimo aggiornamento.', true);
    }
  }

  let historyScrollTimer;


  async function fallbackMarket(){
    const pages=await Promise.all([0,100].map(async start=>{
      const res=await fetch(SECONDARY+start+'&limit=100',{mode:'cors',cache:'no-store'});
      if(!res.ok) throw new Error('CoinLore HTTP '+res.status);
      const payload=await res.json();
      if(!Array.isArray(payload.data)) throw new Error('Risposta CoinLore non valida');
      return payload.data;
    }));
    return pages.flat().map((c,i)=>({
      id:String(c.id||c.symbol||i),
      name:c.name||c.symbol||'—',
      symbol:c.symbol||'—',
      market_cap_rank:Number(c.rank)||i+1,
      current_price:Number(c.price_usd),
      market_cap:Number(c.market_cap_usd),
      total_volume:Number(c.volume24),
      circulating_supply:Number(c.csupply),
      max_supply:Number(c.msupply),
      price_change_percentage_1h_in_currency:c.percent_change_1h==null||c.percent_change_1h===''?null:Number(c.percent_change_1h),
      price_change_percentage_24h:c.percent_change_24h==null||c.percent_change_24h===''?null:Number(c.percent_change_24h),
      price_change_percentage_7d_in_currency:c.percent_change_7d==null||c.percent_change_7d===''?null:Number(c.percent_change_7d),
      price_change_percentage_24d_in_currency:null,
      sparkline_in_7d:null,
      image:(c.symbol?('https://assets.coincap.io/assets/icons/'+String(c.symbol).trim().toLowerCase()+'@2x.png'):null)
    })).sort((a,b)=>(Number(a.market_cap_rank)||999999)-(Number(b.market_cap_rank)||999999)).slice(0,200);
  }

  function logoFallback(coin){
    const span=document.createElement('span');
    span.className='v442-market-fallback-logo';
    span.textContent=String(coin.symbol||coin.name||'?').trim().slice(0,1).toUpperCase()||'?';
    span.title=(coin.name||coin.symbol||'crypto')+' · logo non disponibile';
    return span;
  }
  function logoCandidates(coin){
    const symbol=String(coin.symbol||'').trim().toLowerCase();
    const id=String(coin.id||'').trim().toLowerCase();
    const primary=typeof coin.image==='string'&&coin.image.startsWith('https://')?coin.image:null;
    const list=[];
    if(primary) list.push(primary);
    if(symbol){
      list.push('https://assets.coincap.io/assets/icons/'+symbol+'@2x.png');
      list.push('https://cdn.jsdelivr.net/gh/spothq/cryptocurrency-icons@master/128/color/'+symbol+'.png');
      list.push('https://cdn.jsdelivr.net/gh/spothq/cryptocurrency-icons@master/32/color/'+symbol+'.png');
      list.push('https://raw.githubusercontent.com/spothq/cryptocurrency-icons/master/128/color/'+symbol+'.png');
      list.push('https://raw.githubusercontent.com/spothq/cryptocurrency-icons/master/32/color/'+symbol+'.png');
      list.push('https://cryptoicons.org/api/icon/'+symbol+'/200');
    }
    if(id && id!==symbol){
      list.push('https://coin-images.coingecko.com/coins/images/'+id+'/large.png');
    }
    return [...new Set(list.filter(Boolean))];
  }
  function buildLogoImage(coin){
    const candidates=logoCandidates(coin);
    if(!candidates.length) return logoFallback(coin);
    const img=document.createElement('img');
    img.className='v442-market-logo';
    img.alt='';
    img.loading='eager';
    img.decoding='async';
    img.referrerPolicy='no-referrer';
    img.title=(coin.name||coin.symbol||'crypto')+' · logo';
    let index=0;
    const tryNext=()=>{
      if(index>=candidates.length){
        img.replaceWith(logoFallback(coin));
        return;
      }
      img.src=candidates[index++];
    };
    img.onerror=()=>tryNext();
    img.onload=()=>img.classList.add('is-ready');
    tryNext();
    return img;
  }
  function iconFor(coin){
    const holder=document.createElement('span');holder.className='v442-market-symbol-wrap';
    holder.appendChild(buildLogoImage(coin));
    const meta=document.createElement('span'); meta.className='v442-market-coin';
    const name=document.createElement('span'); name.className='v442-market-coin-name'; name.textContent=coin.name||'—';
    const symbol=document.createElement('span'); symbol.className='v442-market-coin-symbol'; symbol.textContent=String(coin.symbol||'').toUpperCase();
    meta.appendChild(name); meta.appendChild(symbol); holder.appendChild(meta);
    return holder;
  }

  function quickSeriesFromChanges(coin){
    const current=Number(coin.current_price);
    if(!Number.isFinite(current)||current<=0) return [];
    const h1=Number.isFinite(Number(coin.price_change_percentage_1h_in_currency))?Number(coin.price_change_percentage_1h_in_currency):null;
    const h24=Number.isFinite(Number(coin.price_change_percentage_24h))?Number(coin.price_change_percentage_24h):null;
    const d7raw=coin.price_change_percentage_7d_in_currency ?? coin.price_change_percentage_7d;
    const d7=Number.isFinite(Number(d7raw))?Number(d7raw):null;
    const anchorPoints=[];
    const safeBack=(pct)=> current/(1+(pct/100));
    if(d7!==null && Math.abs(100+d7)>0.00001) anchorPoints.push({x:0, y:safeBack(d7)});
    if(h24!==null && Math.abs(100+h24)>0.00001) anchorPoints.push({x:0.72, y:safeBack(h24)});
    if(h1!==null && Math.abs(100+h1)>0.00001) anchorPoints.push({x:0.93, y:safeBack(h1)});
    anchorPoints.push({x:1, y:current});
    if(anchorPoints.length<2) return Array.from({length:24},()=>current);
    const result=[];
    const total=32;
    for(let i=0;i<total;i++){
      const t=i/(total-1);
      let left=anchorPoints[0], right=anchorPoints[anchorPoints.length-1];
      for(let j=0;j<anchorPoints.length-1;j++){
        if(t>=anchorPoints[j].x && t<=anchorPoints[j+1].x){ left=anchorPoints[j]; right=anchorPoints[j+1]; break; }
      }
      const span=Math.max(right.x-left.x,1e-6);
      const local=(t-left.x)/span;
      const ease=local*local*(3-2*local);
      result.push(left.y+(right.y-left.y)*ease);
    }
    return result.filter(v=>Number.isFinite(v)&&v>0);
  }

  function sentimentIcon(kind){
    if(kind==='bull' || kind==='bear'){
      const img=document.createElement('img');
      img.className='v451-sentiment-icon v473-sentiment-animal';
      img.src=kind==='bull'?'data:image/png;base64,':'data:image/png;base64,';
      img.alt='';
      img.setAttribute('aria-hidden','true');
      img.decoding='async';
      return img;
    }
    const span=document.createElement('span');
    span.className='v451-sentiment-icon v473-sentiment-neutral';
    span.textContent='•';
    span.setAttribute('aria-hidden','true');
    return span;
  }

  function sparkChart(coin){
    const historical = Array.isArray(coin.sparkline_in_7d?.price)
      ? coin.sparkline_in_7d.price.map(Number).filter(v=>Number.isFinite(v)&&v>0) : [];
    const realtime = (liveSeries.get(liveKey(coin))||[]).map(p=>p.price).filter(v=>Number.isFinite(v)&&v>0);
    const current=Number(coin.current_price);
    const quick=quickSeriesFromChanges(coin);
    const series=historical.length>=24
      ? [...historical.slice(-168), ...(realtime.length?realtime.slice(-8):Number.isFinite(current)&&current>0?[current]:[])]
      : (quick.length>=8 ? quick : (Number.isFinite(current)&&current>0?Array.from({length:24},()=>current):[]));
    if(series.length===0){
      const missing=document.createElement('span');
      missing.className='v442-spark-empty';
      missing.textContent='Grafico non disponibile';
      missing.title='La fonte dati non ha ancora restituito prezzi sufficienti';
      return missing;
    }
    // Dal primo prezzo reale mostriamo una linea orizzontale neutra:
    // non inventiamo valori precedenti né movimenti di mercato.
    const values=series.length===1?[series[0],series[0]]:series.slice(-176);
    const lo=Math.min(...values), hi=Math.max(...values), range=Math.max(hi-lo,Math.abs(hi)*0.000001,1e-12);
    const rising=values[values.length-1]>=values[0];
    const color=series.length===1||hi===lo?'#91a4bd':rising?'#16c784':'#ea3943';
    const svgNS='http://www.w3.org/2000/svg'; const svg=document.createElementNS(svgNS,'svg');
    svg.setAttribute('viewBox','0 0 120 44'); svg.setAttribute('preserveAspectRatio','none'); svg.setAttribute('role','img');
    svg.setAttribute('aria-label','Mini grafico storico di '+String(coin.name||coin.symbol||'criptovaluta')+' con serie iniziale immediata e aggiornamenti live');
    svg.setAttribute('class','v442-market-spark v449-market-sparkline');
    svg.setAttribute('title',(historical.length>=24?'Storico reale 7 giorni':'Serie iniziale immediata')+' · '+values.length+' punti');
    const points=values.map((v,i)=>({x:3+(i/(values.length-1))*114,y:39-34*(v-lo)/range}));
    const fmt=n=>n.toFixed(2);
    let d='M '+fmt(points[0].x)+' '+fmt(points[0].y);
    for(let i=0;i<points.length-1;i++){
      const p0=points[Math.max(0,i-1)], p1=points[i], p2=points[i+1], p3=points[Math.min(points.length-1,i+2)];
      const c1x=p1.x+(p2.x-p0.x)/6, c2x=p2.x-(p3.x-p1.x)/6;
      const c1y=p1.y+(p2.y-p0.y)/6, c2y=p2.y-(p3.y-p1.y)/6;
      d+=' C '+fmt(c1x)+' '+fmt(c1y)+' '+fmt(c2x)+' '+fmt(c2y)+' '+fmt(p2.x)+' '+fmt(p2.y);
    }
    const line=document.createElementNS(svgNS,'path');
    line.setAttribute('d',d); line.setAttribute('fill','none'); line.setAttribute('stroke',color); line.setAttribute('stroke-width','2.2'); line.setAttribute('stroke-linejoin','round'); line.setAttribute('stroke-linecap','round'); line.setAttribute('vector-effect','non-scaling-stroke');
    svg.appendChild(line);
    const last=points[points.length-1], dot=document.createElementNS(svgNS,'circle');
    dot.setAttribute('cx',fmt(last.x)); dot.setAttribute('cy',fmt(last.y)); dot.setAttribute('r','2.35'); dot.setAttribute('fill',color); svg.appendChild(dot);
    return svg;
  }

  function pctEl(value,label){
    const el=document.createElement('span');
    const n=Number(value);
    el.className='v451-pct';
    if(value===null || value===undefined || value==='' || !Number.isFinite(n)){
      el.textContent='—'; el.title=label+' non disponibile dalla fonte dati'; el.classList.add('neu');
      return el;
    }
    el.textContent=(n>0?'+':'')+nf(2).format(n)+'%';
    el.classList.add(n>0?'pos':n<0?'neg':'neu');
    return el;
  }

  function supplyCell(coin){
    const wrap=document.createElement('div'); wrap.className='v451-supply';
    const text=document.createElement('div'); text.className='v451-supply-text';
    const circ=Number(coin.circulating_supply); const max=Number(coin.max_supply);
    const symbol=String(coin.symbol||'').toUpperCase();
    text.textContent=Number.isFinite(circ)&&circ>0 ? (fmtSupply(circ)+' '+symbol) : '—';
    wrap.appendChild(text);
    if(Number.isFinite(circ) && circ>0 && Number.isFinite(max) && max>0){
      const bar=document.createElement('div'); bar.className='v451-supply-bar';
      const fill=document.createElement('span'); fill.style.width=Math.max(0,Math.min(100,(circ/max)*100)).toFixed(1)+'%'; bar.appendChild(fill);
      wrap.appendChild(bar);
      const sub=document.createElement('div'); sub.className='v451-supply-sub'; sub.textContent=(circ/max*100).toFixed(1)+'% di max supply'; wrap.appendChild(sub);
    } else {
      const sub=document.createElement('div'); sub.className='v451-supply-sub'; sub.textContent='Supply max non disponibile'; wrap.appendChild(sub);
    }
    return wrap;
  }

  function sentimentCell(coin){
    // Indicatore tecnico dinamico basato sulle variazioni disponibili, non su social/news.
    const span=document.createElement('span');
    const num=v=>v===null||v===undefined||v===''?null:(Number.isFinite(Number(v))?Number(v):null);
    const h1=num(coin.price_change_percentage_1h_in_currency);
    const h24=num(coin.price_change_percentage_24h);
    const d7=num(coin.price_change_percentage_7d_in_currency ?? coin.price_change_percentage_7d);
    const live=liveSeries.get(liveKey(coin))||[];
    const first=live.length>1?Number(live[0].price):null;
    const last=live.length>1?Number(live[live.length-1].price):null;
    const momentum=first>0&&Number.isFinite(last)?((last/first)-1)*100:null;
    const parts=[];
    if(h1!==null)parts.push({w:1.0,val:Math.tanh(h1/1.5)});
    if(h24!==null)parts.push({w:1.5,val:Math.tanh(h24/4)});
    if(d7!==null)parts.push({w:0.8,val:Math.tanh(d7/10)});
    if(momentum!==null)parts.push({w:1.2,val:Math.tanh(momentum/0.5)});
    let label='Non disponibile',cls='neutral',iconKind='neutral';
    if(parts.length){
      const weight=parts.reduce((sum,p)=>sum+p.w,0);
      const score=parts.reduce((sum,p)=>sum+p.val*p.w,0)/weight;
      label='Neutrale';
      if(score>=0.16){label='Rialzista';cls='up';iconKind='bull';}
      else if(score<=-0.16){label='Ribassista';cls='down';iconKind='bear';}
    }
    span.className='v451-sentiment '+cls;
    span.appendChild(sentimentIcon(iconKind));
    const text=document.createElement('span');
    text.className='v451-sentiment-text';
    text.textContent=label;
    span.appendChild(text);
    span.title='Segnale tecnico dinamico (non sentiment social): variazioni 1h, 24h, 7g e momentum live quando disponibili; aggiornato con i dati ricevuti';
    span.setAttribute('aria-label','Segnale market: '+label);
    return span;
  }

  function cell(row,content,cls,label){ const td=document.createElement('td'); if(cls)td.className=cls; if(label)td.dataset.label=label; if(typeof content==='string') td.textContent=content; else td.appendChild(content); row.appendChild(td); return td; }

  function render(scheduleHistory=true){
    const query=search.value.trim().toLocaleLowerCase('it');
    const filtered=coins.filter(c=>!query || (String(c.name||'')+' '+String(c.symbol||'')+' '+String(c.id||'')).toLocaleLowerCase('it').includes(query));
    count.textContent=filtered.length+' / '+coins.length;
    const frag=document.createDocumentFragment();
    if(!filtered.length){
      const tr=document.createElement('tr'), td=document.createElement('td');
      td.colSpan=11; td.className='v442-empty-row'; td.textContent=coins.length?'Nessuna criptovaluta trovata.':'Nessun dato disponibile. Market riprova automaticamente.'; tr.appendChild(td); frag.appendChild(tr);
    } else {
      for(let i=0;i<filtered.length;i++){
        const coin=filtered[i], tr=document.createElement('tr');
        tr.className='v442-market-row'; tr.dataset.historyKey=historyKey(coin);
        cell(tr, String(coin.market_cap_rank||i+1));
        cell(tr, iconFor(coin));

        const priceWrap=document.createElement('span');
        priceWrap.className='v442-market-price';
        priceWrap.appendChild(document.createTextNode(fmtPrice(Number(coin.current_price))));
        const change24=Number(coin.price_change_percentage_24h);
        priceWrap.classList.add(Number.isFinite(change24)?(change24>0?'v447-price-up':change24<0?'v447-price-down':'v447-price-neutral'):'v447-price-neutral');
        if(Number.isFinite(change24)){
          const sub=document.createElement('small');
          sub.className=change24>0?'v442-market-change-up':change24<0?'v442-market-change-down':'v447-price-neutral';
          sub.textContent=(change24>0?'+':'')+nf(2).format(change24)+'% · 24h';
          priceWrap.appendChild(sub);
        }
        cell(tr, priceWrap, null, 'Prezzo');
        cell(tr, pctEl(coin.price_change_percentage_1h_in_currency,'1h'), 'v445-pct', '1h');
        cell(tr, pctEl(coin.price_change_percentage_24h,'24h'), 'v445-pct', '24h');
        cell(tr, pctEl(coin.price_change_percentage_7d_in_currency ?? coin.price_change_percentage_7d,'7g'), 'v445-pct', '7g');
        cell(tr, fmtBig(Number(coin.market_cap)), 'v442-market-money', 'Market Cap');
        cell(tr, fmtBig(Number(coin.total_volume)), 'v442-market-money', 'Volume (24h)');
        cell(tr, supplyCell(coin), null, 'Supply');
        cell(tr, sentimentCell(coin), null, 'Sentiment');
        cell(tr, sparkChart(coin), 'v453-live-chart', 'Mini grafico storico');
        
        frag.appendChild(tr);
      }
    }
    rows.replaceChildren(frag);
    if(scheduleHistory) queueVisibleHistories();
  }

  async function fetchMarket(force=false){
    if(loading) return;
    if(!force && coins.length && Date.now()-fetchedAt<CACHE_AGE){
      render();
      setStatus('Dati in cache · '+coins.length+' crypto · salvati alle '+new Date(fetchedAt).toLocaleTimeString('it-IT',{hour:'2-digit',minute:'2-digit'})+' · aggiornamento entro 60 s');
      return;
    }
    loading=true; lastAttempt=Date.now();
    setStatus(coins.length?'Aggiornamento market in corso…':'Caricamento market Top 200 in stile avanzato…');
    const controller=new AbortController(); const timeout=setTimeout(()=>controller.abort(),18000);
    try{
      const response=await fetch(SOURCE,{headers:{'Accept':'application/json'},mode:'cors',credentials:'omit',cache:'no-store',signal:controller.signal});
      if(!response.ok) throw new Error('HTTP '+response.status+(response.status===429?' · limite temporaneo di richieste':''));
      const data=await response.json();
      if(!Array.isArray(data) || !data.length) throw new Error('Nessun risultato valido ricevuto');
      const previousHistory=new Map(coins.filter(c=>Array.isArray(c.sparkline_in_7d?.price)&&c.sparkline_in_7d.price.length>=24).map(c=>[historyKey(c),c.sparkline_in_7d]));
      coins=data.slice(0,200).filter(c=>c && typeof c==='object' && typeof c.name==='string').map(c=>({
        ...c,
        image:(typeof c.image==='string'&&c.image.startsWith('https://')?c.image:(c.symbol?'https://assets.coincap.io/assets/icons/'+String(c.symbol).trim().toLowerCase()+'@2x.png':null)),
        price_change_percentage_1h_in_currency: Number.isFinite(Number(c.price_change_percentage_1h_in_currency)) ? Number(c.price_change_percentage_1h_in_currency) : null,
        circulating_supply: Number(c.circulating_supply),
        max_supply: Number(c.max_supply),
        sparkline_in_7d:(Array.isArray(c.sparkline_in_7d?.price)&&c.sparkline_in_7d.price.length>=24)
          ? c.sparkline_in_7d : (previousHistory.get(historyKey(c))||null)
      }));
      coins.forEach(c=>{applyHistoricalData(c);observeLivePrice(c);});
      coins.sort((a,b)=>(Number(a.market_cap_rank)||999999)-(Number(b.market_cap_rank)||999999));
      fetchedAt=Date.now(); cacheWrite(); render(); connectMarketStream();
      setStatus('CoinGecko · '+coins.length+' crypto · loghi aggiornati · grafici storici immediati · quotazioni ogni 60 s');
    }catch(err){
      try{
        const alternative=await fallbackMarket();
        if(alternative.length){
          const previousHistory=new Map(coins.filter(c=>Array.isArray(c.sparkline_in_7d?.price)&&c.sparkline_in_7d.price.length>=24).map(c=>[historyKey(c),c.sparkline_in_7d]));
          coins=alternative; coins.forEach(c=>{c.sparkline_in_7d=previousHistory.get(historyKey(c))||null;applyHistoricalData(c);observeLivePrice(c);}); fetchedAt=Date.now(); cacheWrite(); render(); connectMarketStream();
          setStatus('CoinLore · '+coins.length+' crypto · loghi aggiornati · grafici iniziali immediati · quotazioni ogni 60 s');
          return;
        }
      }catch(_fallback){}
      const label=err.name==='AbortError'?'connessione scaduta':(err.message||'connessione non disponibile');
      if(coins.length){ render(); setStatus('Ultimi dati salvati · aggiornamento non disponibile ('+label+'). Il prossimo aggiornamento partirà automaticamente.', true); }
      else { render(); setStatus('Impossibile caricare i 200 mercati ('+label+'). Il prossimo aggiornamento partirà automaticamente quando la connessione torna disponibile.', true); }
    }finally{ clearTimeout(timeout); loading=false; }
  }

  function startTimer(){ if(timer) clearInterval(timer); timer=setInterval(()=>{ if(document.body.classList.contains('v442-market-open')){ if(!loading && Date.now()-lastAttempt>=AUTO_REFRESH) fetchMarket(); if(!historyBusy) queueVisibleHistories(); } },5000); }
  function stopTimer(){ if(timer){ clearInterval(timer); timer=null; } }
  function open(){
    if(document.body.classList.contains('v442-market-open')) return;
    previousFocus=document.activeElement; shade.hidden=false; drawer.removeAttribute('inert'); drawer.setAttribute('aria-hidden','false');
    menu.setAttribute('aria-expanded','true'); document.body.classList.add('v442-market-open');
    close.focus({preventScroll:true});
    if(!firstOpened){ firstOpened=true; cacheRead(); if(coins.length){ render(); setStatus('Ultimi dati salvati · verifica aggiornamenti…'); } fetchMarket(); }
    else if(Date.now()-fetchedAt>CACHE_AGE) fetchMarket();
    startTimer(); connectMarketStream();
  }
  function hide(){
    if(!document.body.classList.contains('v442-market-open')) return;
    document.body.classList.remove('v442-market-open'); drawer.setAttribute('aria-hidden','true'); drawer.setAttribute('inert',''); menu.setAttribute('aria-expanded','false'); shade.hidden=true; stopTimer(); disconnectMarketStream();
    try{ (previousFocus&&previousFocus.isConnected?previousFocus:menu).focus({preventScroll:true}); }catch(_){ menu.focus(); }
  }

  menu.addEventListener('click',()=>document.body.classList.contains('v442-market-open')?hide():open());
  close.addEventListener('click',hide); shade.addEventListener('click',hide); dashboardNav.addEventListener('click',hide);
  marketNav.addEventListener('click',()=>{ search.focus(); });
  search.addEventListener('input',()=>render());
  (q('v442MarketScroll')||drawer).addEventListener('scroll',()=>{clearTimeout(historyScrollTimer);historyScrollTimer=setTimeout(queueVisibleHistories,160);},{passive:true});
  window.addEventListener('online',()=>{if(document.body.classList.contains('v442-market-open')){failedSymbols.clear();historyFailures=0;fetchMarket(true);connectMarketStream();}},{passive:true});
  document.addEventListener('visibilitychange',()=>{if(!document.hidden&&document.body.classList.contains('v442-market-open')){if(Date.now()-fetchedAt>=CACHE_AGE)fetchMarket();connectMarketStream();}});
  drawer.addEventListener('keydown',ev=>{
    if(ev.key==='Escape'){ ev.preventDefault(); hide(); return; }
    if(ev.key!=='Tab') return;
    const focusables=Array.from(drawer.querySelectorAll('button:not([disabled]),input:not([disabled]),a[href], [tabindex="0"]')).filter(el=>el.offsetParent!==null);
    if(!focusables.length) return;
    const first=focusables[0], last=focusables[focusables.length-1];
    if(ev.shiftKey && document.activeElement===first){ ev.preventDefault(); last.focus(); }
    if(!ev.shiftKey && document.activeElement===last){ ev.preventDefault(); first.focus(); }
  });
})();


/* V461: rileva ogni cambio Light/Night e lo riflette subito nel Market. */
(function(){
  'use strict';
  function syncMarketTheme(){
    if(!document.body)return;
    document.body.dataset.marketTheme=document.body.classList.contains('light')?'light':'night';
  }
  function init(){
    if(!document.body)return;
    syncMarketTheme();
    new MutationObserver(syncMarketTheme).observe(document.body,{attributes:true,attributeFilter:['class']});
    window.addEventListener('pageshow',syncMarketTheme);
  }
  if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init,{once:true});
  else init();
})();
